INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C1','kor',3,2,'u2',2,'유창하게 읽는다는 것 — 소리 내어 읽을 때 듣는 사람에게 뜻이 잘 전해지게 읽는 것이고, 남보다 빨리 읽거나 가장 큰 소리로 읽는 것이 아님',ARRAY['[4국02-01]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C2','kor',3,2,'u2',2,'띄어 읽기 표시와 띄어 읽는 자리 — ∨는 조금 쉬어 읽고 ≡는 조금 더 길게 쉬어 읽는 표시, ‘누가/무엇이’ 다음에 조금 띄어 읽고 그 말이 길면 한 번 더, 문장과 문장 사이는 조금 더 길게 쉬며, 뜻이 달라지지 않으면 쉬는 곳은 사람마다 조금씩 달라도 됨(아무 데서나는 아님)',ARRAY['[4국02-01]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C3','kor',3,2,'u2',2,'글자 대신 쓰는 그림 기호 — 복도 바닥 화살표·책꽂이 옆 책 그림·급식실 발자국처럼 긴 글 없이 무엇을 하라는 말인지 멀리서도 바쁠 때도 한눈에 알아보게 하려고 그림이나 색을 씀',ARRAY['[4국02-01]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C4','kor',3,2,'u2',2,'글 내용 확인과 스스로 점검하기 — 소리 내어 읽은 글에서 알 수 있는 것은 글에 쓰여 있는 것만이고, 녹음을 다시 들을 때는 몇 초 걸렸는지가 아니라 듣는 사람에게 뜻이 전해지게 읽었는지를 살피며, 점검은 잘못을 찾아 점수 매기는 일이 아니라 다음에 더 잘 읽으려고 하는 일',ARRAY['[4국02-01]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C5','kor',3,2,'u2',3,'장면의 분위기와 그 까닭 — 인물이 처한 상황·인물의 말이나 행동·인물의 마음을 모으면 장면의 분위기가 드러나고, 분위기나 마음을 말할 때는 글 안에서 그렇게 느낀 까닭을 함께 말함(먼저 말한 사람·많이 고른 답을 따르지 않음)',ARRAY['[4국02-01]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C6','kor',3,2,'u2',3,'분위기를 살려 읽는 방법 — 상황을 떠올리며 실감 나게, 말이나 행동에 어울리는 표정과 몸짓으로, 마음이 드러나는 목소리로 읽고(쓸쓸한 장면은 낮고 느리게, 그러나 뜻은 또렷이), 꾸며 주는 말·문장 부호도 느낌을 살려 읽으며, 장면에 어울리면 읽는 방법은 사람마다 달라도 됨',ARRAY['[4국02-01]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C7','kor',3,2,'u2',5,'장면을 떠올리며 뜻 덩어리로 읽기 — 「노란 조끼」에서 인물이 하는 일과 까닭을 글에서 찾고, 장면의 상황·말·마음을 정리해 장면이 떠오르게 뜻 덩어리로 묶어 읽기(아주 빠르게도, 한 낱말씩 다 끊어서도 아님)',ARRAY['[4국02-01]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C8','kor',3,2,'u2',5,'뜻이 비슷한 낱말 — 글에 나온 낱말(다독이다·서두르다·살피다)을 그 낱말이 들어간 줄에서 뜻을 찾아 비슷한 말(달래다·급히 하다·둘러보다)로 바꾸어 넣어 보면 뜻이 더 또렷해짐',ARRAY['[4국02-01]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C9','kor',3,2,'u2',5,'글을 읽고 생각 나누기와 배울 점 — 글을 읽고 든 생각이나 느낌은 마음이 움직인 곳이 서로 달라도 되고, 배울 점은 유명한 사람에게만 있는 것이 아니라 둘레의 사람에게도 있음',ARRAY['[4국02-01][4국05-02]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C10','kor',3,2,'u2',7,'글과 그림이 하는 일 — 글은 자세한 내용을 알려 주고 그림은 글로 알기 어려운 것을 한눈에 보여 주며, 둘을 이어 읽으면 더 잘 이해됨(그림은 꾸미려고 넣는 것이 아니고, 한쪽만 있으면 되는 것도 아님)',ARRAY['[4국01-04][4국06-01]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C11','kor',3,2,'u2',7,'색·크기·모양으로 나타내기 — 색은 서로 다른 것을 구별해 보여 주고, 크기는 중요한 것을 눈에 띄게 하며, 모양(화살표 등)은 어디에 있는지·어느 쪽인지 알려 줌; 같은 내용도 나타내는 방법은 여러 가지',ARRAY['[4국01-04][4국06-01]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C12','kor',3,2,'u2',8,'목적에 맞는 발표 주제와 내용 — 자료의 도막마다 중요한 내용을 고르고, 누구에게 왜 알려 줄지부터 정하면 넣을 내용도 정해지며, 목적과 상관없는 재미있는 것·덜 중요한 것은 넣지 않음',ARRAY['[4국01-04][4국06-01]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C13','kor',3,2,'u2',8,'발표 자료의 얼개와 꾸밈 — 제목·그림·설명을 어디에 놓을지 얼개를 먼저 짜고(맨 위 크게 쓴 제목 · 가운데 보여 주려는 그림 · 그림 아래 짧은 설명), 색과 크기는 전하려는 것이 눈에 띄게 쓰며 많이 쓸수록 좋은 것이 아님',ARRAY['[4국01-04][4국06-01]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C14','kor',3,2,'u2',8,'서로 다른 자료 보기와 의견 말하기 — 같은 내용이라도 표현과 배치가 다를 수 있어 전하려는 것이 잘 보이면 둘 다 알맞고(글이 많은 쪽·그림이 큰 쪽이 나은 것이 아님), 친구 자료에 의견을 말할 때는 잘한 곳과 더 잘 보이게 할 방법을 함께 말함',ARRAY['[4국01-04][4국06-01]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C15','kor',3,2,'u2',11,'배운 내용 실천하기 — 이야기를 소개할 그림은 흐름에서 중요한 장면이 드러난 것으로 고르고, 나타내려는 것마다 글로 쓸지 그림으로 보일지 갈라 두며, 친구 발표는 끝까지 듣고 좋았던 곳을 말해 줌',ARRAY['[4국01-04][4국06-01]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C16','kor',3,2,'u2',11,'‘것·수·줄’ 띄어쓰기 — ‘것·수·줄’은 혼자 쓰이지 못하고 다른 말에 기대어 쓰이는 말이라 앞말과 띄어 쓰고(먹을 것 · 갈 수 있다 · 탈 줄 안다), 줄넘기·수요일처럼 한 낱말 속에 들어 있을 때는 붙여 씀(기초 다지기)',ARRAY['[4국04-02](케이티처 표기)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u2-C17','kor',3,2,'u2',11,'특징이 드러나는 이름 짓기 — 물건의 생김새나 하는 일을 살펴 새 이름을 지으면, 이름에 특징이 드러나 처음 듣는 사람도 무엇인지 알 수 있음(기초 다지기)',ARRAY['[4국04-02](케이티처 표기)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X01','kor',3,'u2',ARRAY['K3-2-u2-C1','K3-2-u2-C4','K3-2-u2-C6','K3-2-u2-C15']::text[],'남보다 빨리 읽거나 몇 초 만에 다 읽는 것을 잘 읽은 것으로 여긴다','읽고 난 뒤 듣는 사람에게 무엇이 남았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X02','kor',3,'u2',ARRAY['K3-2-u2-C1','K3-2-u2-C6','K3-2-u2-C15']::text[],'처음부터 끝까지 가장 큰 소리로 읽는 것을 잘 읽은 것으로 여긴다','크기보다 뜻이 전해지는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X03','kor',3,'u2',ARRAY['K3-2-u2-C2']::text[],'쉬어 읽는 곳은 언제나 한 곳뿐이라 친구와 다르면 하나는 틀렸다고 여긴다','뜻이 달라지지 않으면 조금씩 달라도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X04','kor',3,'u2',ARRAY['K3-2-u2-C2']::text[],'아무 데서나 쉬어도 된다고 여겨 ‘누가/무엇이’ 덩어리 한가운데서 끊어 읽는다','‘무엇이’에 해당하는 말이 끝나는 곳은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X05','kor',3,'u2',ARRAY['K3-2-u2-C2','K3-2-u2-C7']::text[],'띄어 읽기를 잘하려고 한 낱말씩 모두 끊어 읽어 뜻이 흩어진다','뜻 덩어리로 묶어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X06','kor',3,'u2',ARRAY['K3-2-u2-C2']::text[],'∨(조금 쉬기)와 ≡(조금 더 길게 쉬기)를 바꾸어 알거나, 문장과 문장 사이를 짧게 쉰다','≡ 는 문장 끝 — 더 길게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X07','kor',3,'u2',ARRAY['K3-2-u2-C3']::text[],'글자 대신 그림 기호를 쓰는 까닭을 꾸미거나 글씨 쓰기가 귀찮아서라고 여긴다','멀리서도, 바쁠 때도 한눈에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X08','kor',3,'u2',ARRAY['K3-2-u2-C4','K3-2-u2-C7']::text[],'글에 쓰여 있지 않은 것(짐작한 것·값·이름)을 글에서 알 수 있다고 여긴다','그 내용이 적힌 줄을 찾을 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X09','kor',3,'u2',ARRAY['K3-2-u2-C4']::text[],'스스로 점검하기를 잘못을 찾아 점수를 매기거나 남과 견주는 일로 여긴다','점검은 다음에 더 잘 읽으려고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X10','kor',3,'u2',ARRAY['K3-2-u2-C5']::text[],'분위기나 마음을 말할 때 까닭 없이 말하거나, 먼저 말한 사람·많이 고른 답을 따른다','그렇게 느낀 까닭을 글에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X11','kor',3,'u2',ARRAY['K3-2-u2-C5','K3-2-u2-C7']::text[],'인물의 마음을 짐작할 근거로 인물의 말·행동이 아니라 날씨·때처럼 마음과 상관없는 곳을 고른다','인물이 한 말이나 행동은 어디?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X12','kor',3,'u2',ARRAY['K3-2-u2-C5','K3-2-u2-C6']::text[],'장면과 분위기를 엇갈리게 잇거나, 쓸쓸한 장면을 웃는 목소리로 읽는다','그 장면에서 인물은 무엇을 하고 있었나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X13','kor',3,'u2',ARRAY['K3-2-u2-C6']::text[],'실감 나게 읽기를 아주 크고 빠르게, 또는 들리지 않을 만큼 작게 읽는 것으로 여긴다','낮고 느리게, 그러나 뜻은 또렷이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X14','kor',3,'u2',ARRAY['K3-2-u2-C6']::text[],'분위기를 살려 읽는 방법은 하나뿐이라 서로 다르게 읽으면 하나는 틀렸다고 여긴다','장면에 어울리면 방법은 여러 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X15','kor',3,'u2',ARRAY['K3-2-u2-C4','K3-2-u2-C5','K3-2-u2-C7']::text[],'글에서 인물이 겪은 일·하는 일이나 그 까닭을 잘못 읽는다','그 일이 적힌 줄을 다시 소리 내어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X16','kor',3,'u2',ARRAY['K3-2-u2-C8']::text[],'뜻이 비슷한 낱말을 앞뒤 줄을 보지 않고 짐작해 다른 낱말의 뜻과 섞는다','그 줄에 바꾸어 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X17','kor',3,'u2',ARRAY['K3-2-u2-C9']::text[],'배울 점은 유명하거나 나이가 많은 사람에게만 있다고 여기거나, 글을 읽고 든 느낌에 정답이 있다고 여긴다','둘레의 사람에게도 · 느낌은 달라도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X18','kor',3,'u2',ARRAY['K3-2-u2-C10']::text[],'설명하는 글에 그림을 넣는 까닭을 보기 좋게 꾸미거나 글을 적게 쓰려고라고 여긴다','그림이 없으면 무엇이 어려울까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X19','kor',3,'u2',ARRAY['K3-2-u2-C10','K3-2-u2-C15']::text[],'글과 그림 가운데 한쪽만 있으면 된다고 여기거나, 그림으로 보일 것과 글로 쓸 것을 엇갈리게 고른다','글이 할 일과 그림이 할 일이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X20','kor',3,'u2',ARRAY['K3-2-u2-C11']::text[],'색·크기·모양이 하는 일(구별하기·눈에 띄게 하기·쪽 알려 주기)을 엇갈리게 안다','그 표현이 없으면 무엇을 알기 어려울까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X21','kor',3,'u2',ARRAY['K3-2-u2-C12','K3-2-u2-C15']::text[],'누구에게 왜 알려 줄지와 상관없이 재미있는 것·덜 중요한 것을 중요한 내용으로 고른다','누구에게, 왜 알려 주나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X22','kor',3,'u2',ARRAY['K3-2-u2-C13']::text[],'얼개에서 제목·그림·설명의 자리를 엇갈리게 놓거나 얼개 없이 바로 만든다','가장 먼저 눈에 들어와야 할 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X23','kor',3,'u2',ARRAY['K3-2-u2-C13']::text[],'색과 크기는 많이 쓸수록, 알록달록하고 모두 크게 쓸수록 좋다고 여긴다','모두 크면 무엇이 중요한지 보일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X24','kor',3,'u2',ARRAY['K3-2-u2-C11','K3-2-u2-C14']::text[],'같은 내용을 다르게 나타낸 자료 가운데 글이 많은 쪽이나 그림이 큰 쪽이 더 잘 만든 것이라고 여긴다','전하려는 것이 잘 보이면 둘 다 알맞아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X25','kor',3,'u2',ARRAY['K3-2-u2-C14']::text[],'친구 자료에 의견을 말할 때 잘못한 곳만 찾아 말하거나 무조건 잘했다고만 말한다','잘한 곳 + 더 잘 보이게 할 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X26','kor',3,'u2',ARRAY['K3-2-u2-C15']::text[],'친구가 발표할 때 내 차례만 준비하거나 내용과 상관없이 박수만 친다','끝까지 듣고 좋았던 곳 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X27','kor',3,'u2',ARRAY['K3-2-u2-C16']::text[],'‘것·수·줄’을 앞말에 붙여 쓰거나 뒷말에 붙여 쓴다','‘것·수·줄’ 앞뒤를 모두 살피기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X28','kor',3,'u2',ARRAY['K3-2-u2-C16']::text[],'줄넘기·수요일처럼 한 낱말 속에 든 ‘줄·수’도 띄어 써야 한다고 여긴다','혼자 떨어져 다른 말에 기댈 때만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u2-X29','kor',3,'u2',ARRAY['K3-2-u2-C17']::text[],'새 이름에 물건의 특징이 드러나지 않거나, 특징과 이름을 엇갈리게 잇는다','그 물건이 무엇을 하는지 이름에 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_basic#1','kor',3,2,'u2','L02','g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C1',1,'mc','auto','글을 「유창하게 읽는다」는 것은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X02','K3-2-u2-X05']::text[],false,'{"seq":1,"concept":"K3-2-u2-C1","difficulty":1,"kind":"mc","stem":"글을 「유창하게 읽는다」는 것은 무엇인가요?","options":[{"t":"듣는 사람에게 뜻이 잘 전해지게 읽는 것","correct":true},{"t":"남보다 빨리 읽는 것","mis":"K3-2-u2-X01"},{"t":"가장 큰 소리로 읽는 것","mis":"K3-2-u2-X02"},{"t":"한 글자씩 아주 천천히 읽는 것","mis":"K3-2-u2-X05"}],"explanation":["읽어 준 것을 듣는 사람이 있어요.","그 사람에게 뜻이 남아야 해요.","빠르기나 크기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_basic#2','kor',3,2,'u2','L02','g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C2',1,'mc','auto','∨ 표시는 어떻게 읽으라는 뜻인가요?',ARRAY['K3-2-u2-X06','K3-2-u2-X02','K3-2-u2-X01']::text[],false,'{"seq":2,"concept":"K3-2-u2-C2","difficulty":1,"kind":"mc","stem":"∨ 표시는 어떻게 읽으라는 뜻인가요?","options":[{"t":"조금 쉬어 읽는다","correct":true},{"t":"조금 더 길게 쉬어 읽는다","mis":"K3-2-u2-X06"},{"t":"소리를 크게 읽는다","mis":"K3-2-u2-X02"},{"t":"쉬지 않고 빨리 읽는다","mis":"K3-2-u2-X01"}],"explanation":["∨ 는 조금 쉬는 표시예요.","≡ 는 조금 더 길게 쉬어요.","∨ 는 조금 쉬어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_basic#3','kor',3,2,'u2','L02','g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C4',1,'mc','auto','「우산」에서 천을 받쳐 주는 가느다란 뼈대를 무엇이라고 했나요?',ARRAY['K3-2-u2-X15','K3-2-u2-X08']::text[],false,'{"seq":3,"concept":"K3-2-u2-C4","difficulty":1,"kind":"mc","stem":"「우산」에서 천을 받쳐 주는 가느다란 뼈대를 무엇이라고 했나요?","options":[{"t":"살","correct":true},{"t":"손잡이","mis":"K3-2-u2-X15"},{"t":"천","mis":"K3-2-u2-X15"},{"t":"꼭지","mis":"K3-2-u2-X08"}],"explanation":["세 번째 줄을 소리 내어 읽어요.","가느다란 뼈대라고 했어요.","살이에요."],"asset":{"type":"passage","lines":["우산은 비를 막아 주는 물건입니다.","손으로 잡는 곳을 손잡이라고 하고,","천을 받쳐 주는 가느다란 뼈대를 살이라고 합니다.","살을 펴면 천이 넓게 벌어져 비를 막습니다.","비가 그친 뒤에 젖은 우산을 그대로 접어 두면","천에 냄새가 배고 살이 녹슬기도 합니다.","그래서 우산은 펴서 말린 뒤에 접어 두어야 합니다."],"title":"설명하는 글 「우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_basic#4','kor',3,2,'u2','L02','g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C3',1,'ox','auto','복도 바닥의 오른쪽 화살표는 긴 글이 없어도 무엇을 하라는 말인지 알 수 있어요.',ARRAY['K3-2-u2-X07']::text[],false,'{"seq":4,"concept":"K3-2-u2-C3","difficulty":1,"kind":"ox","stem":"복도 바닥의 오른쪽 화살표는 긴 글이 없어도 무엇을 하라는 말인지 알 수 있어요.","answer":"O","reason_options":[{"t":"그림 기호는 한눈에 알아보게 하려고 쓰는 것이기 때문에","correct":true},{"t":"화살표는 복도를 꾸미려고 그린 것이기 때문에","mis":"K3-2-u2-X07"}],"mis":"K3-2-u2-X07","explanation":["화살표는 오른쪽을 가리켜요.","이쪽으로 걸으라는 뜻이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["복도 바닥의 오른쪽 화살표 — 이쪽으로 걸어요.","책꽂이 옆의 책 그림 — 뽑은 책은 제자리에 꽂아요.","급식실 앞의 발자국 표시 — 여기에 줄을 서요."],"title":"학교 안의 그림 기호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_basic#5','kor',3,2,'u2','L02','g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C2',2,'mc','auto','「젖은 우산을 그대로 접어 두면 천에 냄새가 뱁니다.」에서 ∨ 를 넣기에 가장 알맞은 곳은 어디인가요?',ARRAY['K3-2-u2-X04','K3-2-u2-X05']::text[],false,'{"seq":5,"concept":"K3-2-u2-C2","difficulty":2,"kind":"mc","stem":"「젖은 우산을 그대로 접어 두면 천에 냄새가 뱁니다.」에서 ∨ 를 넣기에 가장 알맞은 곳은 어디인가요?","options":[{"t":"「접어 두면」 다음","correct":true},{"t":"「젖은」 다음","mis":"K3-2-u2-X04"},{"t":"「천에」 다음","mis":"K3-2-u2-X04"},{"t":"쉬지 않고 한 번에 읽는다","mis":"K3-2-u2-X05"}],"explanation":["무엇에 대한 문장인지 찾아요.","‘젖은 우산을 그대로 접어 두면’이 한 덩어리예요.","그 덩어리가 끝나는 곳에서 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_basic#6','kor',3,2,'u2','L02','g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C4',2,'mc','auto','「우산」에서 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u2-X08']::text[],false,'{"seq":6,"concept":"K3-2-u2-C4","difficulty":2,"kind":"mc","stem":"「우산」에서 알 수 있는 것은 무엇인가요?","options":[{"t":"젖은 채로 접어 두면 살이 녹슬기도 한다","correct":true},{"t":"우산을 처음 만든 사람의 이름","mis":"K3-2-u2-X08"},{"t":"우산 하나의 값","mis":"K3-2-u2-X08"},{"t":"우산은 꼭 파란색이어야 한다","mis":"K3-2-u2-X08"}],"explanation":["글에 쓰여 있는 것만 골라요.","여섯 번째 줄에 녹이 나와요.","이름·값·색은 글에 없어요."],"asset":{"type":"passage","lines":["우산은 비를 막아 주는 물건입니다.","손으로 잡는 곳을 손잡이라고 하고,","천을 받쳐 주는 가느다란 뼈대를 살이라고 합니다.","살을 펴면 천이 넓게 벌어져 비를 막습니다.","비가 그친 뒤에 젖은 우산을 그대로 접어 두면","천에 냄새가 배고 살이 녹슬기도 합니다.","그래서 우산은 펴서 말린 뒤에 접어 두어야 합니다."],"title":"설명하는 글 「우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_basic#7','kor',3,2,'u2','L02','g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C4',2,'ox','auto','녹음한 내 목소리를 다시 들을 때는 몇 초 만에 다 읽었는지를 가장 먼저 살펴요.',ARRAY['K3-2-u2-X01']::text[],false,'{"seq":7,"concept":"K3-2-u2-C4","difficulty":2,"kind":"ox","stem":"녹음한 내 목소리를 다시 들을 때는 몇 초 만에 다 읽었는지를 가장 먼저 살펴요.","answer":"X","reason_options":[{"t":"듣는 사람에게 뜻이 전해지게 읽었는지를 살펴야 하기 때문에","correct":true},{"t":"빨리 읽을수록 유창하게 읽은 것이기 때문에","mis":"K3-2-u2-X01"}],"mis":"K3-2-u2-X01","explanation":["녹음을 처음 듣는 사람을 떠올려요.","그 사람에게 뜻이 남아야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_basic#8','kor',3,2,'u2','L02','g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C3',2,'mc','auto','급식실 앞에 발자국 표시를 그려 둔 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X07']::text[],false,'{"seq":8,"concept":"K3-2-u2-C3","difficulty":2,"kind":"mc","stem":"급식실 앞에 발자국 표시를 그려 둔 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"여기에 줄을 서라는 것을 한눈에 알게 하려고","correct":true},{"t":"바닥을 예쁘게 꾸미려고","mis":"K3-2-u2-X07"},{"t":"글씨를 쓰기 귀찮아서","mis":"K3-2-u2-X07"},{"t":"발자국 크기를 재려고","mis":"K3-2-u2-X07"}],"explanation":["발자국은 서는 자리를 보여 줘요.","바쁜 점심시간에도 한눈에 보여요.","줄 설 자리를 알려 줘요."],"asset":{"type":"passage","lines":["복도 바닥의 오른쪽 화살표 — 이쪽으로 걸어요.","책꽂이 옆의 책 그림 — 뽑은 책은 제자리에 꽂아요.","급식실 앞의 발자국 표시 — 여기에 줄을 서요."],"title":"학교 안의 그림 기호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_basic#9','kor',3,2,'u2','L02','g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C2',2,'match','auto','유창하게 읽는 방법과 그 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C2","difficulty":2,"kind":"match","stem":"유창하게 읽는 방법과 그 내용을 알맞게 이으세요.","pairs":[{"l":"‘누가/무엇이’ 다음","r":"조금 띄어 읽는다"},{"l":"‘누가/무엇이’가 길 때","r":"한 번 더 띄어 읽는다"},{"l":"문장과 문장 사이","r":"조금 더 길게 쉰다"}],"mis":"K3-2-u2-X06","explanation":["3학년 1학기에 배운 방법이에요.","덩어리가 끝나는 곳에서 쉬어요.","문장 끝은 더 길게 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_basic#10','kor',3,2,'u2','L02','g3_2_kor_u2_L02_basic','lesson_basic','K3-2-u2-C2',3,'error','auto','친구마다 쉬어 읽는 곳이 조금씩 달랐어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X03','K3-2-u2-X04']::text[],false,'{"seq":10,"concept":"K3-2-u2-C2","difficulty":3,"kind":"error","stem":"친구마다 쉬어 읽는 곳이 조금씩 달랐어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「쉬어 읽는 곳은 하나뿐이니 나랑 다르게 읽은 친구는 틀렸어.」","correct":true,"mis_target":"K3-2-u2-X03"},{"t":"친구 가 — 「뜻이 달라지지 않으면 조금씩 달라도 괜찮아.」","mis":"K3-2-u2-X03"},{"t":"친구 다 — 「그래도 덩어리 한가운데서 끊으면 뜻이 흩어져.」","mis":"K3-2-u2-X04"}],"explanation":["숨 쉬는 자리는 사람마다 조금 달라요.","뜻만 달라지지 않으면 돼요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_challenge#1','kor',3,2,'u2','L02','g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C2',2,'sa','auto','조금 더 길게 쉬어 읽으라는 표시는 ∨ 와 ≡ 가운데 무엇인가요? 표시를 그대로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u2-C2","difficulty":2,"kind":"sa","stem":"조금 더 길게 쉬어 읽으라는 표시는 ∨ 와 ≡ 가운데 무엇인가요? 표시를 그대로 쓰세요.","answer":["≡"],"explanation":["∨ 는 조금 쉬어요.","문장 끝에 붙는 표시예요.","≡ 예요."],"mis":"K3-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_challenge#2','kor',3,2,'u2','L02','g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C4',2,'mc','auto','스스로 점검하기를 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X09','K3-2-u2-X01']::text[],false,'{"seq":2,"concept":"K3-2-u2-C4","difficulty":2,"kind":"mc","stem":"스스로 점검하기를 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"다음에 더 잘 읽으려고","correct":true},{"t":"친구보다 점수가 높은지 보려고","mis":"K3-2-u2-X09"},{"t":"틀린 곳을 모두 세어 점수를 매기려고","mis":"K3-2-u2-X09"},{"t":"가장 빨리 읽은 사람을 뽑으려고","mis":"K3-2-u2-X01"}],"explanation":["점검표에는 점수가 없어요.","아쉬운 곳을 찾아 다시 읽어요.","더 잘 읽으려고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_challenge#3','kor',3,2,'u2','L02','g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C2',3,'mc','auto','「천을 받쳐 주는 가느다란 뼈대를 살이라고 합니다.」를 알맞게 띄어 읽은 것은 무엇인가요?',ARRAY['K3-2-u2-X05','K3-2-u2-X06','K3-2-u2-X04']::text[],false,'{"seq":3,"concept":"K3-2-u2-C2","difficulty":3,"kind":"mc","stem":"「천을 받쳐 주는 가느다란 뼈대를 살이라고 합니다.」를 알맞게 띄어 읽은 것은 무엇인가요?","options":[{"t":"천을 받쳐 주는 가느다란 뼈대를∨살이라고 합니다.≡","correct":true},{"t":"천을∨받쳐∨주는∨가느다란∨뼈대를∨살이라고∨합니다.≡","mis":"K3-2-u2-X05"},{"t":"천을 받쳐∨주는 가느다란 뼈대를 살이라고 합니다.∨","mis":"K3-2-u2-X06"},{"t":"천을 받쳐 주는 가느다란∨뼈대를 살이라고 합니다.≡","mis":"K3-2-u2-X04"}],"explanation":["무엇을 살이라고 하는지 덩어리를 찾아요.","그 덩어리가 끝난 뒤 쉬어요.","문장 끝은 ≡ 로 길게 쉬어요."],"asset":{"type":"passage","lines":["우산은 비를 막아 주는 물건입니다.","손으로 잡는 곳을 손잡이라고 하고,","천을 받쳐 주는 가느다란 뼈대를 살이라고 합니다.","살을 펴면 천이 넓게 벌어져 비를 막습니다.","비가 그친 뒤에 젖은 우산을 그대로 접어 두면","천에 냄새가 배고 살이 녹슬기도 합니다.","그래서 우산은 펴서 말린 뒤에 접어 두어야 합니다."],"title":"설명하는 글 「우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_challenge#4','kor',3,2,'u2','L02','g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C1',3,'ox','auto','「우산」을 한 번도 쉬지 않고 가장 빨리 읽은 친구가 가장 유창하게 읽은 친구예요.',ARRAY['K3-2-u2-X01']::text[],false,'{"seq":4,"concept":"K3-2-u2-C1","difficulty":3,"kind":"ox","stem":"「우산」을 한 번도 쉬지 않고 가장 빨리 읽은 친구가 가장 유창하게 읽은 친구예요.","answer":"X","reason_options":[{"t":"쉬지 않고 빨리 읽으면 뜻 덩어리가 보이지 않아 듣는 사람에게 뜻이 덜 전해지기 때문에","correct":true},{"t":"빠르기가 유창하게 읽기의 전부이기 때문에","mis":"K3-2-u2-X01"}],"mis":"K3-2-u2-X01","explanation":["듣는 사람을 떠올려요.","쉬어 읽어야 뜻 덩어리가 보여요.","그래서 X예요."],"asset":{"type":"passage","lines":["우산은 비를 막아 주는 물건입니다.","손으로 잡는 곳을 손잡이라고 하고,","천을 받쳐 주는 가느다란 뼈대를 살이라고 합니다.","살을 펴면 천이 넓게 벌어져 비를 막습니다.","비가 그친 뒤에 젖은 우산을 그대로 접어 두면","천에 냄새가 배고 살이 녹슬기도 합니다.","그래서 우산은 펴서 말린 뒤에 접어 두어야 합니다."],"title":"설명하는 글 「우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_challenge#5','kor',3,2,'u2','L02','g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C4',3,'error','auto','「우산」을 읽고 알 수 있는 것을 말했어요. 글에 없는 것을 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X08','K3-2-u2-X15']::text[],false,'{"seq":5,"concept":"K3-2-u2-C4","difficulty":3,"kind":"error","stem":"「우산」을 읽고 알 수 있는 것을 말했어요. 글에 없는 것을 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「우산은 비 오는 날에만 팔린대.」","correct":true,"mis_target":"K3-2-u2-X08"},{"t":"친구 가 — 「젖은 채로 접으면 천에 냄새가 밴대.」","mis":"K3-2-u2-X08"},{"t":"친구 나 — 「손으로 잡는 곳을 손잡이라고 한대.」","mis":"K3-2-u2-X15"}],"explanation":["글에 쓰여 있는 것만 골라요.","팔린다는 이야기는 글에 없어요.","친구 다가 글에 없는 것을 말했어요."],"asset":{"type":"passage","lines":["우산은 비를 막아 주는 물건입니다.","손으로 잡는 곳을 손잡이라고 하고,","천을 받쳐 주는 가느다란 뼈대를 살이라고 합니다.","살을 펴면 천이 넓게 벌어져 비를 막습니다.","비가 그친 뒤에 젖은 우산을 그대로 접어 두면","천에 냄새가 배고 살이 녹슬기도 합니다.","그래서 우산은 펴서 말린 뒤에 접어 두어야 합니다."],"title":"설명하는 글 「우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_challenge#6','kor',3,2,'u2','L02','g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C3',3,'mc','auto','책꽂이 옆에 책 그림 기호를 붙이면 어떤 점이 좋은가요?',ARRAY['K3-2-u2-X07','K3-2-u2-X08']::text[],false,'{"seq":6,"concept":"K3-2-u2-C3","difficulty":3,"kind":"mc","stem":"책꽂이 옆에 책 그림 기호를 붙이면 어떤 점이 좋은가요?","options":[{"t":"뽑은 책을 제자리에 꽂으라는 것을 글을 읽지 않아도 알 수 있다","correct":true},{"t":"책꽂이가 예뻐진다","mis":"K3-2-u2-X07"},{"t":"책을 빨리 읽게 된다","mis":"K3-2-u2-X07"},{"t":"책의 값을 알 수 있다","mis":"K3-2-u2-X08"}],"explanation":["책 그림은 할 일을 알려 줘요.","긴 글 없이도 알 수 있어요.","제자리에 꽂으라는 뜻이에요."],"asset":{"type":"passage","lines":["복도 바닥의 오른쪽 화살표 — 이쪽으로 걸어요.","책꽂이 옆의 책 그림 — 뽑은 책은 제자리에 꽂아요.","급식실 앞의 발자국 표시 — 여기에 줄을 서요."],"title":"학교 안의 그림 기호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_challenge#7','kor',3,2,'u2','L02','g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C4',3,'match','auto','녹음해 듣기의 차례와 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u2-C4","difficulty":3,"kind":"match","stem":"녹음해 듣기의 차례와 할 일을 알맞게 이으세요.","pairs":[{"l":"처음","r":"녹음을 켜고 소리 내어 읽기"},{"l":"다음","r":"녹음을 멈추고 다시 들으며 아쉬운 곳 찾기"},{"l":"마지막","r":"어떻게 읽을지 생각하고 다시 읽기"}],"mis":"K3-2-u2-X09","explanation":["읽고 → 듣고 → 다시 읽어요.","아쉬운 곳은 고칠 곳이에요.","점수가 아니라 다시 읽기로 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_challenge#8','kor',3,2,'u2','L02','g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C1',4,'mc','auto','수아는 「우산」을 빠르고 크게 읽었고, 지호는 조금 느리지만 덩어리마다 쉬어 읽었어요. 듣는 친구가 「우산을 왜 말려야 하는지」를 더 잘 알아들은 쪽과 그 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X02','K3-2-u2-X03']::text[],false,'{"seq":8,"concept":"K3-2-u2-C1","difficulty":4,"kind":"mc","stem":"수아는 「우산」을 빠르고 크게 읽었고, 지호는 조금 느리지만 덩어리마다 쉬어 읽었어요. 듣는 친구가 「우산을 왜 말려야 하는지」를 더 잘 알아들은 쪽과 그 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"지호 — 뜻 덩어리마다 쉬어 읽어 「젖은 채 접으면 냄새가 배고 녹슨다」가 또렷이 전해져서","correct":true},{"t":"수아 — 빠르게 읽어 시간이 덜 걸려서","mis":"K3-2-u2-X01"},{"t":"수아 — 큰 소리라 멀리까지 들려서","mis":"K3-2-u2-X02"},{"t":"둘 다 같다 — 같은 글을 읽었으니까","mis":"K3-2-u2-X03"}],"explanation":["듣는 사람이 무엇을 알아들었는지 봐요.","덩어리마다 쉬면 까닭이 들려요.","지호 쪽이 뜻이 전해졌어요."],"asset":{"type":"passage","lines":["우산은 비를 막아 주는 물건입니다.","손으로 잡는 곳을 손잡이라고 하고,","천을 받쳐 주는 가느다란 뼈대를 살이라고 합니다.","살을 펴면 천이 넓게 벌어져 비를 막습니다.","비가 그친 뒤에 젖은 우산을 그대로 접어 두면","천에 냄새가 배고 살이 녹슬기도 합니다.","그래서 우산은 펴서 말린 뒤에 접어 두어야 합니다."],"title":"설명하는 글 「우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_challenge#9','kor',3,2,'u2','L02','g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C2',4,'essay','teacher','「그래서 우산은 펴서 말린 뒤에 접어 두어야 합니다.」에 ∨ 를 한 곳 넣어 다시 쓰고, 왜 그곳에서 쉬었는지 쓰세요. 친구가 다른 곳에서 쉬었다면 어떻게 말해 줄지도 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C2","difficulty":4,"kind":"essay","stem":"「그래서 우산은 펴서 말린 뒤에 접어 두어야 합니다.」에 ∨ 를 한 곳 넣어 다시 쓰고, 왜 그곳에서 쉬었는지 쓰세요. 친구가 다른 곳에서 쉬었다면 어떻게 말해 줄지도 쓰세요.","answer_guide":{"answer":"예: 그래서 우산은∨펴서 말린 뒤에 접어 두어야 합니다.≡ — 무엇에 대한 문장인지 알려 주는 ‘우산은’이 끝나는 곳이라서 쉬었다. 친구가 「말린 뒤에」 다음에서 쉬었다면, 뜻이 달라지지 않으니 그렇게 읽어도 괜찮다고 말해 주겠다.","scoring_points":["∨ 를 뜻 덩어리가 끝나는 곳에 넣었는가","그곳에서 쉰 까닭을 썼는가","뜻이 달라지지 않으면 달라도 된다고 말했는가"]},"explanation":["‘무엇이’ 덩어리를 찾아요.","쉰 까닭을 덩어리로 설명해요.","다른 친구의 쉬는 곳도 인정해요."],"asset":{"type":"passage","lines":["우산은 비를 막아 주는 물건입니다.","손으로 잡는 곳을 손잡이라고 하고,","천을 받쳐 주는 가느다란 뼈대를 살이라고 합니다.","살을 펴면 천이 넓게 벌어져 비를 막습니다.","비가 그친 뒤에 젖은 우산을 그대로 접어 두면","천에 냄새가 배고 살이 녹슬기도 합니다.","그래서 우산은 펴서 말린 뒤에 접어 두어야 합니다."],"title":"설명하는 글 「우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L02_challenge#10','kor',3,2,'u2','L02','g3_2_kor_u2_L02_challenge','lesson_challenge','K3-2-u2-C3',4,'essay','teacher','우리 교실이나 복도에서 볼 수 있는 그림 기호를 하나 떠올려(또는 새로 생각해) 쓰고, 그것이 무엇을 하라는 뜻인지, 글 대신 그림을 쓰면 무엇이 좋은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C3","difficulty":4,"kind":"essay","stem":"우리 교실이나 복도에서 볼 수 있는 그림 기호를 하나 떠올려(또는 새로 생각해) 쓰고, 그것이 무엇을 하라는 뜻인지, 글 대신 그림을 쓰면 무엇이 좋은지 쓰세요.","answer_guide":{"answer":"예: 교실 뒤 쓰레기통 위에 붙인 종이컵 그림 — 종이컵은 이 통에 버리라는 뜻이다. 청소 시간에 바쁠 때도 글을 읽지 않고 그림만 보면 어디에 버릴지 한눈에 알 수 있어서 좋다.","scoring_points":["그림 기호를 하나 썼는가","그 기호가 무엇을 하라는 뜻인지 썼는가","한눈에 알아볼 수 있다는 좋은 점을 썼는가"]},"explanation":["교실 안을 떠올려요.","그 기호가 시키는 일을 써요.","글보다 빨리 알아보는 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_basic#1','kor',3,2,'u2','L03','g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',1,'mc','auto','장면에서 느껴지는 기분을 무엇이라고 하나요?',ARRAY['K3-2-u2-X15','K3-2-u2-X06']::text[],false,'{"seq":1,"concept":"K3-2-u2-C5","difficulty":1,"kind":"mc","stem":"장면에서 느껴지는 기분을 무엇이라고 하나요?","options":[{"t":"분위기","correct":true},{"t":"줄거리","mis":"K3-2-u2-X15"},{"t":"제목","mis":"K3-2-u2-X15"},{"t":"띄어 읽기","mis":"K3-2-u2-X06"}],"explanation":["같은 이야기도 장면마다 기분이 달라요.","그 기분을 부르는 말이 있어요.","분위기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_basic#2','kor',3,2,'u2','L03','g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',1,'mc','auto','「말린 실내화」 ①에서 유빈이에게 일어난 일은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":2,"concept":"K3-2-u2-C5","difficulty":1,"kind":"mc","stem":"「말린 실내화」 ①에서 유빈이에게 일어난 일은 무엇인가요?","options":[{"t":"주머니가 물에 잠겨 실내화가 젖었다","correct":true},{"t":"신발주머니를 집에 두고 왔다","mis":"K3-2-u2-X15"},{"t":"실내화를 친구에게 빌려주었다","mis":"K3-2-u2-X15"},{"t":"물웅덩이에 넘어져 다쳤다","mis":"K3-2-u2-X15"}],"explanation":["두 번째 줄과 세 번째 줄을 읽어요.","주머니가 물에 잠겼어요.","그래서 실내화가 젖었어요."],"asset":{"type":"passage","lines":["비가 쏟아지던 날이었다.","유빈이는 신발주머니를 든 채 물웅덩이를 건너뛰었다.","철벅. 주머니가 그만 물에 잠겼다.","교실에서 꺼내 보니 실내화가 흠뻑 젖어 있었다.","유빈이는 실내화를 신발장 위에 올려놓고 조용히 자리에 앉았다.","하루 내내 양말이 축축했지만 아무에게도 말하지 않았다."],"title":"이야기 「말린 실내화」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_basic#3','kor',3,2,'u2','L03','g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',1,'sa','auto','다음 날 아침 실내화 안쪽에 들어 있던 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u2-C5","difficulty":1,"kind":"sa","stem":"다음 날 아침 실내화 안쪽에 들어 있던 것은 무엇인가요? 두 글자로 쓰세요.","answer":["쪽지"],"explanation":["「말린 실내화」 ② 세 번째 줄을 읽어요.","접힌 것이 들어 있었어요.","쪽지예요."],"asset":{"type":"passage","lines":["다음 날 아침, 유빈이는 신발장 앞에서 걸음을 멈추었다.","실내화가 뽀송하게 말라 제자리에 놓여 있었다.","안쪽에 접힌 쪽지가 하나 들어 있었다.","“볕 드는 창가에 두었어. 이제 안 축축해.”","유빈이가 고개를 들자 다올이가 씩 웃고 있었다.","창밖에는 비가 그쳐 있었다."],"title":"이야기 「말린 실내화」 ②"},"mis":"K3-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_basic#4','kor',3,2,'u2','L03','g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C6',1,'ox','auto','분위기를 살려 읽을 때는 인물의 마음이 드러나는 목소리로 읽어요.',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":4,"concept":"K3-2-u2-C6","difficulty":1,"kind":"ox","stem":"분위기를 살려 읽을 때는 인물의 마음이 드러나는 목소리로 읽어요.","answer":"O","reason_options":[{"t":"목소리에 마음이 실려야 장면의 분위기가 듣는 사람에게 전해지기 때문에","correct":true},{"t":"목소리는 언제나 똑같이 해야 하기 때문에","mis":"K3-2-u2-X12"}],"mis":"K3-2-u2-X12","explanation":["읽는 방법 셋 가운데 하나예요.","상황 · 표정과 몸짓 · 목소리예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_basic#5','kor',3,2,'u2','L03','g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',2,'mc','auto','「말린 실내화」 ①에서 유빈이의 마음을 짐작할 수 있는 곳은 어디인가요?',ARRAY['K3-2-u2-X11']::text[],false,'{"seq":5,"concept":"K3-2-u2-C5","difficulty":2,"kind":"mc","stem":"「말린 실내화」 ①에서 유빈이의 마음을 짐작할 수 있는 곳은 어디인가요?","options":[{"t":"“아무에게도 말하지 않았다”","correct":true},{"t":"“비가 쏟아지던 날이었다”","mis":"K3-2-u2-X11"},{"t":"“철벅.”","mis":"K3-2-u2-X11"},{"t":"“교실에서 꺼내 보니”","mis":"K3-2-u2-X11"}],"explanation":["인물의 말이나 행동을 찾아요.","날씨나 소리에는 마음이 없어요.","혼자 참은 행동에서 마음이 보여요."],"asset":{"type":"passage","lines":["비가 쏟아지던 날이었다.","유빈이는 신발주머니를 든 채 물웅덩이를 건너뛰었다.","철벅. 주머니가 그만 물에 잠겼다.","교실에서 꺼내 보니 실내화가 흠뻑 젖어 있었다.","유빈이는 실내화를 신발장 위에 올려놓고 조용히 자리에 앉았다.","하루 내내 양말이 축축했지만 아무에게도 말하지 않았다."],"title":"이야기 「말린 실내화」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_basic#6','kor',3,2,'u2','L03','g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',2,'match','auto','「말린 실내화」의 장면과 어울리는 분위기를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u2-C5","difficulty":2,"kind":"match","stem":"「말린 실내화」의 장면과 어울리는 분위기를 알맞게 이으세요.","pairs":[{"l":"축축한 양말로 하루를 보낸 장면","r":"가라앉고 쓸쓸하다"},{"l":"마른 실내화를 발견한 장면","r":"마음이 놓이고 따뜻하다"},{"l":"물웅덩이를 건너뛰던 장면","r":"서두르고 아슬아슬하다"}],"mis":"K3-2-u2-X12","explanation":["그 장면에서 유빈이가 무엇을 했는지 떠올려요.","혼자 참음 · 손길 · 건너뜀이에요.","셋 다 글 안에 까닭이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_basic#7','kor',3,2,'u2','L03','g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C6',2,'mc','auto','가라앉고 쓸쓸한 장면을 읽는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X13','K3-2-u2-X12']::text[],false,'{"seq":7,"concept":"K3-2-u2-C6","difficulty":2,"kind":"mc","stem":"가라앉고 쓸쓸한 장면을 읽는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"낮고 느리게, 그러나 뜻이 또렷이 들리게 읽는다","correct":true},{"t":"가장 크고 빠르게 읽는다","mis":"K3-2-u2-X13"},{"t":"들리지 않을 만큼 아주 작게 읽는다","mis":"K3-2-u2-X13"},{"t":"웃는 목소리로 신나게 읽는다","mis":"K3-2-u2-X12"}],"explanation":["너무 커도, 너무 작아도 어울리지 않아요.","낮고 느리게 읽어요.","그래도 뜻은 들려야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_basic#8','kor',3,2,'u2','L03','g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C5',2,'ox','auto','분위기를 말할 때는 친구들이 가장 많이 고른 답을 따라 말하면 돼요.',ARRAY['K3-2-u2-X10']::text[],false,'{"seq":8,"concept":"K3-2-u2-C5","difficulty":2,"kind":"ox","stem":"분위기를 말할 때는 친구들이 가장 많이 고른 답을 따라 말하면 돼요.","answer":"X","reason_options":[{"t":"그렇게 느낀 까닭을 글에서 찾아 함께 말해야 하기 때문에","correct":true},{"t":"많이 고른 답이 언제나 맞기 때문에","mis":"K3-2-u2-X10"}],"mis":"K3-2-u2-X10","explanation":["예하와 우담이는 예상이 달랐어요.","까닭을 말해서 서로 알아들었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_basic#9','kor',3,2,'u2','L03','g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C6',2,'mc','auto','「흠뻑 젖어 있었다」의 「흠뻑」을 느낌을 살려 읽는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X13','K3-2-u2-X12']::text[],false,'{"seq":9,"concept":"K3-2-u2-C6","difficulty":2,"kind":"mc","stem":"「흠뻑 젖어 있었다」의 「흠뻑」을 느낌을 살려 읽는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"물에 푹 젖은 느낌이 들게 힘주어 읽는다","correct":true},{"t":"아주 빠르게 읽고 넘어간다","mis":"K3-2-u2-X01"},{"t":"들리지 않게 작게 읽는다","mis":"K3-2-u2-X13"},{"t":"웃음소리를 내며 읽는다","mis":"K3-2-u2-X12"}],"explanation":["꾸며 주는 말은 느낌을 살려 읽어요.","흠뻑은 아주 많이 젖은 모양이에요.","그 느낌이 들게 읽어요."],"asset":{"type":"passage","lines":["비가 쏟아지던 날이었다.","유빈이는 신발주머니를 든 채 물웅덩이를 건너뛰었다.","철벅. 주머니가 그만 물에 잠겼다.","교실에서 꺼내 보니 실내화가 흠뻑 젖어 있었다.","유빈이는 실내화를 신발장 위에 올려놓고 조용히 자리에 앉았다.","하루 내내 양말이 축축했지만 아무에게도 말하지 않았다."],"title":"이야기 「말린 실내화」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_basic#10','kor',3,2,'u2','L03','g3_2_kor_u2_L03_basic','lesson_basic','K3-2-u2-C6',3,'error','auto','나겸이와 한울이가 같은 장면을 다르게 읽은 것을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X14']::text[],false,'{"seq":10,"concept":"K3-2-u2-C6","difficulty":3,"kind":"error","stem":"나겸이와 한울이가 같은 장면을 다르게 읽은 것을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「둘이 다르게 읽었으니 한 명은 틀리게 읽은 거야.」","correct":true,"mis_target":"K3-2-u2-X14"},{"t":"친구 가 — 「둘 다 쓸쓸한 마음이 전해졌으니 알맞게 읽었어.」","mis":"K3-2-u2-X14"},{"t":"친구 다 — 「장면에 어울리면 읽는 방법은 여러 가지야.」","mis":"K3-2-u2-X14"}],"explanation":["읽은 방법은 달라요.","그런데 같은 마음이 전해졌어요.","친구 나가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"나겸","text":"“아무에게도 말하지 않았다” 앞에서 한 번 더 쉬고 읽었어."},{"who":"한울","text":"나는 쉬지 않고, 대신 목소리를 더 낮춰서 읽었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_challenge#1','kor',3,2,'u2','L03','g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C5',2,'sa','auto','장면의 분위기는 인물이 처한 상황, 인물의 말이나 행동, 그리고 인물의 ○○을 모으면 드러나요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u2-C5","difficulty":2,"kind":"sa","stem":"장면의 분위기는 인물이 처한 상황, 인물의 말이나 행동, 그리고 인물의 ○○을 모으면 드러나요. ○○에 들어갈 두 글자를 쓰세요.","answer":["마음"],"explanation":["세 가지를 모아요.","상황 · 말이나 행동 · 하나 더예요.","마음이에요."],"mis":"K3-2-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_challenge#2','kor',3,2,'u2','L03','g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C15',2,'mc','auto','실내화를 말려 준 사람은 누구인지, 글에서 알 수 있는 까닭과 함께 고르세요.',ARRAY['K3-2-u2-X15','K3-2-u2-X08']::text[],false,'{"seq":2,"concept":"K3-2-u2-C15","difficulty":2,"kind":"mc","stem":"실내화를 말려 준 사람은 누구인지, 글에서 알 수 있는 까닭과 함께 고르세요.","options":[{"t":"다올 — 유빈이가 고개를 들자 다올이가 씩 웃고 있었다","correct":true},{"t":"유빈 — 신발장 위에 올려놓았다","mis":"K3-2-u2-X15"},{"t":"선생님 — 다음 날 아침이었다","mis":"K3-2-u2-X08"},{"t":"알 수 없다 — 이름이 쪽지에 없다","mis":"K3-2-u2-X08"}],"explanation":["쪽지 다음 줄을 읽어요.","고개를 들자 누가 웃고 있었나요?","다올이예요."],"asset":{"type":"passage","lines":["다음 날 아침, 유빈이는 신발장 앞에서 걸음을 멈추었다.","실내화가 뽀송하게 말라 제자리에 놓여 있었다.","안쪽에 접힌 쪽지가 하나 들어 있었다.","“볕 드는 창가에 두었어. 이제 안 축축해.”","유빈이가 고개를 들자 다올이가 씩 웃고 있었다.","창밖에는 비가 그쳐 있었다."],"title":"이야기 「말린 실내화」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_challenge#3','kor',3,2,'u2','L03','g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C5',3,'mc','auto','「말린 실내화」 ②의 분위기를 까닭과 함께 바르게 말한 것은 무엇인가요?',ARRAY['K3-2-u2-X11','K3-2-u2-X10','K3-2-u2-X12']::text[],false,'{"seq":3,"concept":"K3-2-u2-C5","difficulty":3,"kind":"mc","stem":"「말린 실내화」 ②의 분위기를 까닭과 함께 바르게 말한 것은 무엇인가요?","options":[{"t":"마음이 놓이고 따뜻하다 — 혼자 참던 유빈이에게 다올이가 말없이 실내화를 말려 주었으니까","correct":true},{"t":"가라앉고 쓸쓸하다 — 아침이라서","mis":"K3-2-u2-X11"},{"t":"신나고 시끌시끌하다 — 친구들이 가장 많이 그렇게 골랐으니까","mis":"K3-2-u2-X10"},{"t":"무섭고 아슬아슬하다 — 쪽지가 접혀 있어서","mis":"K3-2-u2-X12"}],"explanation":["분위기에는 까닭이 따라와요.","까닭은 인물의 상황과 행동에서 찾아요.","말없는 손길이 따뜻함의 까닭이에요."],"asset":{"type":"passage","lines":["다음 날 아침, 유빈이는 신발장 앞에서 걸음을 멈추었다.","실내화가 뽀송하게 말라 제자리에 놓여 있었다.","안쪽에 접힌 쪽지가 하나 들어 있었다.","“볕 드는 창가에 두었어. 이제 안 축축해.”","유빈이가 고개를 들자 다올이가 씩 웃고 있었다.","창밖에는 비가 그쳐 있었다."],"title":"이야기 「말린 실내화」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_challenge#4','kor',3,2,'u2','L03','g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C5',3,'ox','auto','「창밖에는 비가 그쳐 있었다」는 유빈이의 마음이 달라진 것과 어울리는 장면이에요.',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":4,"concept":"K3-2-u2-C5","difficulty":3,"kind":"ox","stem":"「창밖에는 비가 그쳐 있었다」는 유빈이의 마음이 달라진 것과 어울리는 장면이에요.","answer":"O","reason_options":[{"t":"쏟아지던 비가 그친 것이 혼자 참던 마음이 풀린 장면과 함께 그려지기 때문에","correct":true},{"t":"날씨는 이야기와 아무 상관이 없기 때문에","mis":"K3-2-u2-X12"}],"mis":"K3-2-u2-X12","explanation":["앞부분은 비가 쏟아졌어요.","뒷부분은 비가 그쳤어요.","마음이 풀린 장면과 어울려요."],"asset":{"type":"passage","lines":["다음 날 아침, 유빈이는 신발장 앞에서 걸음을 멈추었다.","실내화가 뽀송하게 말라 제자리에 놓여 있었다.","안쪽에 접힌 쪽지가 하나 들어 있었다.","“볕 드는 창가에 두었어. 이제 안 축축해.”","유빈이가 고개를 들자 다올이가 씩 웃고 있었다.","창밖에는 비가 그쳐 있었다."],"title":"이야기 「말린 실내화」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_challenge#5','kor',3,2,'u2','L03','g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C5',3,'error','auto','「말린 실내화」 ①의 분위기를 두고 말했어요. 까닭을 알맞게 대지 못한 친구는 누구인가요?',ARRAY['K3-2-u2-X10','K3-2-u2-X11']::text[],false,'{"seq":5,"concept":"K3-2-u2-C5","difficulty":3,"kind":"error","stem":"「말린 실내화」 ①의 분위기를 두고 말했어요. 까닭을 알맞게 대지 못한 친구는 누구인가요?","options":[{"t":"친구 다 — 「쓸쓸해. 왜냐하면 내가 먼저 말했으니까.」","correct":true,"mis_target":"K3-2-u2-X10"},{"t":"친구 가 — 「쓸쓸해. 양말이 축축한데도 혼자 참았으니까.」","mis":"K3-2-u2-X10"},{"t":"친구 나 — 「가라앉아. 조용히 자리에 앉았다고 했으니까.」","mis":"K3-2-u2-X11"}],"explanation":["까닭은 글 안에 있어야 해요.","먼저 말한 것은 까닭이 아니에요.","친구 다가 까닭을 대지 못했어요."],"asset":{"type":"passage","lines":["비가 쏟아지던 날이었다.","유빈이는 신발주머니를 든 채 물웅덩이를 건너뛰었다.","철벅. 주머니가 그만 물에 잠겼다.","교실에서 꺼내 보니 실내화가 흠뻑 젖어 있었다.","유빈이는 실내화를 신발장 위에 올려놓고 조용히 자리에 앉았다.","하루 내내 양말이 축축했지만 아무에게도 말하지 않았다."],"title":"이야기 「말린 실내화」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_challenge#6','kor',3,2,'u2','L03','g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C6',3,'mc','auto','“볕 드는 창가에 두었어. 이제 안 축축해.”를 읽는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X13','K3-2-u2-X12','K3-2-u2-X01']::text[],false,'{"seq":6,"concept":"K3-2-u2-C6","difficulty":3,"kind":"mc","stem":"“볕 드는 창가에 두었어. 이제 안 축축해.”를 읽는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"친구를 챙기는 다정한 목소리로 부드럽게 읽는다","correct":true},{"t":"화가 난 듯 큰 소리로 읽는다","mis":"K3-2-u2-X13"},{"t":"쓸쓸하게 한숨 쉬듯 읽는다","mis":"K3-2-u2-X12"},{"t":"쉬지 않고 아주 빠르게 읽는다","mis":"K3-2-u2-X01"}],"explanation":["쪽지를 쓴 사람은 다올이에요.","젖은 실내화를 말려 준 마음이에요.","다정한 목소리가 어울려요."],"asset":{"type":"passage","lines":["다음 날 아침, 유빈이는 신발장 앞에서 걸음을 멈추었다.","실내화가 뽀송하게 말라 제자리에 놓여 있었다.","안쪽에 접힌 쪽지가 하나 들어 있었다.","“볕 드는 창가에 두었어. 이제 안 축축해.”","유빈이가 고개를 들자 다올이가 씩 웃고 있었다.","창밖에는 비가 그쳐 있었다."],"title":"이야기 「말린 실내화」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_challenge#7','kor',3,2,'u2','L03','g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C6',3,'match','auto','분위기를 살려 읽는 방법과 「말린 실내화」에서 해 볼 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u2-C6","difficulty":3,"kind":"match","stem":"분위기를 살려 읽는 방법과 「말린 실내화」에서 해 볼 일을 알맞게 이으세요.","pairs":[{"l":"상황을 떠올리며 실감 나게","r":"비 오는 길에서 물웅덩이를 건너뛰는 모습을 떠올리며 읽기"},{"l":"어울리는 표정과 몸짓으로","r":"고개를 들며 놀란 얼굴로 읽기"},{"l":"마음이 드러나는 목소리로","r":"혼자 참는 마음이 들리게 낮은 목소리로 읽기"}],"mis":"K3-2-u2-X12","explanation":["방법마다 할 일이 달라요.","상황 · 표정과 몸짓 · 목소리예요.","장면에 맞게 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_challenge#8','kor',3,2,'u2','L03','g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C6',4,'mc','auto','「하루 내내 양말이 축축했지만 아무에게도 말하지 않았다.」를 한 친구는 「아무에게도」 앞에서 한 번 더 쉬고, 다른 친구는 쉬지 않고 목소리를 낮춰 읽었어요. 두 낭독을 가장 알맞게 본 것은 무엇인가요?',ARRAY['K3-2-u2-X14','K3-2-u2-X13']::text[],false,'{"seq":8,"concept":"K3-2-u2-C6","difficulty":4,"kind":"mc","stem":"「하루 내내 양말이 축축했지만 아무에게도 말하지 않았다.」를 한 친구는 「아무에게도」 앞에서 한 번 더 쉬고, 다른 친구는 쉬지 않고 목소리를 낮춰 읽었어요. 두 낭독을 가장 알맞게 본 것은 무엇인가요?","options":[{"t":"둘 다 혼자 참는 마음이 전해지면 알맞다 — 쉬기와 낮은 목소리는 같은 마음을 살리는 다른 방법이다","correct":true},{"t":"쉬어 읽은 쪽만 맞다 — 띄어 읽기가 가장 중요하니까","mis":"K3-2-u2-X14"},{"t":"목소리를 낮춘 쪽만 맞다 — 쉬면 느려지니까","mis":"K3-2-u2-X14"},{"t":"둘 다 틀렸다 — 크게 읽어야 실감 나니까","mis":"K3-2-u2-X13"}],"explanation":["읽은 방법이 서로 달라요.","전해진 마음을 견주어요.","같은 마음이면 둘 다 알맞아요."],"asset":{"type":"passage","lines":["비가 쏟아지던 날이었다.","유빈이는 신발주머니를 든 채 물웅덩이를 건너뛰었다.","철벅. 주머니가 그만 물에 잠겼다.","교실에서 꺼내 보니 실내화가 흠뻑 젖어 있었다.","유빈이는 실내화를 신발장 위에 올려놓고 조용히 자리에 앉았다.","하루 내내 양말이 축축했지만 아무에게도 말하지 않았다."],"title":"이야기 「말린 실내화」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_challenge#9','kor',3,2,'u2','L03','g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C5',4,'essay','teacher','「말린 실내화」에서 장면 하나를 골라, 인물이 처한 상황·인물의 말이나 행동·인물의 마음을 차례로 쓰고, 그 장면의 분위기를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C5","difficulty":4,"kind":"essay","stem":"「말린 실내화」에서 장면 하나를 골라, 인물이 처한 상황·인물의 말이나 행동·인물의 마음을 차례로 쓰고, 그 장면의 분위기를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 장면 — 축축한 양말로 하루를 보낸 장면. 상황 — 실내화가 흠뻑 젖었다. 행동 — 아무에게도 말하지 않고 조용히 자리에 앉았다. 마음 — 불편하지만 혼자 참는 마음. 분위기 — 가라앉고 쓸쓸하다. 젖은 양말로 하루 내내 혼자 참고 있었기 때문이다.","scoring_points":["장면을 하나 골랐는가","상황·말이나 행동·마음을 글에서 찾아 썼는가","분위기를 까닭과 함께 썼는가"]},"explanation":["장면부터 골라요.","세 가지를 글에서 찾아요.","분위기와 까닭을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L03_challenge#10','kor',3,2,'u2','L03','g3_2_kor_u2_L03_challenge','lesson_challenge','K3-2-u2-C6',4,'essay','teacher','「유빈이가 고개를 들자 다올이가 씩 웃고 있었다.」를 분위기를 살려 읽는다면 어떤 목소리·표정·빠르기로 읽을지 쓰고, 그렇게 읽는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C6","difficulty":4,"kind":"essay","stem":"「유빈이가 고개를 들자 다올이가 씩 웃고 있었다.」를 분위기를 살려 읽는다면 어떤 목소리·표정·빠르기로 읽을지 쓰고, 그렇게 읽는 까닭을 쓰세요.","answer_guide":{"answer":"예: 고마움과 놀람이 섞인 밝고 따뜻한 목소리로, 고개를 드는 몸짓과 놀란 표정을 하며, 「씩 웃고」에서는 조금 천천히 읽겠다. 혼자 참던 유빈이가 말려 준 사람이 다올이라는 걸 알게 된 장면이라 마음이 놓이고 따뜻한 분위기이기 때문이다.","scoring_points":["목소리를 썼는가","표정이나 몸짓, 빠르기를 썼는가","장면의 분위기와 이어 까닭을 썼는가"]},"explanation":["장면의 분위기를 먼저 떠올려요.","목소리 · 표정 · 빠르기를 정해요.","까닭은 장면에서 찾아요."],"asset":{"type":"passage","lines":["다음 날 아침, 유빈이는 신발장 앞에서 걸음을 멈추었다.","실내화가 뽀송하게 말라 제자리에 놓여 있었다.","안쪽에 접힌 쪽지가 하나 들어 있었다.","“볕 드는 창가에 두었어. 이제 안 축축해.”","유빈이가 고개를 들자 다올이가 씩 웃고 있었다.","창밖에는 비가 그쳐 있었다."],"title":"이야기 「말린 실내화」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_basic#1','kor',3,2,'u2','L05','g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',1,'mc','auto','「노란 조끼」를 입은 분이 하는 일은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":1,"concept":"K3-2-u2-C7","difficulty":1,"kind":"mc","stem":"「노란 조끼」를 입은 분이 하는 일은 무엇인가요?","options":[{"t":"건널목에서 차를 세우고 아이들을 건너게 한다","correct":true},{"t":"아이들을 태우고 학교까지 데려다준다","mis":"K3-2-u2-X15"},{"t":"학교 앞 길을 쓸어 준다","mis":"K3-2-u2-X15"},{"t":"노란 조끼를 만들어 판다","mis":"K3-2-u2-X15"}],"explanation":["두 번째 줄을 읽어요.","건널목을 지키는 분이에요.","차를 세우고 건너게 해요."],"asset":{"type":"passage","lines":["해가 뜨기 전, 길 건너에 노란 조끼가 서 있다.","우리 학교 건널목을 지키는 분이다.","비가 오는 날에도, 눈이 쌓인 날에도 그 자리를 비운 적이 없다.","아이들이 뛰어오면 손을 들어 차를 세우고 어깨를 다독여 준다.","“천천히 와도 돼. 서두르지 않아도 돼.”"],"title":"글 「노란 조끼」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_basic#2','kor',3,2,'u2','L05','g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C8',1,'match','auto','낱말과 뜻이 비슷한 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u2-C8","difficulty":1,"kind":"match","stem":"낱말과 뜻이 비슷한 말을 알맞게 이으세요.","pairs":[{"l":"다독이다","r":"달래다"},{"l":"서두르다","r":"급히 하다"},{"l":"살피다","r":"둘러보다"}],"mis":"K3-2-u2-X16","explanation":["그 낱말이 든 줄을 읽어요.","비슷한 말을 넣어 봐요.","뜻이 통하면 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_basic#3','kor',3,2,'u2','L05','g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C9',1,'ox','auto','배울 점은 아주 유명한 사람에게만 있어요.',ARRAY['K3-2-u2-X17']::text[],false,'{"seq":3,"concept":"K3-2-u2-C9","difficulty":1,"kind":"ox","stem":"배울 점은 아주 유명한 사람에게만 있어요.","answer":"X","reason_options":[{"t":"「노란 조끼」처럼 둘레의 사람에게도 배울 점이 있기 때문에","correct":true},{"t":"이름난 사람만 열심히 살기 때문에","mis":"K3-2-u2-X17"}],"mis":"K3-2-u2-X17","explanation":["노란 조끼는 이름난 사람이 아니에요.","그런데도 배울 점이 있었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_basic#4','kor',3,2,'u2','L05','g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',1,'mc','auto','장면을 떠올리며 유창하게 읽는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X05','K3-2-u2-X02']::text[],false,'{"seq":4,"concept":"K3-2-u2-C7","difficulty":1,"kind":"mc","stem":"장면을 떠올리며 유창하게 읽는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"장면이 떠오르게 뜻 덩어리로 묶어 읽는다","correct":true},{"t":"한 글자도 안 틀리게 아주 빠르게 읽는다","mis":"K3-2-u2-X01"},{"t":"한 낱말씩 모두 끊어 아주 천천히 읽는다","mis":"K3-2-u2-X05"},{"t":"처음부터 끝까지 가장 큰 소리로 읽는다","mis":"K3-2-u2-X02"}],"explanation":["듣는 사람 머릿속에 장면이 그려져야 해요.","너무 빠르거나 다 끊으면 뜻이 흩어져요.","뜻 덩어리로 묶어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_basic#5','kor',3,2,'u2','L05','g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',2,'mc','auto','「노란 조끼」에서 알 수 있는 것은 무엇인가요?',ARRAY['K3-2-u2-X08']::text[],false,'{"seq":5,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"「노란 조끼」에서 알 수 있는 것은 무엇인가요?","options":[{"t":"비 오는 날에도 그 자리에 있었다","correct":true},{"t":"몇 해 동안 이 일을 했는지","mis":"K3-2-u2-X08"},{"t":"어느 동네에 사는지","mis":"K3-2-u2-X08"},{"t":"조끼를 어디에서 샀는지","mis":"K3-2-u2-X08"}],"explanation":["글에 쓰여 있는 것만 골라요.","세 번째 줄에 비 오는 날이 나와요.","나머지는 글에 없어요."],"asset":{"type":"passage","lines":["해가 뜨기 전, 길 건너에 노란 조끼가 서 있다.","우리 학교 건널목을 지키는 분이다.","비가 오는 날에도, 눈이 쌓인 날에도 그 자리를 비운 적이 없다.","아이들이 뛰어오면 손을 들어 차를 세우고 어깨를 다독여 준다.","“천천히 와도 돼. 서두르지 않아도 돼.”"],"title":"글 「노란 조끼」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_basic#6','kor',3,2,'u2','L05','g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C8',2,'mc','auto','「서두르지 않아도 돼.」의 「서두르지」를 비슷한 말로 바꾼 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":6,"concept":"K3-2-u2-C8","difficulty":2,"kind":"mc","stem":"「서두르지 않아도 돼.」의 「서두르지」를 비슷한 말로 바꾼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"급히 하지","correct":true},{"t":"둘러보지","mis":"K3-2-u2-X16"},{"t":"달래지","mis":"K3-2-u2-X16"},{"t":"멈추지","mis":"K3-2-u2-X16"}],"explanation":["서두르다는 급하게 하는 거예요.","바꾸어 넣어 읽어 봐요.","「급히 하지 않아도 돼」가 통해요."],"asset":{"type":"passage","lines":["해가 뜨기 전, 길 건너에 노란 조끼가 서 있다.","우리 학교 건널목을 지키는 분이다.","비가 오는 날에도, 눈이 쌓인 날에도 그 자리를 비운 적이 없다.","아이들이 뛰어오면 손을 들어 차를 세우고 어깨를 다독여 준다.","“천천히 와도 돼. 서두르지 않아도 돼.”"],"title":"글 「노란 조끼」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_basic#7','kor',3,2,'u2','L05','g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',2,'mc','auto','노란 조끼를 입은 분이 하루도 빠지지 않은 까닭으로 글에 나온 것은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":7,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"노란 조끼를 입은 분이 하루도 빠지지 않은 까닭으로 글에 나온 것은 무엇인가요?","options":[{"t":"자기가 없는 날 그 자리를 살필 사람이 걱정되어서","correct":true},{"t":"아침에 일어나는 것이 쉬워서","mis":"K3-2-u2-X15"},{"t":"노란 조끼가 마음에 들어서","mis":"K3-2-u2-X15"},{"t":"꽃가루를 좋아해서","mis":"K3-2-u2-X15"}],"explanation":["뒷부분 세 번째 줄을 읽어요.","“내가 없는 날, 누가 여기를 살피지?”예요.","그 자리가 걱정되어서예요."],"asset":{"type":"passage","lines":["처음에는 이른 아침에 일어나는 일이 가장 힘들었다고 한다.","그래도 하루도 빠지지 않은 까닭을 이렇게 말했다.","“내가 없는 날, 누가 여기를 살피지?”","봄에는 꽃가루가 날리고 겨울에는 손이 얼었다.","그래도 노란 조끼는 늘 같은 곳에 서 있었다.","아이들은 이제 멀리서도 그 조끼를 알아본다."],"title":"글 「노란 조끼」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_basic#8','kor',3,2,'u2','L05','g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C9',2,'ox','auto','윤성·다올·예하가 마음이 움직인 곳이 서로 다르니 두 명은 잘못 읽은 거예요.',ARRAY['K3-2-u2-X17']::text[],false,'{"seq":8,"concept":"K3-2-u2-C9","difficulty":2,"kind":"ox","stem":"윤성·다올·예하가 마음이 움직인 곳이 서로 다르니 두 명은 잘못 읽은 거예요.","answer":"X","reason_options":[{"t":"글을 읽고 든 생각이나 느낌은 사람마다 달라도 되기 때문에","correct":true},{"t":"느낌에는 하나의 정답이 있기 때문에","mis":"K3-2-u2-X17"}],"mis":"K3-2-u2-X17","explanation":["셋 다 서로 다른 곳에서 마음이 움직였어요.","생각이나 느낌은 달라도 괜찮아요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"윤성","text":"추운 날에도 서 있었다는 곳에서 마음이 뭉클했어."},{"who":"다올","text":"나는 “내가 없는 날”이라는 말이 오래 남았어."},{"who":"예하","text":"나는 내일 아침에 인사해 봐야겠다고 생각했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_basic#9','kor',3,2,'u2','L05','g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',2,'mc','auto','「“내가 없는 날, 누가 여기를 살피지?”」 장면의 분위기로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":9,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"「“내가 없는 날, 누가 여기를 살피지?”」 장면의 분위기로 알맞은 것은 무엇인가요?","options":[{"t":"묵직하고 든든하다","correct":true},{"t":"들뜨고 시끌시끌하다","mis":"K3-2-u2-X12"},{"t":"무섭고 아슬아슬하다","mis":"K3-2-u2-X12"},{"t":"우습고 장난스럽다","mis":"K3-2-u2-X12"}],"explanation":["추운 길가에 혼자 서 있어요.","그래도 그만두지 않았어요.","묵직하고 든든해요."],"asset":{"type":"passage","lines":["처음에는 이른 아침에 일어나는 일이 가장 힘들었다고 한다.","그래도 하루도 빠지지 않은 까닭을 이렇게 말했다.","“내가 없는 날, 누가 여기를 살피지?”","봄에는 꽃가루가 날리고 겨울에는 손이 얼었다.","그래도 노란 조끼는 늘 같은 곳에 서 있었다.","아이들은 이제 멀리서도 그 조끼를 알아본다."],"title":"글 「노란 조끼」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_basic#10','kor',3,2,'u2','L05','g3_2_kor_u2_L05_basic','lesson_basic','K3-2-u2-C7',3,'error','auto','「봄에는 꽃가루가 날리고 겨울에는 손이 얼었다.」를 읽는 방법을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X05']::text[],false,'{"seq":10,"concept":"K3-2-u2-C7","difficulty":3,"kind":"error","stem":"「봄에는 꽃가루가 날리고 겨울에는 손이 얼었다.」를 읽는 방법을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「봄에는∨꽃가루가∨날리고∨겨울에는∨손이∨얼었다처럼 낱말마다 다 끊어야 정확해.」","correct":true,"mis_target":"K3-2-u2-X05"},{"t":"친구 가 — 「‘봄에는 꽃가루가 날리고’에서 한 번 쉬면 두 계절 장면이 떠올라.」","mis":"K3-2-u2-X05"},{"t":"친구 다 — 「손이 언 장면을 떠올리며 조금 느리게 읽으면 좋겠어.」","mis":"K3-2-u2-X05"}],"explanation":["낱말마다 끊으면 장면이 흩어져요.","계절마다 한 덩어리로 묶어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["처음에는 이른 아침에 일어나는 일이 가장 힘들었다고 한다.","그래도 하루도 빠지지 않은 까닭을 이렇게 말했다.","“내가 없는 날, 누가 여기를 살피지?”","봄에는 꽃가루가 날리고 겨울에는 손이 얼었다.","그래도 노란 조끼는 늘 같은 곳에 서 있었다.","아이들은 이제 멀리서도 그 조끼를 알아본다."],"title":"글 「노란 조끼」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_challenge#1','kor',3,2,'u2','L05','g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C8',2,'sa','auto','「어깨를 다독여 준다」의 「다독여」와 뜻이 비슷한 말은 「○○ 준다」예요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u2-C8","difficulty":2,"kind":"sa","stem":"「어깨를 다독여 준다」의 「다독여」와 뜻이 비슷한 말은 「○○ 준다」예요. ○○에 들어갈 두 글자를 쓰세요.","answer":["달래"],"explanation":["다독이다는 가볍게 두드리며 마음을 가라앉혀 주는 거예요.","뛰어오는 아이를 안심시켜요.","달래 준다예요."],"asset":{"type":"passage","lines":["해가 뜨기 전, 길 건너에 노란 조끼가 서 있다.","우리 학교 건널목을 지키는 분이다.","비가 오는 날에도, 눈이 쌓인 날에도 그 자리를 비운 적이 없다.","아이들이 뛰어오면 손을 들어 차를 세우고 어깨를 다독여 준다.","“천천히 와도 돼. 서두르지 않아도 돼.”"],"title":"글 「노란 조끼」 ①"},"mis":"K3-2-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_challenge#2','kor',3,2,'u2','L05','g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C9',2,'mc','auto','「노란 조끼」를 읽고 둘레에서 배울 점이 있는 사람을 찾는 방법 가운데 가장 가까운 것은 무엇인가요?',ARRAY['K3-2-u2-X17']::text[],false,'{"seq":2,"concept":"K3-2-u2-C9","difficulty":2,"kind":"mc","stem":"「노란 조끼」를 읽고 둘레에서 배울 점이 있는 사람을 찾는 방법 가운데 가장 가까운 것은 무엇인가요?","options":[{"t":"둘레 사람에게 물어보기","correct":true},{"t":"아주 유명한 사람만 인터넷에서 찾기","mis":"K3-2-u2-X17"},{"t":"나보다 나이가 많은 사람만 고르기","mis":"K3-2-u2-X17"},{"t":"책에 나온 사람만 고르기","mis":"K3-2-u2-X17"}],"explanation":["찾는 길은 여러 가지예요.","그 가운데 가장 가까운 길이 있어요.","우리 반·우리 집에도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_challenge#3','kor',3,2,'u2','L05','g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C7',3,'mc','auto','여덟째 줄 장면을 정리한 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X15','K3-2-u2-X11']::text[],false,'{"seq":3,"concept":"K3-2-u2-C7","difficulty":3,"kind":"mc","stem":"여덟째 줄 장면을 정리한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"상황 — 이른 아침 추운 길가에 혼자 서 있다 / 마음 — 힘들어도 그만둘 수 없다","correct":true},{"t":"상황 — 아이들과 운동장에서 논다 / 마음 — 신난다","mis":"K3-2-u2-X15"},{"t":"상황 — 노란 조끼를 새로 샀다 / 마음 — 뿌듯하다","mis":"K3-2-u2-X15"},{"t":"상황 — 비가 그쳤다 / 마음 — 알 수 없다","mis":"K3-2-u2-X11"}],"explanation":["장면은 상황 · 말 · 마음으로 정리해요.","혼자 서 있는 장면이에요.","그만둘 수 없는 마음이에요."],"asset":{"type":"passage","lines":["처음에는 이른 아침에 일어나는 일이 가장 힘들었다고 한다.","그래도 하루도 빠지지 않은 까닭을 이렇게 말했다.","“내가 없는 날, 누가 여기를 살피지?”","봄에는 꽃가루가 날리고 겨울에는 손이 얼었다.","그래도 노란 조끼는 늘 같은 곳에 서 있었다.","아이들은 이제 멀리서도 그 조끼를 알아본다."],"title":"글 「노란 조끼」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_challenge#4','kor',3,2,'u2','L05','g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C8',3,'error','auto','「여기를 살피지」를 비슷한 말로 바꾸어 읽었어요. 뜻이 통하지 않는 친구는 누구인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":4,"concept":"K3-2-u2-C8","difficulty":3,"kind":"error","stem":"「여기를 살피지」를 비슷한 말로 바꾸어 읽었어요. 뜻이 통하지 않는 친구는 누구인가요?","options":[{"t":"친구 다 — 「여기를 달래지」","correct":true,"mis_target":"K3-2-u2-X16"},{"t":"친구 가 — 「여기를 둘러보지」","mis":"K3-2-u2-X16"},{"t":"친구 나 — 「여기를 지켜보지」","mis":"K3-2-u2-X16"}],"explanation":["살피다는 두루 자세히 보는 거예요.","둘러보다 · 지켜보다는 통해요.","친구 다는 다독이다의 뜻과 섞었어요."],"asset":{"type":"passage","lines":["처음에는 이른 아침에 일어나는 일이 가장 힘들었다고 한다.","그래도 하루도 빠지지 않은 까닭을 이렇게 말했다.","“내가 없는 날, 누가 여기를 살피지?”","봄에는 꽃가루가 날리고 겨울에는 손이 얼었다.","그래도 노란 조끼는 늘 같은 곳에 서 있었다.","아이들은 이제 멀리서도 그 조끼를 알아본다."],"title":"글 「노란 조끼」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_challenge#5','kor',3,2,'u2','L05','g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C7',3,'ox','auto','「아이들은 이제 멀리서도 그 조끼를 알아본다.」에서 아이들이 조끼를 알아보는 까닭은 늘 같은 곳에 서 있었기 때문이에요.',ARRAY['K3-2-u2-X08']::text[],false,'{"seq":5,"concept":"K3-2-u2-C7","difficulty":3,"kind":"ox","stem":"「아이들은 이제 멀리서도 그 조끼를 알아본다.」에서 아이들이 조끼를 알아보는 까닭은 늘 같은 곳에 서 있었기 때문이에요.","answer":"O","reason_options":[{"t":"바로 앞 줄에 「늘 같은 곳에 서 있었다」고 했기 때문에","correct":true},{"t":"노란색이 세상에서 가장 눈에 띄는 색이라고 글에 쓰여 있기 때문에","mis":"K3-2-u2-X08"}],"mis":"K3-2-u2-X08","explanation":["앞 줄을 이어 읽어요.","늘 같은 곳에 서 있었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["처음에는 이른 아침에 일어나는 일이 가장 힘들었다고 한다.","그래도 하루도 빠지지 않은 까닭을 이렇게 말했다.","“내가 없는 날, 누가 여기를 살피지?”","봄에는 꽃가루가 날리고 겨울에는 손이 얼었다.","그래도 노란 조끼는 늘 같은 곳에 서 있었다.","아이들은 이제 멀리서도 그 조끼를 알아본다."],"title":"글 「노란 조끼」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_challenge#6','kor',3,2,'u2','L05','g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C9',3,'mc','auto','예하가 「내일 아침에 인사해 봐야겠다」고 한 것은 어떤 것인가요?',ARRAY['K3-2-u2-X08','K3-2-u2-X17']::text[],false,'{"seq":6,"concept":"K3-2-u2-C9","difficulty":3,"kind":"mc","stem":"예하가 「내일 아침에 인사해 봐야겠다」고 한 것은 어떤 것인가요?","options":[{"t":"글을 읽고 든 생각을 내 생활과 이어 말한 것","correct":true},{"t":"글에 나온 사실을 그대로 옮긴 것","mis":"K3-2-u2-X08"},{"t":"윤성이의 느낌이 틀렸다고 말한 것","mis":"K3-2-u2-X17"},{"t":"노란 조끼에 대해 지어낸 것","mis":"K3-2-u2-X08"}],"explanation":["예하는 자기가 할 일을 말했어요.","글을 읽고 든 생각이에요.","생활과 이은 생각이에요."],"asset":{"type":"speech","turns":[{"who":"윤성","text":"추운 날에도 서 있었다는 곳에서 마음이 뭉클했어."},{"who":"다올","text":"나는 “내가 없는 날”이라는 말이 오래 남았어."},{"who":"예하","text":"나는 내일 아침에 인사해 봐야겠다고 생각했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_challenge#7','kor',3,2,'u2','L05','g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C7',3,'match','auto','「노란 조끼」의 문장과 떠오르는 장면을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u2-C7","difficulty":3,"kind":"match","stem":"「노란 조끼」의 문장과 떠오르는 장면을 알맞게 이으세요.","pairs":[{"l":"해가 뜨기 전, 길 건너에 노란 조끼가 서 있다","r":"아직 어두운 길가에 조끼 하나가 보이는 장면"},{"l":"손을 들어 차를 세우고 어깨를 다독여 준다","r":"뛰어온 아이를 멈춰 세워 안심시키는 장면"},{"l":"겨울에는 손이 얼었다","r":"찬바람 속에서 언 손을 비비는 장면"}],"mis":"K3-2-u2-X15","explanation":["문장을 읽으며 그림을 떠올려요.","때 · 하는 일 · 계절을 봐요.","장면이 떠오르면 목소리도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_challenge#8','kor',3,2,'u2','L05','g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C8',4,'mc','auto','「천천히 와도 돼. 서두르지 않아도 돼.」에서 「천천히 와도 돼」와 「서두르지 않아도 돼」의 관계로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":8,"concept":"K3-2-u2-C8","difficulty":4,"kind":"mc","stem":"「천천히 와도 돼. 서두르지 않아도 돼.」에서 「천천히 와도 돼」와 「서두르지 않아도 돼」의 관계로 가장 알맞은 것은 무엇인가요?","options":[{"t":"서두르다와 천천히는 뜻이 반대라, 같은 마음을 두 번 다르게 말해 아이들을 안심시킨다","correct":true},{"t":"두 말은 뜻이 서로 부딪혀 하나는 잘못 쓴 말이다","mis":"K3-2-u2-X16"},{"t":"서두르다는 천천히와 뜻이 비슷하다","mis":"K3-2-u2-X16"},{"t":"두 말은 아무 관계가 없다","mis":"K3-2-u2-X16"}],"explanation":["「서두르지 않아도」는 「급히 하지 않아도」예요.","그것은 「천천히 해도」와 같은 말이에요.","같은 마음을 두 번 말했어요."],"asset":{"type":"passage","lines":["해가 뜨기 전, 길 건너에 노란 조끼가 서 있다.","우리 학교 건널목을 지키는 분이다.","비가 오는 날에도, 눈이 쌓인 날에도 그 자리를 비운 적이 없다.","아이들이 뛰어오면 손을 들어 차를 세우고 어깨를 다독여 준다.","“천천히 와도 돼. 서두르지 않아도 돼.”"],"title":"글 「노란 조끼」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_challenge#9','kor',3,2,'u2','L05','g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C7',4,'essay','teacher','「노란 조끼」에서 가장 장면이 잘 떠오르는 문장 하나를 골라 쓰고, 어디에서 쉬어 읽을지 ∨ 로 표시한 뒤, 어떤 장면을 떠올리며 어떤 목소리로 읽을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C7","difficulty":4,"kind":"essay","stem":"「노란 조끼」에서 가장 장면이 잘 떠오르는 문장 하나를 골라 쓰고, 어디에서 쉬어 읽을지 ∨ 로 표시한 뒤, 어떤 장면을 떠올리며 어떤 목소리로 읽을지 쓰세요.","answer_guide":{"answer":"예: 비가 오는 날에도,∨눈이 쌓인 날에도∨그 자리를 비운 적이 없다.≡ — 비에 젖고 눈을 맞으면서도 길가에 서 있는 모습을 떠올리며, 묵직하고 든든한 마음이 들리게 조금 낮고 천천히 읽겠다.","scoring_points":["문장을 골라 썼는가","뜻 덩어리에 맞게 ∨ 를 표시했는가","떠올린 장면과 목소리를 썼는가"]},"explanation":["문장을 하나 골라요.","뜻 덩어리마다 쉬어요.","장면과 목소리를 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L05_challenge#10','kor',3,2,'u2','L05','g3_2_kor_u2_L05_challenge','lesson_challenge','K3-2-u2-C9',4,'essay','teacher','「노란 조끼」처럼 내 둘레에서 날마다 꾸준히 무엇인가를 하는 사람을 한 명 떠올려 그 사람이 하는 일을 쓰고, 그 사람에게서 배울 점과 「노란 조끼」를 읽고 든 내 생각을 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C9","difficulty":4,"kind":"essay","stem":"「노란 조끼」처럼 내 둘레에서 날마다 꾸준히 무엇인가를 하는 사람을 한 명 떠올려 그 사람이 하는 일을 쓰고, 그 사람에게서 배울 점과 「노란 조끼」를 읽고 든 내 생각을 함께 쓰세요.","answer_guide":{"answer":"예: 우리 아파트 경비 아저씨는 날마다 아침 일찍 아파트 화단에 물을 주신다. 춥거나 더워도 거르지 않는 꾸준함을 배우고 싶다. 「노란 조끼」를 읽고 나서, 내가 당연하게 여긴 일 뒤에도 누군가의 꾸준한 손길이 있다는 생각이 들었다.","scoring_points":["둘레의 사람과 그 사람이 하는 일을 썼는가","배울 점을 썼는가","「노란 조끼」를 읽고 든 내 생각을 썼는가"]},"explanation":["유명하지 않아도 돼요.","그 사람이 꾸준히 하는 일을 써요.","배울 점과 내 생각을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_basic#1','kor',3,2,'u2','L07','g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',1,'mc','auto','설명하는 글에 그림을 넣는 까닭은 무엇인가요?',ARRAY['K3-2-u2-X18']::text[],false,'{"seq":1,"concept":"K3-2-u2-C10","difficulty":1,"kind":"mc","stem":"설명하는 글에 그림을 넣는 까닭은 무엇인가요?","options":[{"t":"글로는 알기 어려운 것을 한눈에 보여 주려고","correct":true},{"t":"보기 좋게 꾸미려고","mis":"K3-2-u2-X18"},{"t":"글을 적게 쓰려고","mis":"K3-2-u2-X18"},{"t":"종이를 채우려고","mis":"K3-2-u2-X18"}],"explanation":["도서관 안내의 평면 그림을 떠올려요.","굵은 동그라미가 자리를 보여 줬어요.","한눈에 보여 주려고 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_basic#2','kor',3,2,'u2','L07','g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',1,'mc','auto','「학교에서 쓰는 번호」에서 책에 붙인 번호를 보면 무엇을 알 수 있나요?',ARRAY['K3-2-u2-X08']::text[],false,'{"seq":2,"concept":"K3-2-u2-C10","difficulty":1,"kind":"mc","stem":"「학교에서 쓰는 번호」에서 책에 붙인 번호를 보면 무엇을 알 수 있나요?","options":[{"t":"그 책을 어느 칸에 꽂아야 하는지","correct":true},{"t":"책의 값","mis":"K3-2-u2-X08"},{"t":"누가 쓴 책인지","mis":"K3-2-u2-X08"},{"t":"책이 몇 쪽인지","mis":"K3-2-u2-X08"}],"explanation":["마지막 도막을 읽어요.","책 아래쪽 번호를 봐요.","꽂을 칸을 알 수 있어요."],"asset":{"type":"passage","lines":["이름이 같아도 번호는 다릅니다. 같은 이름의 친구도 출석 번호로 가릴 수 있습니다.","[그림] 이름표 둘에 서로 다른 번호가 붙어 있는 그림","칸마다 다른 사물함 번호. 번호가 있으면 여러 칸 가운데 내 칸을 바로 찾습니다.","[그림] 번호가 적힌 사물함 여러 칸 그림","교실마다 다른 표시. 문 앞의 표시를 보면 몇 학년 몇 반인지 알 수 있습니다.","[그림] 교실 문 위 표시판 그림","책에 붙인 번호. 책 아래쪽 번호를 보면 어느 칸에 꽂을지 알 수 있습니다.","[그림] 책등에 번호표가 붙은 책 그림"],"title":"설명하는 글 「학교에서 쓰는 번호」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_basic#3','kor',3,2,'u2','L07','g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C11',1,'ox','auto','칸마다 다른 색을 칠하는 것은 서로 다른 칸임을 구별하려고 하는 거예요.',ARRAY['K3-2-u2-X20']::text[],false,'{"seq":3,"concept":"K3-2-u2-C11","difficulty":1,"kind":"ox","stem":"칸마다 다른 색을 칠하는 것은 서로 다른 칸임을 구별하려고 하는 거예요.","answer":"O","reason_options":[{"t":"색은 서로 다른 것을 구별해 보여 주기 때문에","correct":true},{"t":"색은 언제나 가장 중요한 것을 알려 주기 때문에","mis":"K3-2-u2-X20"}],"mis":"K3-2-u2-X20","explanation":["색 · 크기 · 모양은 하는 일이 달라요.","색은 구별해 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_basic#4','kor',3,2,'u2','L07','g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C11',1,'mc','auto','안내 그림에 화살표를 그리는 까닭은 무엇인가요?',ARRAY['K3-2-u2-X20','K3-2-u2-X18']::text[],false,'{"seq":4,"concept":"K3-2-u2-C11","difficulty":1,"kind":"mc","stem":"안내 그림에 화살표를 그리는 까닭은 무엇인가요?","options":[{"t":"어느 쪽으로 가는지 알려 주려고","correct":true},{"t":"서로 다른 칸을 구별하려고","mis":"K3-2-u2-X20"},{"t":"글씨를 크게 보이려고","mis":"K3-2-u2-X20"},{"t":"그림을 꾸미려고","mis":"K3-2-u2-X18"}],"explanation":["화살표는 모양이에요.","모양은 어디인지, 어느 쪽인지 알려 줘요.","가는 쪽을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_basic#5','kor',3,2,'u2','L07','g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',2,'mc','auto','같은 도서관 안내를 두 가지로 만들었어요. 「글과 그림이 함께 있는 안내」가 더 빨리 알아볼 수 있었던 까닭은 무엇인가요?',ARRAY['K3-2-u2-X19','K3-2-u2-X18']::text[],false,'{"seq":5,"concept":"K3-2-u2-C10","difficulty":2,"kind":"mc","stem":"같은 도서관 안내를 두 가지로 만들었어요. 「글과 그림이 함께 있는 안내」가 더 빨리 알아볼 수 있었던 까닭은 무엇인가요?","options":[{"t":"평면 그림의 굵은 동그라미가 도서관 자리를 한눈에 보여 주어서","correct":true},{"t":"글이 더 길어서","mis":"K3-2-u2-X19"},{"t":"그림이 더 예뻐서","mis":"K3-2-u2-X18"},{"t":"글이 하나도 없어서","mis":"K3-2-u2-X19"}],"explanation":["두 안내의 글은 같았어요.","다른 것은 그림이에요.","그림이 자리를 한눈에 보여 줬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_basic#6','kor',3,2,'u2','L07','g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',2,'mc','auto','글과 그림을 함께 쓰면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":6,"concept":"K3-2-u2-C10","difficulty":2,"kind":"mc","stem":"글과 그림을 함께 쓰면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"글은 자세히 알려 주고 그림은 한눈에 보여 주어 이어 보면 더 잘 이해된다","correct":true},{"t":"그림만 크면 글은 없어도 된다","mis":"K3-2-u2-X19"},{"t":"글이 있으면 그림은 볼 필요가 없다","mis":"K3-2-u2-X19"},{"t":"그림이 있으면 글을 아무렇게나 써도 된다","mis":"K3-2-u2-X19"}],"explanation":["글이 하는 일과 그림이 하는 일이 달라요.","둘이 서로 돕는 거예요.","이어 보면 더 잘 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_basic#7','kor',3,2,'u2','L07','g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C11',2,'match','auto','표현 방법과 그렇게 한 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u2-C11","difficulty":2,"kind":"match","stem":"표현 방법과 그렇게 한 까닭을 알맞게 이으세요.","pairs":[{"l":"칸마다 다른 색을 칠했다","r":"서로 다른 칸임을 구별하려고"},{"l":"번호 글자를 크게 썼다","r":"가장 중요한 것을 눈에 띄게 하려고"},{"l":"화살표를 그렸다","r":"어느 쪽으로 가는지 알려 주려고"}],"mis":"K3-2-u2-X20","explanation":["그 표현이 없었다면 무엇이 어려웠을까요?","색은 구별, 크기는 눈에 띄게예요.","모양은 쪽을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_basic#8','kor',3,2,'u2','L07','g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C11',2,'ox','auto','한슬이와 유빈이가 사물함을 서로 다르게 나타냈으니 한 명은 잘못 나타낸 거예요.',ARRAY['K3-2-u2-X24']::text[],false,'{"seq":8,"concept":"K3-2-u2-C11","difficulty":2,"kind":"ox","stem":"한슬이와 유빈이가 사물함을 서로 다르게 나타냈으니 한 명은 잘못 나타낸 거예요.","answer":"X","reason_options":[{"t":"같은 내용이라도 나타내는 방법은 여러 가지이기 때문에","correct":true},{"t":"같은 내용은 언제나 똑같이 나타내야 하기 때문에","mis":"K3-2-u2-X24"}],"mis":"K3-2-u2-X24","explanation":["한슬이는 그림을 크게, 유빈이는 번호를 크게 했어요.","둘 다 사물함 번호가 잘 보여요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"한슬","text":"사물함 그림을 크게 그리고, 번호는 작게 적었어."},{"who":"유빈","text":"번호를 크게 쓰고, 사물함은 네모로만 간단히 그렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_basic#9','kor',3,2,'u2','L07','g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',2,'mc','auto','「학교에서 쓰는 번호」에서 [그림] 「번호가 적힌 사물함 여러 칸 그림」은 어떤 글과 이어 읽어야 하나요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":9,"concept":"K3-2-u2-C10","difficulty":2,"kind":"mc","stem":"「학교에서 쓰는 번호」에서 [그림] 「번호가 적힌 사물함 여러 칸 그림」은 어떤 글과 이어 읽어야 하나요?","options":[{"t":"번호가 있으면 여러 칸 가운데 내 칸을 바로 찾는다","correct":true},{"t":"같은 이름의 친구도 출석 번호로 가릴 수 있다","mis":"K3-2-u2-X19"},{"t":"문 앞의 표시를 보면 몇 학년 몇 반인지 안다","mis":"K3-2-u2-X19"},{"t":"책 아래쪽 번호를 보면 꽂을 칸을 안다","mis":"K3-2-u2-X19"}],"explanation":["그림 바로 위의 글을 봐요.","사물함 이야기예요.","내 칸을 찾는 글과 이어요."],"asset":{"type":"passage","lines":["이름이 같아도 번호는 다릅니다. 같은 이름의 친구도 출석 번호로 가릴 수 있습니다.","[그림] 이름표 둘에 서로 다른 번호가 붙어 있는 그림","칸마다 다른 사물함 번호. 번호가 있으면 여러 칸 가운데 내 칸을 바로 찾습니다.","[그림] 번호가 적힌 사물함 여러 칸 그림","교실마다 다른 표시. 문 앞의 표시를 보면 몇 학년 몇 반인지 알 수 있습니다.","[그림] 교실 문 위 표시판 그림","책에 붙인 번호. 책 아래쪽 번호를 보면 어느 칸에 꽂을지 알 수 있습니다.","[그림] 책등에 번호표가 붙은 책 그림"],"title":"설명하는 글 「학교에서 쓰는 번호」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_basic#10','kor',3,2,'u2','L07','g3_2_kor_u2_L07_basic','lesson_basic','K3-2-u2-C10',3,'error','auto','「학교에서 쓰는 번호」의 그림을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X18','K3-2-u2-X19']::text[],false,'{"seq":10,"concept":"K3-2-u2-C10","difficulty":3,"kind":"error","stem":"「학교에서 쓰는 번호」의 그림을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「교실 문 위 표시판 그림은 예쁘게 보이려고 넣은 거야.」","correct":true,"mis_target":"K3-2-u2-X18"},{"t":"친구 가 — 「이름표 그림을 보면 이름이 같아도 번호가 다른 게 한눈에 보여.」","mis":"K3-2-u2-X18"},{"t":"친구 다 — 「표시판 그림이 있어서 몇 학년 몇 반이 문 위에 있다는 걸 바로 알겠어.」","mis":"K3-2-u2-X19"}],"explanation":["그림은 꾸미려고 넣지 않아요.","글로 알기 어려운 것을 보여 줘요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["이름이 같아도 번호는 다릅니다. 같은 이름의 친구도 출석 번호로 가릴 수 있습니다.","[그림] 이름표 둘에 서로 다른 번호가 붙어 있는 그림","칸마다 다른 사물함 번호. 번호가 있으면 여러 칸 가운데 내 칸을 바로 찾습니다.","[그림] 번호가 적힌 사물함 여러 칸 그림","교실마다 다른 표시. 문 앞의 표시를 보면 몇 학년 몇 반인지 알 수 있습니다.","[그림] 교실 문 위 표시판 그림","책에 붙인 번호. 책 아래쪽 번호를 보면 어느 칸에 꽂을지 알 수 있습니다.","[그림] 책등에 번호표가 붙은 책 그림"],"title":"설명하는 글 「학교에서 쓰는 번호」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_challenge#1','kor',3,2,'u2','L07','g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C11',2,'sa','auto','색·크기·모양 가운데 중요한 것을 눈에 띄게 할 때 쓰는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u2-C11","difficulty":2,"kind":"sa","stem":"색·크기·모양 가운데 중요한 것을 눈에 띄게 할 때 쓰는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["크기"],"explanation":["번호 글자를 크게 썼어요.","크게 하면 눈에 띄어요.","크기예요."],"mis":"K3-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_challenge#2','kor',3,2,'u2','L07','g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',2,'mc','auto','「같은 이름을 가진 친구가 있어도 출석 번호로 가릴 수 있습니다.」 옆에 넣을 그림으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X18','K3-2-u2-X23']::text[],false,'{"seq":2,"concept":"K3-2-u2-C10","difficulty":2,"kind":"mc","stem":"「같은 이름을 가진 친구가 있어도 출석 번호로 가릴 수 있습니다.」 옆에 넣을 그림으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"이름이 같은 이름표 둘에 서로 다른 번호가 붙은 그림","correct":true},{"t":"웃고 있는 친구 얼굴 그림","mis":"K3-2-u2-X18"},{"t":"교실 창밖 나무 그림","mis":"K3-2-u2-X18"},{"t":"알록달록한 무늬 그림","mis":"K3-2-u2-X23"}],"explanation":["글이 말하는 것을 그림이 보여 줘야 해요.","같은 이름 · 다른 번호예요.","이름표 둘 그림이 알맞아요."],"asset":{"type":"passage","lines":["이름이 같아도 번호는 다릅니다. 같은 이름의 친구도 출석 번호로 가릴 수 있습니다.","[그림] 이름표 둘에 서로 다른 번호가 붙어 있는 그림","칸마다 다른 사물함 번호. 번호가 있으면 여러 칸 가운데 내 칸을 바로 찾습니다.","[그림] 번호가 적힌 사물함 여러 칸 그림","교실마다 다른 표시. 문 앞의 표시를 보면 몇 학년 몇 반인지 알 수 있습니다.","[그림] 교실 문 위 표시판 그림","책에 붙인 번호. 책 아래쪽 번호를 보면 어느 칸에 꽂을지 알 수 있습니다.","[그림] 책등에 번호표가 붙은 책 그림"],"title":"설명하는 글 「학교에서 쓰는 번호」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_challenge#3','kor',3,2,'u2','L07','g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C11',3,'mc','auto','사물함 안내 그림에서 번호를 크게 쓰고 칸마다 다른 색을 칠했어요. 이렇게 한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X20','K3-2-u2-X18']::text[],false,'{"seq":3,"concept":"K3-2-u2-C11","difficulty":3,"kind":"mc","stem":"사물함 안내 그림에서 번호를 크게 쓰고 칸마다 다른 색을 칠했어요. 이렇게 한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"번호는 가장 중요해 눈에 띄게, 색은 칸을 서로 구별하려고","correct":true},{"t":"번호는 구별하려고, 색은 눈에 띄게 하려고","mis":"K3-2-u2-X20"},{"t":"둘 다 꾸미려고","mis":"K3-2-u2-X18"},{"t":"둘 다 어느 쪽인지 알려 주려고","mis":"K3-2-u2-X20"}],"explanation":["크기와 색이 하는 일을 나누어 봐요.","크기는 눈에 띄게, 색은 구별이에요.","두 가지 까닭이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_challenge#4','kor',3,2,'u2','L07','g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',3,'error','auto','글과 그림을 함께 쓰는 것을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":4,"concept":"K3-2-u2-C10","difficulty":3,"kind":"error","stem":"글과 그림을 함께 쓰는 것을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「그림을 크게 그리면 글은 다 지워도 돼.」","correct":true,"mis_target":"K3-2-u2-X19"},{"t":"친구 가 — 「글은 자세하지만 한눈에 안 들어와.」","mis":"K3-2-u2-X19"},{"t":"친구 나 — 「그림은 한눈에 들어오지만 자세하지 않아.」","mis":"K3-2-u2-X19"}],"explanation":["글과 그림은 서로 도와요.","한쪽만 있으면 모자라요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_challenge#5','kor',3,2,'u2','L07','g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',3,'ox','auto','「도서관은 3층 복도 끝, 계단을 올라와 오른쪽으로 스무 걸음쯤」이라는 글만으로도 자세하지만, 평면 그림을 함께 두면 더 빨리 찾을 수 있어요.',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":5,"concept":"K3-2-u2-C10","difficulty":3,"kind":"ox","stem":"「도서관은 3층 복도 끝, 계단을 올라와 오른쪽으로 스무 걸음쯤」이라는 글만으로도 자세하지만, 평면 그림을 함께 두면 더 빨리 찾을 수 있어요.","answer":"O","reason_options":[{"t":"글은 자세히 알려 주고 그림은 자리를 한눈에 보여 주기 때문에","correct":true},{"t":"그림이 있으면 글이 틀려도 되기 때문에","mis":"K3-2-u2-X19"}],"mis":"K3-2-u2-X19","explanation":["글은 틀리지 않았어요.","그림은 한눈에 보여 줘요.","함께 쓰면 더 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_challenge#6','kor',3,2,'u2','L07','g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',3,'match','auto','「학교에서 쓰는 번호」의 글과 그 옆에 놓인 그림을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u2-C10","difficulty":3,"kind":"match","stem":"「학교에서 쓰는 번호」의 글과 그 옆에 놓인 그림을 알맞게 이으세요.","pairs":[{"l":"같은 이름도 출석 번호로 가릴 수 있다","r":"이름표 둘에 다른 번호가 붙은 그림"},{"l":"몇 학년 몇 반인지 문 앞 표시로 안다","r":"교실 문 위 표시판 그림"},{"l":"책 아래쪽 번호로 꽂을 칸을 안다","r":"책등에 번호표가 붙은 그림"}],"mis":"K3-2-u2-X19","explanation":["글이 말하는 것을 그림이 보여 줘요.","이름 · 교실 · 책을 찾아요.","서로 맞는 것끼리 이어요."],"asset":{"type":"passage","lines":["이름이 같아도 번호는 다릅니다. 같은 이름의 친구도 출석 번호로 가릴 수 있습니다.","[그림] 이름표 둘에 서로 다른 번호가 붙어 있는 그림","칸마다 다른 사물함 번호. 번호가 있으면 여러 칸 가운데 내 칸을 바로 찾습니다.","[그림] 번호가 적힌 사물함 여러 칸 그림","교실마다 다른 표시. 문 앞의 표시를 보면 몇 학년 몇 반인지 알 수 있습니다.","[그림] 교실 문 위 표시판 그림","책에 붙인 번호. 책 아래쪽 번호를 보면 어느 칸에 꽂을지 알 수 있습니다.","[그림] 책등에 번호표가 붙은 책 그림"],"title":"설명하는 글 「학교에서 쓰는 번호」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_challenge#7','kor',3,2,'u2','L07','g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C11',3,'mc','auto','한슬이는 사물함 그림을 크게, 유빈이는 번호를 크게 나타냈어요. 둘을 보고 할 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X24']::text[],false,'{"seq":7,"concept":"K3-2-u2-C11","difficulty":3,"kind":"mc","stem":"한슬이는 사물함 그림을 크게, 유빈이는 번호를 크게 나타냈어요. 둘을 보고 할 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“둘 다 내 칸을 찾는 데 필요한 것이 잘 보여서 알맞아.”","correct":true},{"t":"“그림이 큰 한슬이 것이 더 잘 만들었어.”","mis":"K3-2-u2-X24"},{"t":"“번호가 큰 유빈이 것만 맞아.”","mis":"K3-2-u2-X24"},{"t":"“둘이 다르니 둘 다 다시 만들어야 해.”","mis":"K3-2-u2-X24"}],"explanation":["나타내는 방법은 여러 가지예요.","전하려는 것이 보이는지 봐요.","둘 다 알맞아요."],"asset":{"type":"speech","turns":[{"who":"한슬","text":"사물함 그림을 크게 그리고, 번호는 작게 적었어."},{"who":"유빈","text":"번호를 크게 쓰고, 사물함은 네모로만 간단히 그렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_challenge#8','kor',3,2,'u2','L07','g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C11',4,'mc','auto','「교실마다 다른 표시」를 설명하는 그림에서 우리 반 표시만 빨간 테두리로 크게 그렸어요. 이 그림이 알려 주려는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X18','K3-2-u2-X20','K3-2-u2-X19']::text[],false,'{"seq":8,"concept":"K3-2-u2-C11","difficulty":4,"kind":"mc","stem":"「교실마다 다른 표시」를 설명하는 그림에서 우리 반 표시만 빨간 테두리로 크게 그렸어요. 이 그림이 알려 주려는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여러 교실 표시 가운데 우리 반이 어디인지를 눈에 띄게 알려 준다","correct":true},{"t":"빨간색이 가장 예쁜 색이라는 것","mis":"K3-2-u2-X18"},{"t":"우리 반이 가장 큰 교실이라는 것","mis":"K3-2-u2-X20"},{"t":"다른 교실 표시는 볼 필요가 없다는 것","mis":"K3-2-u2-X19"}],"explanation":["크기와 색은 눈에 띄게 하려고 써요.","우리 반만 다르게 했어요.","우리 반 자리를 알려 줘요."],"asset":{"type":"passage","lines":["이름이 같아도 번호는 다릅니다. 같은 이름의 친구도 출석 번호로 가릴 수 있습니다.","[그림] 이름표 둘에 서로 다른 번호가 붙어 있는 그림","칸마다 다른 사물함 번호. 번호가 있으면 여러 칸 가운데 내 칸을 바로 찾습니다.","[그림] 번호가 적힌 사물함 여러 칸 그림","교실마다 다른 표시. 문 앞의 표시를 보면 몇 학년 몇 반인지 알 수 있습니다.","[그림] 교실 문 위 표시판 그림","책에 붙인 번호. 책 아래쪽 번호를 보면 어느 칸에 꽂을지 알 수 있습니다.","[그림] 책등에 번호표가 붙은 책 그림"],"title":"설명하는 글 「학교에서 쓰는 번호」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_challenge#9','kor',3,2,'u2','L07','g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C10',4,'essay','teacher','「학교에서 쓰는 번호」 가운데 한 도막을 골라, 글이 하는 일과 그림이 하는 일을 나누어 쓰고, 그림이 없다면 무엇이 어려울지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C10","difficulty":4,"kind":"essay","stem":"「학교에서 쓰는 번호」 가운데 한 도막을 골라, 글이 하는 일과 그림이 하는 일을 나누어 쓰고, 그림이 없다면 무엇이 어려울지 쓰세요.","answer_guide":{"answer":"예: 사물함 도막 — 글은 번호가 있으면 여러 칸 가운데 내 칸을 바로 찾을 수 있다는 것을 자세히 알려 준다. 그림은 번호가 적힌 사물함 여러 칸이 어떻게 생겼는지 한눈에 보여 준다. 그림이 없으면 번호가 칸 어디에 적혀 있는지 떠올리기 어렵다.","scoring_points":["도막을 하나 골랐는가","글이 하는 일과 그림이 하는 일을 나누어 썼는가","그림이 없을 때 어려운 점을 썼는가"]},"explanation":["글과 그림이 하는 일은 달라요.","하나씩 나누어 써요.","그림이 빠지면 무엇이 어려운지 써요."],"asset":{"type":"passage","lines":["이름이 같아도 번호는 다릅니다. 같은 이름의 친구도 출석 번호로 가릴 수 있습니다.","[그림] 이름표 둘에 서로 다른 번호가 붙어 있는 그림","칸마다 다른 사물함 번호. 번호가 있으면 여러 칸 가운데 내 칸을 바로 찾습니다.","[그림] 번호가 적힌 사물함 여러 칸 그림","교실마다 다른 표시. 문 앞의 표시를 보면 몇 학년 몇 반인지 알 수 있습니다.","[그림] 교실 문 위 표시판 그림","책에 붙인 번호. 책 아래쪽 번호를 보면 어느 칸에 꽂을지 알 수 있습니다.","[그림] 책등에 번호표가 붙은 책 그림"],"title":"설명하는 글 「학교에서 쓰는 번호」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L07_challenge#10','kor',3,2,'u2','L07','g3_2_kor_u2_L07_challenge','lesson_challenge','K3-2-u2-C11',4,'essay','teacher','우리 교실 사물함이나 신발장을 설명하는 그림을 만든다고 생각하고, 색·크기·모양을 각각 어디에 어떻게 쓸지 정하고 그렇게 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C11","difficulty":4,"kind":"essay","stem":"우리 교실 사물함이나 신발장을 설명하는 그림을 만든다고 생각하고, 색·크기·모양을 각각 어디에 어떻게 쓸지 정하고 그렇게 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 색 — 모둠마다 사물함 칸에 다른 색을 칠해 어느 모둠 칸인지 구별하게 한다. 크기 — 번호를 크게 써서 내 칸을 바로 찾게 한다. 모양 — 교실 문에서 사물함까지 화살표를 그려 어느 쪽에 있는지 알려 준다.","scoring_points":["색을 어디에 쓸지와 까닭을 썼는가","크기를 어디에 쓸지와 까닭을 썼는가","모양을 어디에 쓸지와 까닭을 썼는가"]},"explanation":["색은 구별이에요.","크기는 눈에 띄게예요.","모양은 쪽을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_basic#1','kor',3,2,'u2','L08','g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C12',1,'mc','auto','「글로만 쓴 안내문」에서 아쉬운 점은 무엇인가요?',ARRAY['K3-2-u2-X18','K3-2-u2-X19','K3-2-u2-X08']::text[],false,'{"seq":1,"concept":"K3-2-u2-C12","difficulty":1,"kind":"mc","stem":"「글로만 쓴 안내문」에서 아쉬운 점은 무엇인가요?","options":[{"t":"무엇을 어디서 할지 한눈에 안 들어온다","correct":true},{"t":"글씨가 예쁘지 않다","mis":"K3-2-u2-X18"},{"t":"글이 너무 짧다","mis":"K3-2-u2-X19"},{"t":"틀린 말이 많다","mis":"K3-2-u2-X08"}],"explanation":["틀린 말은 하나도 없어요.","바쁜 아침에 보면 어떨까요?","한눈에 안 들어와요."],"asset":{"type":"passage","lines":["비 오는 날에는 우산을 교실 뒤 우산꽂이에 꽂고,","물기는 복도 창가에서 털고, 집에 갈 때 잊지 말고 가져갑니다.","우산을 바닥에 눕혀 두면 지나가는 친구가 밟을 수 있으니 그러지 않습니다."],"title":"글로만 쓴 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_basic#2','kor',3,2,'u2','L08','g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C13',1,'mc','auto','발표 자료의 얼개에서 맨 위 가운데에 놓기 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X22']::text[],false,'{"seq":2,"concept":"K3-2-u2-C13","difficulty":1,"kind":"mc","stem":"발표 자료의 얼개에서 맨 위 가운데에 놓기 알맞은 것은 무엇인가요?","options":[{"t":"크게 쓴 제목","correct":true},{"t":"그림을 풀어 주는 짧은 설명","mis":"K3-2-u2-X22"},{"t":"보여 주려는 그림","mis":"K3-2-u2-X22"},{"t":"만든 사람 이름만","mis":"K3-2-u2-X22"}],"explanation":["가장 먼저 눈에 들어와야 해요.","무엇에 대한 자료인지예요.","크게 쓴 제목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_basic#3','kor',3,2,'u2','L08','g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C14',1,'ox','auto','친구 자료를 보고 의견을 말할 때는 잘한 곳과 더 잘 보이게 할 방법을 함께 말해요.',ARRAY['K3-2-u2-X25']::text[],false,'{"seq":3,"concept":"K3-2-u2-C14","difficulty":1,"kind":"ox","stem":"친구 자료를 보고 의견을 말할 때는 잘한 곳과 더 잘 보이게 할 방법을 함께 말해요.","answer":"O","reason_options":[{"t":"그래야 친구가 다음에 더 잘 만들 수 있기 때문에","correct":true},{"t":"잘못한 곳만 말해야 도움이 되기 때문에","mis":"K3-2-u2-X25"}],"mis":"K3-2-u2-X25","explanation":["잘한 곳을 말해요.","더 잘 보이게 할 방법도 말해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_basic#4','kor',3,2,'u2','L08','g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C12',1,'mc','auto','「줄넘기」 ㉮ 도막에서 중요한 내용은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":4,"concept":"K3-2-u2-C12","difficulty":1,"kind":"mc","stem":"「줄넘기」 ㉮ 도막에서 중요한 내용은 무엇인가요?","options":[{"t":"손잡이 끝이 가슴 높이쯤 오게 줄 길이를 맞춘다","correct":true},{"t":"줄이 머리에 스칠 수도 있다","mis":"K3-2-u2-X21"},{"t":"줄넘기는 넓은 곳이 없어도 한다","mis":"K3-2-u2-X21"},{"t":"두 발을 모아 뛴다","mis":"K3-2-u2-X21"}],"explanation":["㉮의 제목은 「줄 길이 맞추기」예요.","도막이 알려 주려는 것을 찾아요.","가슴 높이쯤이에요."],"asset":{"type":"passage","lines":["㉮ 줄 길이 맞추기","줄 가운데를 한 발로 밟고 손잡이를 위로 당겨 봅니다. 손잡이 끝이 가슴 높이쯤에 오면 알맞습니다.","줄이 너무 길면 발에 걸리고, 너무 짧으면 머리에 스칩니다.","㉯ 뛰는 방법","두 발을 모아 뛰는 방법이 가장 기본입니다. 한 발씩 번갈아 뛰는 방법도 있습니다.","한 번 뛰는 동안 줄을 두 번 돌리는 방법은 더 빠르게 돌려야 합니다."],"title":"자료 「줄넘기」 ㉮ · ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_basic#5','kor',3,2,'u2','L08','g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C12',2,'mc','auto','처음 줄넘기를 하는 친구에게 알려 주려면 꼭 넣어야 할 것은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":5,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"처음 줄넘기를 하는 친구에게 알려 주려면 꼭 넣어야 할 것은 무엇인가요?","options":[{"t":"줄 길이 맞추는 방법","correct":true},{"t":"두 번 돌리기를 몇 번 했는지","mis":"K3-2-u2-X21"},{"t":"줄넘기가 좋은 까닭만","mis":"K3-2-u2-X21"},{"t":"줄넘기 손잡이의 색깔","mis":"K3-2-u2-X21"}],"explanation":["처음 하는 친구가 줄에 걸리면?","줄 길이부터 살펴야 해요.","목적이 정해지면 넣을 것도 정해져요."],"asset":{"type":"passage","lines":["㉮ 줄 길이 맞추기","줄 가운데를 한 발로 밟고 손잡이를 위로 당겨 봅니다. 손잡이 끝이 가슴 높이쯤에 오면 알맞습니다.","줄이 너무 길면 발에 걸리고, 너무 짧으면 머리에 스칩니다.","㉯ 뛰는 방법","두 발을 모아 뛰는 방법이 가장 기본입니다. 한 발씩 번갈아 뛰는 방법도 있습니다.","한 번 뛰는 동안 줄을 두 번 돌리는 방법은 더 빠르게 돌려야 합니다."],"title":"자료 「줄넘기」 ㉮ · ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_basic#6','kor',3,2,'u2','L08','g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C13',2,'match','auto','얼개의 자리와 들어갈 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u2-C13","difficulty":2,"kind":"match","stem":"얼개의 자리와 들어갈 것을 알맞게 이으세요.","pairs":[{"l":"맨 위 가운데","r":"크게 쓴 제목"},{"l":"가운데 넓은 칸","r":"보여 주려는 그림"},{"l":"그림 바로 아래","r":"그림을 풀어 주는 짧은 설명"}],"mis":"K3-2-u2-X22","explanation":["먼저 눈에 들어올 것을 위에 둬요.","그림은 넓은 칸에 둬요.","설명은 그림 바로 아래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_basic#7','kor',3,2,'u2','L08','g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C13',2,'mc','auto','발표 자료에 색과 크기를 쓸 때 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X23','K3-2-u2-X20']::text[],false,'{"seq":7,"concept":"K3-2-u2-C13","difficulty":2,"kind":"mc","stem":"발표 자료에 색과 크기를 쓸 때 알맞은 것은 무엇인가요?","options":[{"t":"전하려는 것이 눈에 띄게 쓴다","correct":true},{"t":"알록달록할수록 좋다","mis":"K3-2-u2-X23"},{"t":"글씨는 모두 크게 쓴다","mis":"K3-2-u2-X23"},{"t":"색은 한 가지도 쓰지 않는다","mis":"K3-2-u2-X20"}],"explanation":["모두 크면 무엇이 중요한지 보일까요?","많이 쓴다고 좋은 게 아니에요.","전하려는 것을 눈에 띄게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_basic#8','kor',3,2,'u2','L08','g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C14',2,'ox','auto','두 친구가 같은 내용을 다르게 만들었다면 글이 많은 쪽이 더 잘 만든 거예요.',ARRAY['K3-2-u2-X24']::text[],false,'{"seq":8,"concept":"K3-2-u2-C14","difficulty":2,"kind":"ox","stem":"두 친구가 같은 내용을 다르게 만들었다면 글이 많은 쪽이 더 잘 만든 거예요.","answer":"X","reason_options":[{"t":"전하려는 것이 잘 보이면 표현과 배치가 달라도 둘 다 알맞기 때문에","correct":true},{"t":"글이 많을수록 자세하니 언제나 낫기 때문에","mis":"K3-2-u2-X24"}],"mis":"K3-2-u2-X24","explanation":["같은 내용도 나타내는 방법은 여러 가지예요.","글의 양으로 정하지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_basic#9','kor',3,2,'u2','L08','g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C12',2,'mc','auto','우담이는 「함께할 때 지킬 것」을 운동장에 붙이려고 해요. 넣어야 할 내용으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":9,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"우담이는 「함께할 때 지킬 것」을 운동장에 붙이려고 해요. 넣어야 할 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"옆과 앞뒤로 사이를 띄우고 선다","correct":true},{"t":"넓은 곳이 없어도 할 수 있다","mis":"K3-2-u2-X21"},{"t":"몇 번 넘었는지 세어 둔다","mis":"K3-2-u2-X21"},{"t":"한 발씩 번갈아 뛰는 방법도 있다","mis":"K3-2-u2-X21"}],"explanation":["우담이가 고른 도막은 ㉰예요.","함께할 때 지킬 것이에요.","사이를 띄우는 내용이에요."],"asset":{"type":"passage","lines":["㉰ 함께할 때 지킬 것","두 팔을 옆으로 벌려도 닿지 않을 만큼 사이를 띄우고 섭니다. 앞뒤로도 한 걸음 넘게 띄웁니다.","줄이 옆 사람에게 닿으면 둘 다 멈추게 되기 때문입니다.","㉱ 줄넘기를 하면 좋은 점","넓은 곳이 없어도 할 수 있습니다. 이어서 하다 보면 숨이 덜 차게 됩니다.","몇 번 넘었는지 세어 두면 어제와 견주어 볼 수 있습니다."],"title":"자료 「줄넘기」 ㉰ · ㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_basic#10','kor',3,2,'u2','L08','g3_2_kor_u2_L08_basic','lesson_basic','K3-2-u2-C14',3,'error','auto','친구 자료 옆에 붙일 쪽지를 썼어요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K3-2-u2-X25']::text[],false,'{"seq":10,"concept":"K3-2-u2-C14","difficulty":3,"kind":"error","stem":"친구 자료 옆에 붙일 쪽지를 썼어요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"친구 가 — 「글씨가 삐뚤어. 그림도 별로야.」","correct":true,"mis_target":"K3-2-u2-X25"},{"t":"친구 나 — 「제목이 커서 무엇인지 바로 알겠어. 화살표를 하나 그리면 더 잘 보이겠어.」","mis":"K3-2-u2-X25"},{"t":"친구 다 — 「그림이 줄 길이를 잘 보여 줘. 설명 글씨를 조금만 키우면 좋겠어.」","mis":"K3-2-u2-X25"}],"explanation":["잘한 곳을 먼저 말해요.","더 잘 보이게 할 방법을 말해요.","친구 가는 잘못한 곳만 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_challenge#1','kor',3,2,'u2','L08','g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C13',2,'sa','auto','발표 자료를 만들기 전에, 어디에 무엇을 놓을지 미리 정하는 것을 「○○ 짜기」라고 해요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u2-C13","difficulty":2,"kind":"sa","stem":"발표 자료를 만들기 전에, 어디에 무엇을 놓을지 미리 정하는 것을 「○○ 짜기」라고 해요. ○○에 들어갈 두 글자를 쓰세요.","answer":["얼개"],"explanation":["만들기 전에 할 일이에요.","자리를 미리 정해요.","얼개 짜기예요."],"mis":"K3-2-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_challenge#2','kor',3,2,'u2','L08','g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C12',2,'mc','auto','나겸이가 「뛰는 방법」 세 가지를 그림으로 보여 주려면 꼭 넣어야 할 것은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":2,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"나겸이가 「뛰는 방법」 세 가지를 그림으로 보여 주려면 꼭 넣어야 할 것은 무엇인가요?","options":[{"t":"두 발 모아 뛰기 · 한 발씩 번갈아 뛰기 · 한 번에 두 번 돌리기","correct":true},{"t":"줄 가운데를 한 발로 밟기","mis":"K3-2-u2-X21"},{"t":"옆 사람과 사이 띄우기","mis":"K3-2-u2-X21"},{"t":"어제와 견주어 보기","mis":"K3-2-u2-X21"}],"explanation":["나겸이가 고른 도막은 ㉯예요.","뛰는 방법이 세 가지 나와요.","그 셋을 넣어요."],"asset":{"type":"passage","lines":["㉮ 줄 길이 맞추기","줄 가운데를 한 발로 밟고 손잡이를 위로 당겨 봅니다. 손잡이 끝이 가슴 높이쯤에 오면 알맞습니다.","줄이 너무 길면 발에 걸리고, 너무 짧으면 머리에 스칩니다.","㉯ 뛰는 방법","두 발을 모아 뛰는 방법이 가장 기본입니다. 한 발씩 번갈아 뛰는 방법도 있습니다.","한 번 뛰는 동안 줄을 두 번 돌리는 방법은 더 빠르게 돌려야 합니다."],"title":"자료 「줄넘기」 ㉮ · ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_challenge#3','kor',3,2,'u2','L08','g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C12',3,'mc','auto','「줄넘기」 ㉱에서 중요한 내용과 거리가 가장 먼 것은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":3,"concept":"K3-2-u2-C12","difficulty":3,"kind":"mc","stem":"「줄넘기」 ㉱에서 중요한 내용과 거리가 가장 먼 것은 무엇인가요?","options":[{"t":"줄이 옆 사람에게 닿으면 둘 다 멈춘다","correct":true},{"t":"넓은 곳이 없어도 할 수 있다","mis":"K3-2-u2-X21"},{"t":"이어서 하다 보면 숨이 덜 차게 된다","mis":"K3-2-u2-X21"},{"t":"몇 번 넘었는지 세어 두면 어제와 견주어 볼 수 있다","mis":"K3-2-u2-X21"}],"explanation":["㉱의 제목은 「좋은 점」이에요.","좋은 점이 셋 나와요.","옆 사람에게 닿는 것은 ㉰의 내용이에요."],"asset":{"type":"passage","lines":["㉰ 함께할 때 지킬 것","두 팔을 옆으로 벌려도 닿지 않을 만큼 사이를 띄우고 섭니다. 앞뒤로도 한 걸음 넘게 띄웁니다.","줄이 옆 사람에게 닿으면 둘 다 멈추게 되기 때문입니다.","㉱ 줄넘기를 하면 좋은 점","넓은 곳이 없어도 할 수 있습니다. 이어서 하다 보면 숨이 덜 차게 됩니다.","몇 번 넘었는지 세어 두면 어제와 견주어 볼 수 있습니다."],"title":"자료 「줄넘기」 ㉰ · ㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_challenge#4','kor',3,2,'u2','L08','g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C13',3,'error','auto','태경이가 짠 얼개를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X22','K3-2-u2-X23']::text[],false,'{"seq":4,"concept":"K3-2-u2-C13","difficulty":3,"kind":"error","stem":"태경이가 짠 얼개를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「설명 글씨를 제목보다 크게 써야 더 잘 보여.」","correct":true,"mis_target":"K3-2-u2-X22"},{"t":"친구 가 — 「제목을 가장 크게 써서 무엇에 대한 자료인지 바로 알겠어.」","mis":"K3-2-u2-X22"},{"t":"친구 나 — 「손잡이 끝에 굵은 가로줄을 그어서 가슴 높이가 한눈에 보여.」","mis":"K3-2-u2-X23"}],"explanation":["제목이 가장 먼저 눈에 들어와야 해요.","설명은 그림 아래 작은 글씨예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["맨 위 — 「줄 길이 맞추기」 (가장 크게)","가운데 — 줄 가운데를 밟고 손잡이를 당긴 그림 · 손잡이 끝에 굵은 가로줄 하나","그림 아래 — “손잡이 끝이 가슴 높이쯤” (작은 글씨)","맨 아래 — 너무 길 때와 짧을 때 그림 둘"],"title":"태경이가 짠 얼개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_challenge#5','kor',3,2,'u2','L08','g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C13',3,'ox','auto','태경이의 얼개에서 「너무 길 때와 짧을 때 그림 둘」은 처음 하는 친구에게 왜 길이를 맞춰야 하는지 보여 주는 데 도움이 돼요.',ARRAY['K3-2-u2-X23']::text[],false,'{"seq":5,"concept":"K3-2-u2-C13","difficulty":3,"kind":"ox","stem":"태경이의 얼개에서 「너무 길 때와 짧을 때 그림 둘」은 처음 하는 친구에게 왜 길이를 맞춰야 하는지 보여 주는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"발에 걸리거나 머리에 스치는 모습을 한눈에 보여 주기 때문에","correct":true},{"t":"그림이 많을수록 언제나 좋은 자료이기 때문에","mis":"K3-2-u2-X23"}],"mis":"K3-2-u2-X23","explanation":["㉮에 너무 길 때와 짧을 때가 나와요.","그 모습을 그림이 보여 줘요.","그래서 O예요."],"asset":{"type":"passage","lines":["맨 위 — 「줄 길이 맞추기」 (가장 크게)","가운데 — 줄 가운데를 밟고 손잡이를 당긴 그림 · 손잡이 끝에 굵은 가로줄 하나","그림 아래 — “손잡이 끝이 가슴 높이쯤” (작은 글씨)","맨 아래 — 너무 길 때와 짧을 때 그림 둘"],"title":"태경이가 짠 얼개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_challenge#6','kor',3,2,'u2','L08','g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C12',3,'match','auto','발표하는 친구와 목적에 맞게 넣을 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u2-C12","difficulty":3,"kind":"match","stem":"발표하는 친구와 목적에 맞게 넣을 내용을 알맞게 이으세요.","pairs":[{"l":"처음 하는 친구에게 알려 줄 태경","r":"손잡이 끝이 가슴 높이쯤"},{"l":"뛰는 방법을 보여 줄 나겸","r":"두 발 모아 뛰기부터 두 번 돌리기까지"},{"l":"운동장에 붙일 우담","r":"두 팔을 벌려도 닿지 않게 사이 띄우기"}],"mis":"K3-2-u2-X21","explanation":["누구에게, 왜 알려 주는지 봐요.","목적이 정해지면 넣을 것도 정해져요.","친구마다 내용이 달라요."],"asset":{"type":"speech","turns":[{"who":"태경","text":"나는 처음 하는 친구에게 알려 주려고 「줄 길이 맞추기」를 고를래."},{"who":"나겸","text":"나는 「뛰는 방법」 세 가지를 그림으로 보여 줄래."},{"who":"우담","text":"나는 「함께할 때 지킬 것」을 운동장에 붙일 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_challenge#7','kor',3,2,'u2','L08','g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C14',3,'mc','auto','친구 자료를 보고 쓴 쪽지로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X25','K3-2-u2-X24']::text[],false,'{"seq":7,"concept":"K3-2-u2-C14","difficulty":3,"kind":"mc","stem":"친구 자료를 보고 쓴 쪽지로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“사이를 띄우는 그림이 한눈에 보여. 팔 벌린 길이에 화살표를 그리면 더 잘 보이겠어.”","correct":true},{"t":"“최고야! 다 잘했어!”","mis":"K3-2-u2-X25"},{"t":"“글씨가 너무 작아서 못 쓰겠어.”","mis":"K3-2-u2-X25"},{"t":"“내 것이 더 잘 만들었어.”","mis":"K3-2-u2-X24"}],"explanation":["잘한 곳 한 가지를 써요.","더 잘 보이게 할 방법 한 가지를 써요.","두 줄이면 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_challenge#8','kor',3,2,'u2','L08','g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C13',4,'mc','auto','「줄 길이 맞추기」 자료에서 제목·그림·설명을 모두 빨강·노랑·파랑으로 칠하고 글씨도 모두 같은 크기로 크게 썼어요. 이 자료를 고칠 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X23','K3-2-u2-X19']::text[],false,'{"seq":8,"concept":"K3-2-u2-C13","difficulty":4,"kind":"mc","stem":"「줄 길이 맞추기」 자료에서 제목·그림·설명을 모두 빨강·노랑·파랑으로 칠하고 글씨도 모두 같은 크기로 크게 썼어요. 이 자료를 고칠 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"제목은 가장 크게, 설명은 작게 하고, 색은 가슴 높이를 가리키는 가로줄처럼 전하려는 곳에만 쓴다","correct":true},{"t":"색을 더 많이 칠해 더 알록달록하게 한다","mis":"K3-2-u2-X23"},{"t":"글씨를 모두 더 크게 쓴다","mis":"K3-2-u2-X23"},{"t":"그림을 지우고 글만 남긴다","mis":"K3-2-u2-X19"}],"explanation":["모두 크고 모두 알록달록하면 무엇이 중요한지 몰라요.","크기로 차례를 정해요.","색은 전하려는 곳에만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_challenge#9','kor',3,2,'u2','L08','g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C12',4,'essay','teacher','「줄넘기」 네 도막 가운데 하나를 골라 누구에게, 왜 알려 줄지 정하고, 그 목적에 맞게 발표 자료에 넣을 내용 두 가지를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C12","difficulty":4,"kind":"essay","stem":"「줄넘기」 네 도막 가운데 하나를 골라 누구에게, 왜 알려 줄지 정하고, 그 목적에 맞게 발표 자료에 넣을 내용 두 가지를 쓰세요.","answer_guide":{"answer":"예: 도막 — ㉰ 함께할 때 지킬 것. 누구에게·왜 — 체육 시간에 여럿이 함께 줄넘기를 하는 우리 반 친구들이 서로 부딪히지 않게 하려고. 넣을 내용 — 두 팔을 옆으로 벌려도 닿지 않게 사이 띄우기, 앞뒤로도 한 걸음 넘게 띄우기.","scoring_points":["도막을 하나 골랐는가","누구에게, 왜 알려 줄지 정했는가","목적에 맞는 내용 두 가지를 썼는가"]},"explanation":["도막을 골라요.","누구에게, 왜를 먼저 정해요.","목적에 맞는 것만 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L08_challenge#10','kor',3,2,'u2','L08','g3_2_kor_u2_L08_challenge','lesson_challenge','K3-2-u2-C13',4,'essay','teacher','「줄넘기」 ㉯ 「뛰는 방법」으로 발표 자료의 얼개를 짠다면 맨 위·가운데·그림 아래에 각각 무엇을 놓을지 쓰고, 색이나 크기를 어디에 쓸지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C13","difficulty":4,"kind":"essay","stem":"「줄넘기」 ㉯ 「뛰는 방법」으로 발표 자료의 얼개를 짠다면 맨 위·가운데·그림 아래에 각각 무엇을 놓을지 쓰고, 색이나 크기를 어디에 쓸지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 맨 위 — 「뛰는 방법 세 가지」를 가장 크게 쓴다. 가운데 — 두 발 모아 뛰기, 한 발씩 번갈아 뛰기, 두 번 돌리기를 번호를 붙인 그림 셋으로 그린다. 그림 아래 — 그림마다 한 줄 설명을 작게 쓴다. 두 번 돌리기의 줄에만 빨간색을 칠해, 더 빠르게 돌려야 한다는 것이 눈에 띄게 한다.","scoring_points":["맨 위·가운데·그림 아래에 놓을 것을 썼는가","자리에 맞는 것을 놓았는가","색이나 크기를 쓸 곳과 까닭을 썼는가"]},"explanation":["제목은 맨 위예요.","그림은 가운데, 설명은 그 아래예요.","전하려는 곳에만 색을 써요."],"asset":{"type":"passage","lines":["㉮ 줄 길이 맞추기","줄 가운데를 한 발로 밟고 손잡이를 위로 당겨 봅니다. 손잡이 끝이 가슴 높이쯤에 오면 알맞습니다.","줄이 너무 길면 발에 걸리고, 너무 짧으면 머리에 스칩니다.","㉯ 뛰는 방법","두 발을 모아 뛰는 방법이 가장 기본입니다. 한 발씩 번갈아 뛰는 방법도 있습니다.","한 번 뛰는 동안 줄을 두 번 돌리는 방법은 더 빠르게 돌려야 합니다."],"title":"자료 「줄넘기」 ㉮ · ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_basic#1','kor',3,2,'u2','L11','g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C15',1,'mc','auto','짧은 이야기를 소개할 때 고를 그림으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X21','K3-2-u2-X23']::text[],false,'{"seq":1,"concept":"K3-2-u2-C15","difficulty":1,"kind":"mc","stem":"짧은 이야기를 소개할 때 고를 그림으로 알맞은 것은 무엇인가요?","options":[{"t":"이야기에서 중요한 장면이 드러난 그림","correct":true},{"t":"가장 예쁜 그림","mis":"K3-2-u2-X21"},{"t":"색이 가장 많은 그림","mis":"K3-2-u2-X23"},{"t":"이야기와 상관없이 내가 좋아하는 그림","mis":"K3-2-u2-X21"}],"explanation":["그림을 보고 친구가 「무슨 이야기구나」 알아야 해요.","흐름에서 중요한 장면이에요.","예쁜 것이 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_basic#2','kor',3,2,'u2','L11','g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C15',1,'mc','auto','친구가 발표할 때 내가 할 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X26']::text[],false,'{"seq":2,"concept":"K3-2-u2-C15","difficulty":1,"kind":"mc","stem":"친구가 발표할 때 내가 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"끝까지 듣고 좋았던 곳을 말해 준다","correct":true},{"t":"내 차례만 준비하고 있는다","mis":"K3-2-u2-X26"},{"t":"내용과 상관없이 박수만 친다","mis":"K3-2-u2-X26"},{"t":"다른 친구와 이야기한다","mis":"K3-2-u2-X26"}],"explanation":["내가 발표할 때를 떠올려요.","친구가 들어 주면 힘이 나요.","좋았던 곳을 말해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_basic#3','kor',3,2,'u2','L11','g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C16',1,'mc','auto','바르게 띄어 쓴 문장은 무엇인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":3,"concept":"K3-2-u2-C16","difficulty":1,"kind":"mc","stem":"바르게 띄어 쓴 문장은 무엇인가요?","options":[{"t":"혼자 갈 수 있다.","correct":true},{"t":"혼자 갈수 있다.","mis":"K3-2-u2-X27"},{"t":"혼자 갈 수있다.","mis":"K3-2-u2-X27"},{"t":"혼자갈수있다.","mis":"K3-2-u2-X27"}],"explanation":["‘수’ 앞뒤를 모두 봐요.","‘수’는 앞말과 띄어 써요.","뒷말과도 띄어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_basic#4','kor',3,2,'u2','L11','g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C17',1,'ox','auto','물건에 새 이름을 지을 때는 그 물건의 생김새나 하는 일이 드러나게 지어요.',ARRAY['K3-2-u2-X29']::text[],false,'{"seq":4,"concept":"K3-2-u2-C17","difficulty":1,"kind":"ox","stem":"물건에 새 이름을 지을 때는 그 물건의 생김새나 하는 일이 드러나게 지어요.","answer":"O","reason_options":[{"t":"이름에 특징이 드러나야 처음 듣는 사람도 무엇인지 알 수 있기 때문에","correct":true},{"t":"이름은 소리가 예쁘기만 하면 되기 때문에","mis":"K3-2-u2-X29"}],"mis":"K3-2-u2-X29","explanation":["생김새나 하는 일을 살펴요.","그 특징을 이름에 담아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_basic#5','kor',3,2,'u2','L11','g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C15',2,'mc','auto','유창하게 소개하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X02','K3-2-u2-X05']::text[],false,'{"seq":5,"concept":"K3-2-u2-C15","difficulty":2,"kind":"mc","stem":"유창하게 소개하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"내용에 어울리는 목소리로 또박또박 읽기","correct":true},{"t":"누구보다 빨리 읽어 내기","mis":"K3-2-u2-X01"},{"t":"처음부터 끝까지 가장 큰 소리로 읽기","mis":"K3-2-u2-X02"},{"t":"바닥만 보며 쉬지 않고 읽기","mis":"K3-2-u2-X05"}],"explanation":["듣는 친구에게 내용이 전해져야 해요.","빠르기·크기가 기준이 아니에요.","또박또박, 어울리는 목소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_basic#6','kor',3,2,'u2','L11','g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C15',2,'match','auto','「관심 있는 일 발표하기」에서 나타내려는 것과 알맞은 방법을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u2-C15","difficulty":2,"kind":"match","stem":"「관심 있는 일 발표하기」에서 나타내려는 것과 알맞은 방법을 이으세요.","pairs":[{"l":"일할 때 입는 옷의 생김새","r":"그림으로 그려 보여 주기"},{"l":"그 일을 하려면 무엇이 필요한지","r":"글로 자세히 쓰기"},{"l":"하루에 하는 일의 차례","r":"번호를 붙인 그림으로 나타내기"}],"mis":"K3-2-u2-X19","explanation":["말로 설명하기 어려운 것은 그림이에요.","자세한 것은 글이에요.","차례는 번호 붙인 그림이에요."],"asset":{"type":"speech","turns":[{"who":"한울","text":"나는 별을 살피는 일이 궁금해서 그 일을 소개할래."},{"who":"예하","text":"나는 학교 텃밭을 돌보는 일을 소개할래."},{"who":"한슬","text":"나는 급식을 만드는 일을 소개할래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_basic#7','kor',3,2,'u2','L11','g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C16',2,'mc','auto','앞말과 띄어 써야 하는 것은 무엇인가요?',ARRAY['K3-2-u2-X28']::text[],false,'{"seq":7,"concept":"K3-2-u2-C16","difficulty":2,"kind":"mc","stem":"앞말과 띄어 써야 하는 것은 무엇인가요?","options":[{"t":"먹을 것","correct":true},{"t":"줄넘기","mis":"K3-2-u2-X28"},{"t":"수요일","mis":"K3-2-u2-X28"},{"t":"수박","mis":"K3-2-u2-X28"}],"explanation":["‘것·수·줄’이 혼자 떨어져 있나 봐요.","한 낱말 속에 든 것은 붙여 써요.","「먹을 것」의 ‘것’은 띄어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_basic#8','kor',3,2,'u2','L11','g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C16',2,'ox','auto','「줄넘기」의 「줄」도 ‘것·수·줄’의 ‘줄’이니까 「줄 넘기」로 띄어 써야 해요.',ARRAY['K3-2-u2-X28']::text[],false,'{"seq":8,"concept":"K3-2-u2-C16","difficulty":2,"kind":"ox","stem":"「줄넘기」의 「줄」도 ‘것·수·줄’의 ‘줄’이니까 「줄 넘기」로 띄어 써야 해요.","answer":"X","reason_options":[{"t":"「줄넘기」는 한 낱말이라 그 속의 「줄」은 붙여 쓰기 때문에","correct":true},{"t":"「줄」은 어디에 있든 언제나 띄어 쓰기 때문에","mis":"K3-2-u2-X28"}],"mis":"K3-2-u2-X28","explanation":["줄넘기는 한 낱말이에요.","다른 말에 기대는 ‘줄’이 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_basic#9','kor',3,2,'u2','L11','g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C17',2,'match','auto','물건의 특징과 새로 지은 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C17","difficulty":2,"kind":"match","stem":"물건의 특징과 새로 지은 이름을 알맞게 이으세요.","pairs":[{"l":"종이를 집어 한데 물려 두는 작은 쇠붙이","r":"종이물림이"},{"l":"물을 빨아들였다가 짜면 나오는 말랑한 것","r":"물먹는솜"},{"l":"문질러 색을 칠하는 굵은 막대","r":"문질러그림막대"}],"mis":"K3-2-u2-X29","explanation":["그 물건이 무엇을 하는지 생각해요.","이름에 그 말이 들어 있나요?","특징이 드러나는 이름과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_basic#10','kor',3,2,'u2','L11','g3_2_kor_u2_L11_basic','lesson_basic','K3-2-u2-C16',3,'error','auto','‘것·수·줄’ 띄어쓰기를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X28','K3-2-u2-X27']::text[],false,'{"seq":10,"concept":"K3-2-u2-C16","difficulty":3,"kind":"error","stem":"‘것·수·줄’ 띄어쓰기를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「‘줄’이라는 글자가 보이면 무조건 띄어 써.」","correct":true,"mis_target":"K3-2-u2-X28"},{"t":"친구 가 — 「‘것·수·줄’은 다른 말에 기대어 쓰여서 앞말과 띄어 써.」","mis":"K3-2-u2-X27"},{"t":"친구 나 — 「줄넘기·수요일처럼 한 낱말 속에 있으면 붙여 써.」","mis":"K3-2-u2-X28"}],"explanation":["규칙에는 조건이 있어요.","다른 말에 기댈 때만 띄어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_challenge#1','kor',3,2,'u2','L11','g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C16',2,'sa','auto','「우산을 접을 줄 안다.」에서 앞말과 띄어 쓴 한 글자 말은 무엇인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u2-C16","difficulty":2,"kind":"sa","stem":"「우산을 접을 줄 안다.」에서 앞말과 띄어 쓴 한 글자 말은 무엇인가요? 한 글자로 쓰세요.","answer":["줄"],"explanation":["‘것·수·줄’ 가운데 하나예요.","「접을」 다음에 띄어 썼어요.","‘줄’이에요."],"mis":"K3-2-u2-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_challenge#2','kor',3,2,'u2','L11','g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C15',2,'mc','auto','소개하고 싶은 물건을 설명하는 글을 쓸 때 넣을 것으로 알맞은 차례는 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":2,"concept":"K3-2-u2-C15","difficulty":2,"kind":"mc","stem":"소개하고 싶은 물건을 설명하는 글을 쓸 때 넣을 것으로 알맞은 차례는 무엇인가요?","options":[{"t":"무엇인가요 → 왜 소개하고 싶은가요 → 어떤 물건인가요","correct":true},{"t":"얼마인가요 → 어디서 샀나요 → 누가 샀나요","mis":"K3-2-u2-X21"},{"t":"어떤 물건인가요 → 언제 버렸나요 → 무엇인가요","mis":"K3-2-u2-X21"},{"t":"왜 싫은가요 → 무엇인가요 → 얼마인가요","mis":"K3-2-u2-X21"}],"explanation":["활동 ③의 세 물음이에요.","무엇 · 왜 · 어떤 물건이에요.","값이나 산 곳은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_challenge#3','kor',3,2,'u2','L11','g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C16',3,'mc','auto','띄어쓰기가 모두 바른 문장은 무엇인가요?',ARRAY['K3-2-u2-X28','K3-2-u2-X27']::text[],false,'{"seq":3,"concept":"K3-2-u2-C16","difficulty":3,"kind":"mc","stem":"띄어쓰기가 모두 바른 문장은 무엇인가요?","options":[{"t":"줄넘기를 할 줄 아는 사람은 이쪽으로 올 수 있다.","correct":true},{"t":"줄 넘기를 할줄 아는 사람은 이쪽으로 올수 있다.","mis":"K3-2-u2-X28"},{"t":"줄넘기를 할줄 아는 사람은 이쪽으로 올 수 있다.","mis":"K3-2-u2-X27"},{"t":"줄넘기를 할 줄 아는 사람은 이쪽으로 올수 있다.","mis":"K3-2-u2-X27"}],"explanation":["줄넘기는 붙여 써요.","「할 줄」·「올 수」는 띄어 써요.","셋을 모두 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_challenge#4','kor',3,2,'u2','L11','g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C15',3,'error','auto','이야기를 소개할 그림을 두고 말했어요. 알맞지 않게 고른 친구는 누구인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":4,"concept":"K3-2-u2-C15","difficulty":3,"kind":"error","stem":"이야기를 소개할 그림을 두고 말했어요. 알맞지 않게 고른 친구는 누구인가요?","options":[{"t":"친구 나 — 「「말린 실내화」에서 신발장 색이 가장 예쁘게 나온 그림을 고를래.」","correct":true,"mis_target":"K3-2-u2-X21"},{"t":"친구 가 — 「「말린 실내화」에서 쪽지를 발견하는 장면 그림을 고를래.」","mis":"K3-2-u2-X21"},{"t":"친구 다 — 「유빈이가 젖은 양말로 혼자 참는 장면 그림을 고를래.」","mis":"K3-2-u2-X21"}],"explanation":["그림은 흐름에서 중요한 장면이에요.","쪽지 · 혼자 참음은 중요한 장면이에요.","친구 나는 예쁜 것으로 골랐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_challenge#5','kor',3,2,'u2','L11','g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C15',3,'ox','auto','우리 반이 새 활동을 정할 때에도 「유창하게 소리 내어 읽기」와 「글과 그림을 함께 써서 알려 주기」는 꼭 들어가야 해요.',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":5,"concept":"K3-2-u2-C15","difficulty":3,"kind":"ox","stem":"우리 반이 새 활동을 정할 때에도 「유창하게 소리 내어 읽기」와 「글과 그림을 함께 써서 알려 주기」는 꼭 들어가야 해요.","answer":"O","reason_options":[{"t":"이 단원에서 배운 두 가지를 실천하는 활동이어야 하기 때문에","correct":true},{"t":"새 활동은 배운 것과 상관없이 아무것이나 해도 되기 때문에","mis":"K3-2-u2-X21"}],"mis":"K3-2-u2-X21","explanation":["활동은 새로 정해도 돼요.","다만 두 가지는 꼭 들어가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_challenge#6','kor',3,2,'u2','L11','g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C16',3,'match','auto','문장과 바르게 띄어 쓴 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u2-C16","difficulty":3,"kind":"match","stem":"문장과 바르게 띄어 쓴 까닭을 알맞게 이으세요.","pairs":[{"l":"벌써 다 읽은 것 같다.","r":"‘것’이 앞말에 기대어 쓰여 띄어 쓴다"},{"l":"수요일에 만나자.","r":"‘수’가 한 낱말 속에 있어 붙여 쓴다"},{"l":"혼자 접을 수 있다.","r":"‘수’가 앞말에 기대어 쓰여 띄어 쓴다"}],"mis":"K3-2-u2-X28","explanation":["‘것·수’가 혼자 떨어져 있는지 봐요.","수요일은 한 낱말이에요.","까닭과 짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_challenge#7','kor',3,2,'u2','L11','g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C17',3,'mc','auto','손으로 누르면 종이에 둥근 구멍이 뚫리는 물건에 지은 이름으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X29']::text[],false,'{"seq":7,"concept":"K3-2-u2-C17","difficulty":3,"kind":"mc","stem":"손으로 누르면 종이에 둥근 구멍이 뚫리는 물건에 지은 이름으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"눌러구멍이","correct":true},{"t":"반짝돌이","mis":"K3-2-u2-X29"},{"t":"동글동글","mis":"K3-2-u2-X29"},{"t":"종이친구","mis":"K3-2-u2-X29"}],"explanation":["하는 일은 누르기와 구멍 뚫기예요.","이름에 그 말이 들어 있나요?","눌러구멍이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_challenge#8','kor',3,2,'u2','L11','g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C15',4,'mc','auto','한울이는 「별을 살피는 일」을 발표하려고 해요. 글로 쓸 것과 그림으로 보일 것을 가장 알맞게 가른 것은 무엇인가요?',ARRAY['K3-2-u2-X19','K3-2-u2-X18']::text[],false,'{"seq":8,"concept":"K3-2-u2-C15","difficulty":4,"kind":"mc","stem":"한울이는 「별을 살피는 일」을 발표하려고 해요. 글로 쓸 것과 그림으로 보일 것을 가장 알맞게 가른 것은 무엇인가요?","options":[{"t":"그 일을 하려면 무엇이 필요한지는 글로, 별을 보는 기구의 생김새는 그림으로","correct":true},{"t":"모두 글로 쓰고 그림은 넣지 않는다","mis":"K3-2-u2-X19"},{"t":"기구의 생김새는 글로, 필요한 것은 그림으로","mis":"K3-2-u2-X19"},{"t":"하늘을 칠한 예쁜 그림 한 장만 넣는다","mis":"K3-2-u2-X18"}],"explanation":["생김새는 말로 설명하기 어려워요.","필요한 것은 글로 자세히 써요.","할 일을 나누어요."],"asset":{"type":"speech","turns":[{"who":"한울","text":"나는 별을 살피는 일이 궁금해서 그 일을 소개할래."},{"who":"예하","text":"나는 학교 텃밭을 돌보는 일을 소개할래."},{"who":"한슬","text":"나는 급식을 만드는 일을 소개할래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_challenge#9','kor',3,2,'u2','L11','g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C15',4,'essay','teacher','세 가지 활동(짧은 이야기 소개하기 · 관심 있는 일 발표하기 · 소개하고 싶은 물건 설명하기) 가운데 하나를 골라, 무엇을 소개할지 정하고 글로 쓸 것 하나와 그림으로 보일 것 하나, 유창하게 읽으려고 할 일 하나를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u2-C15","difficulty":4,"kind":"essay","stem":"세 가지 활동(짧은 이야기 소개하기 · 관심 있는 일 발표하기 · 소개하고 싶은 물건 설명하기) 가운데 하나를 골라, 무엇을 소개할지 정하고 글로 쓸 것 하나와 그림으로 보일 것 하나, 유창하게 읽으려고 할 일 하나를 쓰세요.","answer_guide":{"answer":"예: 활동 — 소개하고 싶은 물건 설명하기. 소개할 것 — 할머니께서 떠 주신 장갑. 글로 쓸 것 — 왜 소개하고 싶은지(추운 날 손이 따뜻했던 일). 그림으로 보일 것 — 손가락 부분 무늬의 생김새. 유창하게 읽기 — 「따뜻했다」에서 마음이 드러나게 천천히 읽고, 친구들을 가끔 바라본다.","scoring_points":["활동과 소개할 것을 정했는가","글로 쓸 것과 그림으로 보일 것을 갈라 썼는가","유창하게 읽으려고 할 일을 썼는가"]},"explanation":["활동을 하나 골라요.","글이 할 일과 그림이 할 일을 갈라요.","빠르기보다 뜻이 전해지게 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_L11_challenge#10','kor',3,2,'u2','L11','g3_2_kor_u2_L11_challenge','lesson_challenge','K3-2-u2-C16',4,'essay','teacher','‘것’, ‘수’, ‘줄’을 하나씩 넣어 이 단원에서 읽은 글(「우산」·「줄넘기」 등)과 이어지는 문장을 세 개 만들고, 띄어 쓴 까닭을 쓰세요. 「줄넘기」라는 낱말도 한 번 넣어 붙여 쓴 까닭도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u2-C16","difficulty":4,"kind":"essay","stem":"‘것’, ‘수’, ‘줄’을 하나씩 넣어 이 단원에서 읽은 글(「우산」·「줄넘기」 등)과 이어지는 문장을 세 개 만들고, 띄어 쓴 까닭을 쓰세요. 「줄넘기」라는 낱말도 한 번 넣어 붙여 쓴 까닭도 쓰세요.","answer_guide":{"answer":"예: 비 온 뒤에는 우산을 말려 둘 것을 잊지 않는다. 줄 길이를 맞추면 줄넘기를 더 오래 할 수 있다. 나는 두 발 모아 뛸 줄 안다. ‘것·수·줄’은 혼자 쓰이지 못하고 앞말에 기대어 쓰이므로 띄어 썼다. 「줄넘기」의 ‘줄’은 한 낱말 속에 들어 있어서 붙여 썼다.","scoring_points":["‘것·수·줄’을 넣은 문장 세 개를 바르게 띄어 썼는가","띄어 쓴 까닭을 썼는가","「줄넘기」를 붙여 쓴 까닭을 썼는가"]},"explanation":["‘것·수·줄’마다 문장을 하나씩 만들어요.","앞말과 띄어 써요.","한 낱말 속은 붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#1','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C1',1,'mc','auto','1차시와 13차시에서 다시 만난 물음 「글을 잘 읽는다는 것은?」의 답은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X02']::text[],false,'{"seq":1,"concept":"K3-2-u2-C1","difficulty":1,"kind":"mc","stem":"1차시와 13차시에서 다시 만난 물음 「글을 잘 읽는다는 것은?」의 답은 무엇인가요?","options":[{"t":"듣는 사람에게 뜻이 전해지게 읽는 것","correct":true},{"t":"남보다 빨리 읽는 것","mis":"K3-2-u2-X01"},{"t":"가장 큰 소리로 읽는 것","mis":"K3-2-u2-X02"},{"t":"외워서 읽는 것","mis":"K3-2-u2-X01"}],"explanation":["처음과 끝에 같은 물음이 나왔어요.","빠르기도 크기도 아니에요.","뜻이 전해지는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#2','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C2',1,'mc','auto','≡ 표시는 어떻게 읽으라는 뜻인가요?',ARRAY['K3-2-u2-X06','K3-2-u2-X02','K3-2-u2-X01']::text[],false,'{"seq":2,"concept":"K3-2-u2-C2","difficulty":1,"kind":"mc","stem":"≡ 표시는 어떻게 읽으라는 뜻인가요?","options":[{"t":"조금 더 길게 쉬어 읽는다","correct":true},{"t":"조금 쉬어 읽는다","mis":"K3-2-u2-X06"},{"t":"큰 소리로 읽는다","mis":"K3-2-u2-X02"},{"t":"빨리 읽는다","mis":"K3-2-u2-X01"}],"explanation":["∨ 는 조금 쉬어요.","≡ 는 문장 끝에 와요.","조금 더 길게 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#3','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C4',1,'mc','auto','「연필깎이」에서 연필을 깎을 때 하는 일은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":3,"concept":"K3-2-u2-C4","difficulty":1,"kind":"mc","stem":"「연필깎이」에서 연필을 깎을 때 하는 일은 무엇인가요?","options":[{"t":"연필을 구멍에 끝까지 넣고 손잡이를 돌린다","correct":true},{"t":"연필을 물에 담근다","mis":"K3-2-u2-X15"},{"t":"연필을 바닥에 두드린다","mis":"K3-2-u2-X15"},{"t":"손잡이를 떼어 낸다","mis":"K3-2-u2-X15"}],"explanation":["두 번째 줄을 읽어요.","넣고 돌려요.","손잡이를 돌려요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#4','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C5',1,'mc','auto','「걸린 종이비행기」 ①에서 종이비행기는 어디에 걸렸나요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":4,"concept":"K3-2-u2-C5","difficulty":1,"kind":"mc","stem":"「걸린 종이비행기」 ①에서 종이비행기는 어디에 걸렸나요?","options":[{"t":"키 큰 나무의 가지 끝","correct":true},{"t":"교실 창문","mis":"K3-2-u2-X15"},{"t":"운동장 철봉","mis":"K3-2-u2-X15"},{"t":"은솔이 가방","mis":"K3-2-u2-X15"}],"explanation":["네 번째 줄을 읽어요.","툭 걸렸어요.","나무의 가지 끝이에요."],"asset":{"type":"passage","lines":["점심시간, 은솔이는 새로 접은 종이비행기를 힘껏 날렸다.","비행기는 운동장 위를 빙글 돌며 멀리 날아갔다.","은솔이는 손뼉을 치며 그 뒤를 쫓아 달렸다.","그런데 비행기가 키 큰 나무의 가지 끝에 툭 걸리고 말았다.","은솔이는 나무 아래에 서서 한참 동안 가지만 올려다보았다.","종이 울리자 친구들은 하나둘 교실로 들어갔다."],"title":"이야기 「걸린 종이비행기」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#5','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C8',1,'mc','auto','「다독이다」와 뜻이 비슷한 말은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":5,"concept":"K3-2-u2-C8","difficulty":1,"kind":"mc","stem":"「다독이다」와 뜻이 비슷한 말은 무엇인가요?","options":[{"t":"달래다","correct":true},{"t":"둘러보다","mis":"K3-2-u2-X16"},{"t":"급히 하다","mis":"K3-2-u2-X16"},{"t":"밀어내다","mis":"K3-2-u2-X16"}],"explanation":["어깨를 다독여 주었어요.","마음을 가라앉혀 주는 거예요.","달래다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#6','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C10',1,'mc','auto','설명할 때 글만 있으면 어떤가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":6,"concept":"K3-2-u2-C10","difficulty":1,"kind":"mc","stem":"설명할 때 글만 있으면 어떤가요?","options":[{"t":"자세하지만 한눈에 안 들어온다","correct":true},{"t":"한눈에 들어오지만 자세하지 않다","mis":"K3-2-u2-X19"},{"t":"자세하고 한눈에 들어온다","mis":"K3-2-u2-X19"},{"t":"아무것도 알 수 없다","mis":"K3-2-u2-X19"}],"explanation":["글과 그림은 하는 일이 달라요.","글은 자세해요.","그런데 한눈에는 안 들어와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#7','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C13',1,'mc','auto','발표 자료를 만들 때 얼개를 먼저 짜는 까닭은 무엇인가요?',ARRAY['K3-2-u2-X23','K3-2-u2-X19','K3-2-u2-X01']::text[],false,'{"seq":7,"concept":"K3-2-u2-C13","difficulty":1,"kind":"mc","stem":"발표 자료를 만들 때 얼개를 먼저 짜는 까닭은 무엇인가요?","options":[{"t":"어디에 무엇을 놓을지 미리 정해 만들 때 헤매지 않으려고","correct":true},{"t":"자료를 알록달록하게 하려고","mis":"K3-2-u2-X23"},{"t":"그림을 안 그리려고","mis":"K3-2-u2-X19"},{"t":"발표를 빨리 끝내려고","mis":"K3-2-u2-X01"}],"explanation":["얼개는 자리 정하기예요.","미리 정하면 헤매지 않아요.","그래서 먼저 짜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#8','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C16',1,'mc','auto','바르게 띄어 쓴 것은 무엇인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":8,"concept":"K3-2-u2-C16","difficulty":1,"kind":"mc","stem":"바르게 띄어 쓴 것은 무엇인가요?","options":[{"t":"읽을 것","correct":true},{"t":"읽을것","mis":"K3-2-u2-X27"},{"t":"읽 을것","mis":"K3-2-u2-X27"},{"t":"읽을 거","mis":"K3-2-u2-X27"}],"explanation":["‘것’은 앞말과 띄어 써요.","「읽을」 다음에 띄어요.","「읽을 것」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#9','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C2',2,'mc','auto','「연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.」에서 ∨ 를 넣기에 가장 알맞은 곳은 어디인가요?',ARRAY['K3-2-u2-X05','K3-2-u2-X04']::text[],false,'{"seq":9,"concept":"K3-2-u2-C2","difficulty":2,"kind":"mc","stem":"「연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.」에서 ∨ 를 넣기에 가장 알맞은 곳은 어디인가요?","options":[{"t":"「넣고」 다음","correct":true},{"t":"「연필을」 다음과 「구멍에」 다음과 「끝까지」 다음 모두","mis":"K3-2-u2-X05"},{"t":"「손잡이를」 다음","mis":"K3-2-u2-X04"},{"t":"「구멍에」 다음","mis":"K3-2-u2-X04"}],"explanation":["두 가지 일이 이어져 있어요.","넣는 일과 돌리는 일 사이에서 쉬어요.","「넣고」 다음이에요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#10','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C3',2,'mc','auto','교실 뒤 쓰레기통 위에 종이컵 그림을 붙여 두면 좋은 점은 무엇인가요?',ARRAY['K3-2-u2-X07']::text[],false,'{"seq":10,"concept":"K3-2-u2-C3","difficulty":2,"kind":"mc","stem":"교실 뒤 쓰레기통 위에 종이컵 그림을 붙여 두면 좋은 점은 무엇인가요?","options":[{"t":"종이컵을 어디에 버릴지 글을 읽지 않아도 한눈에 안다","correct":true},{"t":"쓰레기통이 예뻐진다","mis":"K3-2-u2-X07"},{"t":"종이컵이 덜 생긴다","mis":"K3-2-u2-X07"},{"t":"글씨를 안 써도 되어 편하다","mis":"K3-2-u2-X07"}],"explanation":["그림 기호는 할 일을 알려 줘요.","바쁠 때도 한눈에 알아봐요.","버릴 곳을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#11','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C5',2,'mc','auto','「걸린 종이비행기」 ①에서 은솔이의 마음을 짐작할 수 있는 곳은 어디인가요?',ARRAY['K3-2-u2-X11']::text[],false,'{"seq":11,"concept":"K3-2-u2-C5","difficulty":2,"kind":"mc","stem":"「걸린 종이비행기」 ①에서 은솔이의 마음을 짐작할 수 있는 곳은 어디인가요?","options":[{"t":"“나무 아래에 서서 한참 동안 가지만 올려다보았다”","correct":true},{"t":"“점심시간”","mis":"K3-2-u2-X11"},{"t":"“종이 울리자”","mis":"K3-2-u2-X11"},{"t":"“운동장 위를 빙글 돌며”","mis":"K3-2-u2-X11"}],"explanation":["인물의 행동을 찾아요.","한참 동안 올려다본 것이 행동이에요.","그 행동에서 마음이 보여요."],"asset":{"type":"passage","lines":["점심시간, 은솔이는 새로 접은 종이비행기를 힘껏 날렸다.","비행기는 운동장 위를 빙글 돌며 멀리 날아갔다.","은솔이는 손뼉을 치며 그 뒤를 쫓아 달렸다.","그런데 비행기가 키 큰 나무의 가지 끝에 툭 걸리고 말았다.","은솔이는 나무 아래에 서서 한참 동안 가지만 올려다보았다.","종이 울리자 친구들은 하나둘 교실로 들어갔다."],"title":"이야기 「걸린 종이비행기」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#12','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C6',2,'mc','auto','「은솔이는 나무 아래에 서서 한참 동안 가지만 올려다보았다.」를 읽는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X13','K3-2-u2-X12']::text[],false,'{"seq":12,"concept":"K3-2-u2-C6","difficulty":2,"kind":"mc","stem":"「은솔이는 나무 아래에 서서 한참 동안 가지만 올려다보았다.」를 읽는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"낮고 느리게, 그러나 뜻은 또렷이 들리게","correct":true},{"t":"아주 크고 빠르게","mis":"K3-2-u2-X13"},{"t":"들리지 않을 만큼 작게","mis":"K3-2-u2-X13"},{"t":"웃음을 섞어 신나게","mis":"K3-2-u2-X12"}],"explanation":["쓸쓸한 장면이에요.","너무 커도, 너무 작아도 안 어울려요.","낮고 느리게, 또렷이 읽어요."],"asset":{"type":"passage","lines":["점심시간, 은솔이는 새로 접은 종이비행기를 힘껏 날렸다.","비행기는 운동장 위를 빙글 돌며 멀리 날아갔다.","은솔이는 손뼉을 치며 그 뒤를 쫓아 달렸다.","그런데 비행기가 키 큰 나무의 가지 끝에 툭 걸리고 말았다.","은솔이는 나무 아래에 서서 한참 동안 가지만 올려다보았다.","종이 울리자 친구들은 하나둘 교실로 들어갔다."],"title":"이야기 「걸린 종이비행기」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#13','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C7',2,'mc','auto','「노란 조끼」에서 노란 조끼를 입은 분에게 처음에 가장 힘들었던 일은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":13,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"「노란 조끼」에서 노란 조끼를 입은 분에게 처음에 가장 힘들었던 일은 무엇인가요?","options":[{"t":"이른 아침에 일어나는 일","correct":true},{"t":"차를 세우는 일","mis":"K3-2-u2-X15"},{"t":"조끼를 빠는 일","mis":"K3-2-u2-X15"},{"t":"아이들과 인사하는 일","mis":"K3-2-u2-X15"}],"explanation":["뒷부분 첫 줄을 읽어요.","처음에 힘들었다고 했어요.","이른 아침에 일어나는 일이에요."],"asset":{"type":"passage","lines":["처음에는 이른 아침에 일어나는 일이 가장 힘들었다고 한다.","그래도 하루도 빠지지 않은 까닭을 이렇게 말했다.","“내가 없는 날, 누가 여기를 살피지?”","봄에는 꽃가루가 날리고 겨울에는 손이 얼었다.","그래도 노란 조끼는 늘 같은 곳에 서 있었다.","아이들은 이제 멀리서도 그 조끼를 알아본다."],"title":"글 「노란 조끼」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#14','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C12',2,'mc','auto','서윤이가 「책 빌리는 차례」로 1학년 동생들에게 발표한다면 꼭 넣어야 할 것은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":14,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"서윤이가 「책 빌리는 차례」로 1학년 동생들에게 발표한다면 꼭 넣어야 할 것은 무엇인가요?","options":[{"t":"책을 골라 가져가기 · 이름 말하기 · 돌려줄 날 확인하기","correct":true},{"t":"도서관에 책이 몇 권 있는지","mis":"K3-2-u2-X21"},{"t":"서윤이가 좋아하는 책 이름","mis":"K3-2-u2-X21"},{"t":"도서관 창문 색깔","mis":"K3-2-u2-X21"}],"explanation":["동생들이 처음 빌려 보는 거예요.","빌리는 차례가 필요해요.","첫째 · 둘째 · 셋째예요."],"asset":{"type":"passage","lines":["도서관에서 책을 빌리는 차례를 알려 드리겠습니다.","첫째, 읽고 싶은 책을 골라 빌리는 곳으로 가져갑니다.","둘째, 내 이름을 말하고 책을 내밉니다.","셋째, 언제까지 돌려주어야 하는지 확인합니다.","빌린 책은 깨끗하게 보고 날짜에 맞추어 돌려줍니다."],"title":"서윤이의 발표 글 「책 빌리는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#15','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C14',2,'mc','auto','서윤이는 그림을 크게, 지안이는 글을 크게 나타냈어요. 둘을 보고 할 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X24']::text[],false,'{"seq":15,"concept":"K3-2-u2-C14","difficulty":2,"kind":"mc","stem":"서윤이는 그림을 크게, 지안이는 글을 크게 나타냈어요. 둘을 보고 할 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“둘 다 빌리는 차례가 잘 보여서 알맞아.”","correct":true},{"t":"“그림이 큰 서윤이 것이 더 나아.”","mis":"K3-2-u2-X24"},{"t":"“글이 많은 지안이 것이 더 나아.”","mis":"K3-2-u2-X24"},{"t":"“둘이 다르니 하나는 틀렸어.”","mis":"K3-2-u2-X24"}],"explanation":["같은 내용도 나타내는 방법은 여러 가지예요.","차례가 잘 보이는지 봐요.","둘 다 알맞아요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 차례마다 번호를 붙인 그림 셋을 크게 그리고, 그림 아래에 짧게 글을 썼어."},{"who":"지안","text":"나는 차례를 글로 크게 쓰고, 옆에 작은 화살표 그림으로 이어 놓았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#16','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C15',2,'mc','auto','「걸린 종이비행기」를 친구들에게 소개할 때 고를 그림으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":16,"concept":"K3-2-u2-C15","difficulty":2,"kind":"mc","stem":"「걸린 종이비행기」를 친구들에게 소개할 때 고를 그림으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"태오가 빗자루 손잡이로 가지를 치는 장면","correct":true},{"t":"빗자루 색이 예쁘게 나온 장면","mis":"K3-2-u2-X21"},{"t":"운동장 구석 화단 장면","mis":"K3-2-u2-X21"},{"t":"교실 시계 장면","mis":"K3-2-u2-X21"}],"explanation":["흐름에서 중요한 장면을 골라요.","비행기를 되찾는 장면이에요.","태오가 도와주는 장면이에요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#17','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C1',3,'error','auto','「연필깎이」를 읽은 친구들을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X02']::text[],false,'{"seq":17,"concept":"K3-2-u2-C1","difficulty":3,"kind":"error","stem":"「연필깎이」를 읽은 친구들을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「가장 빨리 읽은 친구가 가장 잘 읽었어.」","correct":true,"mis_target":"K3-2-u2-X01"},{"t":"친구 가 — 「덩어리마다 쉬어 읽은 친구 덕분에 통을 비우는 까닭이 들렸어.」","mis":"K3-2-u2-X01"},{"t":"친구 다 — 「크기만 큰 것보다 또박또박한 게 더 잘 들렸어.」","mis":"K3-2-u2-X02"}],"explanation":["잘 읽었는지는 듣는 사람이 알아요.","빠르기가 기준이 아니에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#18','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C5',3,'error','auto','「걸린 종이비행기」 ②의 분위기를 두고 말했어요. 까닭을 알맞게 대지 못한 친구는 누구인가요?',ARRAY['K3-2-u2-X10','K3-2-u2-X11']::text[],false,'{"seq":18,"concept":"K3-2-u2-C5","difficulty":3,"kind":"error","stem":"「걸린 종이비행기」 ②의 분위기를 두고 말했어요. 까닭을 알맞게 대지 못한 친구는 누구인가요?","options":[{"t":"친구 다 — 「따뜻해. 다들 그렇게 말했으니까.」","correct":true,"mis_target":"K3-2-u2-X10"},{"t":"친구 가 — 「따뜻해. 태오가 말없이 비행기를 책상에 올려 두었으니까.」","mis":"K3-2-u2-X10"},{"t":"친구 나 — 「마음이 놓여. 은솔이가 비행기를 가슴에 꼭 안았으니까.」","mis":"K3-2-u2-X11"}],"explanation":["까닭은 글 안에 있어야 해요.","다들 그렇게 말한 것은 까닭이 아니에요.","친구 다가 까닭을 대지 못했어요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#19','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C9',3,'error','auto','「걸린 종이비행기」를 읽고 생각을 나누었어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X17']::text[],false,'{"seq":19,"concept":"K3-2-u2-C9","difficulty":3,"kind":"error","stem":"「걸린 종이비행기」를 읽고 생각을 나누었어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「나는 태오가 멋있다고 느꼈어. 그러니 너희도 그렇게 느껴야 해.」","correct":true,"mis_target":"K3-2-u2-X17"},{"t":"친구 가 — 「나는 혼자 올려다보던 은솔이가 마음에 남았어.」","mis":"K3-2-u2-X17"},{"t":"친구 다 — 「나는 날개 끝 글씨가 오래 남았어.」","mis":"K3-2-u2-X17"}],"explanation":["생각이나 느낌은 달라도 괜찮아요.","남에게 같게 느끼라고 할 수 없어요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#20','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C10',3,'error','auto','「연필깎이」로 설명 자료를 만들며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X19']::text[],false,'{"seq":20,"concept":"K3-2-u2-C10","difficulty":3,"kind":"error","stem":"「연필깎이」로 설명 자료를 만들며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「그림만 크게 그리면 「너무 오래 돌리면 짧아진다」는 글은 빼도 돼.」","correct":true,"mis_target":"K3-2-u2-X19"},{"t":"친구 가 — 「구멍에 연필을 넣는 모습은 그림으로 보이면 한눈에 알겠어.」","mis":"K3-2-u2-X19"},{"t":"친구 나 — 「통을 비워야 하는 까닭은 글로 써야 자세히 알 수 있어.」","mis":"K3-2-u2-X19"}],"explanation":["글과 그림은 하는 일이 달라요.","까닭 같은 것은 글로 써야 해요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#21','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C13',3,'error','auto','「책 빌리는 차례」 자료의 얼개를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X22']::text[],false,'{"seq":21,"concept":"K3-2-u2-C13","difficulty":3,"kind":"error","stem":"「책 빌리는 차례」 자료의 얼개를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「그림 설명을 맨 위에 가장 크게 쓰고 제목은 그림 아래 작게 쓰자.」","correct":true,"mis_target":"K3-2-u2-X22"},{"t":"친구 나 — 「맨 위에 「책 빌리는 차례」를 크게 쓰자.」","mis":"K3-2-u2-X22"},{"t":"친구 다 — 「가운데에 번호 그림 셋을 놓고 그 아래 짧은 설명을 쓰자.」","mis":"K3-2-u2-X22"}],"explanation":["제목은 맨 위 크게예요.","설명은 그림 아래 작게예요.","친구 가가 자리를 엇갈리게 놓았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#22','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C16',3,'error','auto','띄어쓰기를 고쳐 쓴 것을 두고 말했어요. 잘못 고친 친구는 누구인가요?',ARRAY['K3-2-u2-X28','K3-2-u2-X27']::text[],false,'{"seq":22,"concept":"K3-2-u2-C16","difficulty":3,"kind":"error","stem":"띄어쓰기를 고쳐 쓴 것을 두고 말했어요. 잘못 고친 친구는 누구인가요?","options":[{"t":"친구 다 — 「수요일」을 「수 요일」로 고쳤다","correct":true,"mis_target":"K3-2-u2-X28"},{"t":"친구 가 — 「깎을수 있다」를 「깎을 수 있다」로 고쳤다","mis":"K3-2-u2-X27"},{"t":"친구 나 — 「비울것」을 「비울 것」으로 고쳤다","mis":"K3-2-u2-X27"}],"explanation":["‘것·수’가 앞말에 기댈 때만 띄어요.","수요일은 한 낱말이에요.","친구 다가 잘못 고쳤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#23','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C1',4,'mc','auto','「연필깎이」를 읽어 준 뒤 듣는 친구가 「통을 왜 비워야 해?」라고 물었어요. 다음에 더 잘 읽으려면 무엇을 고치는 것이 가장 알맞은가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X02','K3-2-u2-X05']::text[],false,'{"seq":23,"concept":"K3-2-u2-C1","difficulty":4,"kind":"mc","stem":"「연필깎이」를 읽어 준 뒤 듣는 친구가 「통을 왜 비워야 해?」라고 물었어요. 다음에 더 잘 읽으려면 무엇을 고치는 것이 가장 알맞은가요?","options":[{"t":"「그래서」 앞에서 ≡ 처럼 길게 쉬고 「통이 가득 차면」을 한 덩어리로 또렷이 읽는다","correct":true},{"t":"더 빠르게 읽어 시간을 줄인다","mis":"K3-2-u2-X01"},{"t":"더 큰 소리로 읽는다","mis":"K3-2-u2-X02"},{"t":"낱말마다 다 끊어 읽는다","mis":"K3-2-u2-X05"}],"explanation":["듣는 사람이 까닭을 놓쳤어요.","찌꺼기 → 그래서 비운다가 이어져야 해요.","쉬는 곳과 덩어리를 고쳐요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#24','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C2',4,'essay','teacher','「연필깎이」에서 문장 두 개를 골라 ∨ 와 ≡ 를 넣어 다시 쓰고, 쉰 곳마다 왜 그곳에서 쉬었는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u2-C2","difficulty":4,"kind":"essay","stem":"「연필깎이」에서 문장 두 개를 골라 ∨ 와 ≡ 를 넣어 다시 쓰고, 쉰 곳마다 왜 그곳에서 쉬었는지 쓰세요.","answer_guide":{"answer":"예: 연필깎이는∨연필을 뾰족하게 깎아 주는 물건입니다.≡ 연필을 구멍에 끝까지 넣고∨손잡이를 돌립니다.≡ — 「연필깎이는」은 무엇에 대한 문장인지 알려 주는 덩어리가 끝나는 곳이라 쉬었고, 「넣고」 다음은 넣는 일과 돌리는 일이 나뉘는 곳이라 쉬었다. 문장 끝은 다음 문장과 나누려고 ≡ 로 길게 쉬었다.","scoring_points":["두 문장에 ∨ 와 ≡ 를 알맞게 넣었는가","쉰 곳마다 까닭을 썼는가","문장 끝을 ≡ 로 길게 쉰 까닭을 썼는가"]},"explanation":["덩어리를 먼저 찾아요.","덩어리 끝에서 쉬어요.","문장 끝은 길게 쉬어요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_a#25','kor',3,2,'u2','','g3_2_kor_u2_review_a','unit_review','K3-2-u2-C1',4,'essay','teacher','이 단원에서 배운 「유창하게 읽기」를 정리해, 잘 읽는다는 것이 무엇인지 쓰고, 잘못 알기 쉬운 것 두 가지(빠르기·크기 등)를 들어 왜 그것이 기준이 아닌지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u2-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「유창하게 읽기」를 정리해, 잘 읽는다는 것이 무엇인지 쓰고, 잘못 알기 쉬운 것 두 가지(빠르기·크기 등)를 들어 왜 그것이 기준이 아닌지 쓰세요.","answer_guide":{"answer":"예: 잘 읽는다는 것은 듣는 사람에게 뜻이 전해지게 읽는 것이다. 빨리 읽으면 뜻 덩어리가 보이지 않아 듣는 사람이 내용을 놓치기 쉽다. 가장 큰 소리로만 읽으면 소리만 남고 장면의 분위기가 살지 않는다. 그래서 빠르기나 크기가 아니라 뜻이 전해지는지가 기준이다.","scoring_points":["잘 읽는다는 것의 뜻을 썼는가","잘못 알기 쉬운 것 두 가지를 들었는가","왜 기준이 아닌지 까닭을 썼는가"]},"explanation":["1차시와 13차시의 물음이에요.","빠르기와 크기를 떠올려요.","듣는 사람 쪽에서 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#1','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C1',1,'ox','auto','유창하게 읽으려면 언제나 가장 빠르게 읽어야 해요.',ARRAY['K3-2-u2-X01']::text[],false,'{"seq":1,"concept":"K3-2-u2-C1","difficulty":1,"kind":"ox","stem":"유창하게 읽으려면 언제나 가장 빠르게 읽어야 해요.","answer":"X","reason_options":[{"t":"빠르기보다 듣는 사람에게 뜻이 전해지는지가 중요하기 때문에","correct":true},{"t":"빠를수록 뜻이 잘 전해지기 때문에","mis":"K3-2-u2-X01"}],"mis":"K3-2-u2-X01","explanation":["빠르면 덩어리가 안 보여요.","뜻이 먼저예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#2','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C2',1,'ox','auto','문장과 문장 사이는 낱말 사이보다 조금 더 길게 쉬어 읽어요.',ARRAY['K3-2-u2-X06']::text[],false,'{"seq":2,"concept":"K3-2-u2-C2","difficulty":1,"kind":"ox","stem":"문장과 문장 사이는 낱말 사이보다 조금 더 길게 쉬어 읽어요.","answer":"O","reason_options":[{"t":"문장이 끝나는 곳이라 ≡ 처럼 더 길게 쉬어야 뜻이 나뉘기 때문에","correct":true},{"t":"문장 사이는 쉬지 않아야 빠르게 읽을 수 있기 때문에","mis":"K3-2-u2-X06"}],"mis":"K3-2-u2-X06","explanation":["문장 끝은 ≡ 예요.","더 길게 쉬어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#3','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C4',1,'mc','auto','「연필깎이」에서 깎고 나온 찌꺼기는 어디에 모이나요?',ARRAY['K3-2-u2-X15','K3-2-u2-X08']::text[],false,'{"seq":3,"concept":"K3-2-u2-C4","difficulty":1,"kind":"mc","stem":"「연필깎이」에서 깎고 나온 찌꺼기는 어디에 모이나요?","options":[{"t":"아래 통","correct":true},{"t":"연필 끝","mis":"K3-2-u2-X15"},{"t":"손잡이","mis":"K3-2-u2-X15"},{"t":"책상 서랍","mis":"K3-2-u2-X08"}],"explanation":["다섯 번째 줄을 읽어요.","찌꺼기가 모이는 곳이에요.","아래 통이에요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#4','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C5',1,'mc','auto','「걸린 종이비행기」 ②에서 비행기를 내려 준 사람은 누구인가요?',ARRAY['K3-2-u2-X15','K3-2-u2-X08']::text[],false,'{"seq":4,"concept":"K3-2-u2-C5","difficulty":1,"kind":"mc","stem":"「걸린 종이비행기」 ②에서 비행기를 내려 준 사람은 누구인가요?","options":[{"t":"태오","correct":true},{"t":"은솔","mis":"K3-2-u2-X15"},{"t":"선생님","mis":"K3-2-u2-X08"},{"t":"알 수 없다","mis":"K3-2-u2-X08"}],"explanation":["두 번째 줄을 읽어요.","빗자루 손잡이로 쳤어요.","태오예요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#5','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C8',1,'mc','auto','「살피다」와 뜻이 비슷한 말은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":5,"concept":"K3-2-u2-C8","difficulty":1,"kind":"mc","stem":"「살피다」와 뜻이 비슷한 말은 무엇인가요?","options":[{"t":"둘러보다","correct":true},{"t":"달래다","mis":"K3-2-u2-X16"},{"t":"서두르다","mis":"K3-2-u2-X16"},{"t":"잊어버리다","mis":"K3-2-u2-X16"}],"explanation":["여기를 살피지?라고 했어요.","두루 자세히 보는 거예요.","둘러보다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#6','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C11',1,'mc','auto','서로 다른 것을 구별해 보여 줄 때 쓰는 것은 무엇인가요?',ARRAY['K3-2-u2-X20']::text[],false,'{"seq":6,"concept":"K3-2-u2-C11","difficulty":1,"kind":"mc","stem":"서로 다른 것을 구별해 보여 줄 때 쓰는 것은 무엇인가요?","options":[{"t":"색","correct":true},{"t":"크기","mis":"K3-2-u2-X20"},{"t":"글자 수","mis":"K3-2-u2-X20"},{"t":"쪽 번호","mis":"K3-2-u2-X20"}],"explanation":["칸마다 다르게 칠했어요.","서로 다른 칸이 구별돼요.","색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#7','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C14',1,'mc','auto','친구 자료 옆에 붙일 쪽지에 쓸 두 가지는 무엇인가요?',ARRAY['K3-2-u2-X25','K3-2-u2-X24']::text[],false,'{"seq":7,"concept":"K3-2-u2-C14","difficulty":1,"kind":"mc","stem":"친구 자료 옆에 붙일 쪽지에 쓸 두 가지는 무엇인가요?","options":[{"t":"잘한 곳 한 가지와 더 잘 보이게 할 방법 한 가지","correct":true},{"t":"잘못한 곳 두 가지","mis":"K3-2-u2-X25"},{"t":"「최고」라는 말 두 번","mis":"K3-2-u2-X25"},{"t":"내 자료가 나은 점 두 가지","mis":"K3-2-u2-X24"}],"explanation":["친구에게 도움이 되는 쪽지예요.","잘한 곳을 말해요.","방법도 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#8','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C16',1,'mc','auto','붙여 써야 하는 것은 무엇인가요?',ARRAY['K3-2-u2-X28']::text[],false,'{"seq":8,"concept":"K3-2-u2-C16","difficulty":1,"kind":"mc","stem":"붙여 써야 하는 것은 무엇인가요?","options":[{"t":"수요일","correct":true},{"t":"먹을 수","mis":"K3-2-u2-X28"},{"t":"할 줄","mis":"K3-2-u2-X28"},{"t":"본 것","mis":"K3-2-u2-X28"}],"explanation":["한 낱말 속에 든 것을 찾아요.","수요일은 한 낱말이에요.","붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#9','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C2',2,'mc','auto','「연필깎이는∨연필을 뾰족하게 깎아 주는 물건입니다.≡」에서 「연필깎이는」 다음에 쉰 까닭은 무엇인가요?',ARRAY['K3-2-u2-X04','K3-2-u2-X05']::text[],false,'{"seq":9,"concept":"K3-2-u2-C2","difficulty":2,"kind":"mc","stem":"「연필깎이는∨연필을 뾰족하게 깎아 주는 물건입니다.≡」에서 「연필깎이는」 다음에 쉰 까닭은 무엇인가요?","options":[{"t":"무엇에 대한 문장인지 알려 주는 말이 끝나는 곳이라서","correct":true},{"t":"글자가 다섯 개라서","mis":"K3-2-u2-X04"},{"t":"아무 데서나 쉬어도 되어서","mis":"K3-2-u2-X04"},{"t":"숨이 차서 낱말마다 쉬려고","mis":"K3-2-u2-X05"}],"explanation":["무엇에 대해 말하는 문장인가요?","‘무엇이’ 덩어리가 끝났어요.","그래서 쉬었어요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#10','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C4',2,'ox','auto','스스로 점검표에 표시가 적으면 점수가 낮아요.',ARRAY['K3-2-u2-X09']::text[],false,'{"seq":10,"concept":"K3-2-u2-C4","difficulty":2,"kind":"ox","stem":"스스로 점검표에 표시가 적으면 점수가 낮아요.","answer":"X","reason_options":[{"t":"점검표는 점수가 없고 다음에 더 잘 읽으려고 쓰는 것이기 때문에","correct":true},{"t":"표시가 많을수록 점수가 높기 때문에","mis":"K3-2-u2-X09"}],"mis":"K3-2-u2-X09","explanation":["점검표에는 점수가 없어요.","아쉬운 곳을 찾는 거예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#11','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C5',2,'mc','auto','「종이 울리자 친구들은 하나둘 교실로 들어갔다.」에서 느껴지는 분위기로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":11,"concept":"K3-2-u2-C5","difficulty":2,"kind":"mc","stem":"「종이 울리자 친구들은 하나둘 교실로 들어갔다.」에서 느껴지는 분위기로 알맞은 것은 무엇인가요?","options":[{"t":"은솔이만 혼자 남아 쓸쓸하다","correct":true},{"t":"모두 함께라 신난다","mis":"K3-2-u2-X12"},{"t":"바빠서 우습다","mis":"K3-2-u2-X12"},{"t":"무섭고 떨린다","mis":"K3-2-u2-X12"}],"explanation":["앞 줄에서 은솔이는 나무 아래에 있었어요.","친구들은 들어갔어요.","혼자 남아 쓸쓸해요."],"asset":{"type":"passage","lines":["점심시간, 은솔이는 새로 접은 종이비행기를 힘껏 날렸다.","비행기는 운동장 위를 빙글 돌며 멀리 날아갔다.","은솔이는 손뼉을 치며 그 뒤를 쫓아 달렸다.","그런데 비행기가 키 큰 나무의 가지 끝에 툭 걸리고 말았다.","은솔이는 나무 아래에 서서 한참 동안 가지만 올려다보았다.","종이 울리자 친구들은 하나둘 교실로 들어갔다."],"title":"이야기 「걸린 종이비행기」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#12','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C6',2,'mc','auto','「비행기가 팔랑팔랑 내려와」의 「팔랑팔랑」을 느낌을 살려 읽는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X12','K3-2-u2-X01','K3-2-u2-X13']::text[],false,'{"seq":12,"concept":"K3-2-u2-C6","difficulty":2,"kind":"mc","stem":"「비행기가 팔랑팔랑 내려와」의 「팔랑팔랑」을 느낌을 살려 읽는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"가볍게 흔들리며 내려오는 느낌이 들게 부드럽게 읽는다","correct":true},{"t":"무겁게 쿵 떨어지듯 읽는다","mis":"K3-2-u2-X12"},{"t":"쉬지 않고 빨리 읽는다","mis":"K3-2-u2-X01"},{"t":"소리 없이 입만 움직인다","mis":"K3-2-u2-X13"}],"explanation":["꾸며 주는 말은 느낌을 살려 읽어요.","팔랑팔랑은 가볍게 나부끼는 모양이에요.","부드럽게 읽어요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#13','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C9',2,'mc','auto','「걸린 종이비행기」를 읽고 생각을 나눈 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X17','K3-2-u2-X08']::text[],false,'{"seq":13,"concept":"K3-2-u2-C9","difficulty":2,"kind":"mc","stem":"「걸린 종이비행기」를 읽고 생각을 나눈 것으로 알맞은 것은 무엇인가요?","options":[{"t":"“말없이 도와준 태오처럼 나도 친구를 챙겨 주고 싶어.”","correct":true},{"t":"“내 느낌만 맞고 너희 느낌은 틀렸어.”","mis":"K3-2-u2-X17"},{"t":"“태오는 유명하지 않으니 배울 점이 없어.”","mis":"K3-2-u2-X17"},{"t":"“비행기가 몇 미터 날았는지 궁금해.”","mis":"K3-2-u2-X08"}],"explanation":["느낌은 사람마다 달라도 돼요.","배울 점은 둘레에도 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#14','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C12',2,'mc','auto','「책 빌리는 차례」에서 「셋째」의 중요한 내용은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":14,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"「책 빌리는 차례」에서 「셋째」의 중요한 내용은 무엇인가요?","options":[{"t":"언제까지 돌려주어야 하는지 확인한다","correct":true},{"t":"이름을 말하고 책을 내민다","mis":"K3-2-u2-X21"},{"t":"읽고 싶은 책을 고른다","mis":"K3-2-u2-X21"},{"t":"책을 깨끗하게 본다","mis":"K3-2-u2-X21"}],"explanation":["「셋째」 뒤를 읽어요.","돌려줄 날이에요.","확인하는 일이에요."],"asset":{"type":"passage","lines":["도서관에서 책을 빌리는 차례를 알려 드리겠습니다.","첫째, 읽고 싶은 책을 골라 빌리는 곳으로 가져갑니다.","둘째, 내 이름을 말하고 책을 내밉니다.","셋째, 언제까지 돌려주어야 하는지 확인합니다.","빌린 책은 깨끗하게 보고 날짜에 맞추어 돌려줍니다."],"title":"서윤이의 발표 글 「책 빌리는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#15','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C11',2,'mc','auto','지안이가 차례를 잇는 화살표 그림을 넣은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X20','K3-2-u2-X18']::text[],false,'{"seq":15,"concept":"K3-2-u2-C11","difficulty":2,"kind":"mc","stem":"지안이가 차례를 잇는 화살표 그림을 넣은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"어느 차례에서 다음 차례로 가는지 알려 주려고","correct":true},{"t":"서로 다른 칸을 구별하려고","mis":"K3-2-u2-X20"},{"t":"글씨를 크게 보이려고","mis":"K3-2-u2-X20"},{"t":"자료를 예쁘게 꾸미려고","mis":"K3-2-u2-X18"}],"explanation":["화살표는 모양이에요.","어느 쪽인지 알려 줘요.","다음 차례로 이어 줘요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 차례마다 번호를 붙인 그림 셋을 크게 그리고, 그림 아래에 짧게 글을 썼어."},{"who":"지안","text":"나는 차례를 글로 크게 쓰고, 옆에 작은 화살표 그림으로 이어 놓았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#16','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C16',2,'mc','auto','「연필을 깎을 줄 안다」를 바르게 띄어 쓴 것은 무엇인가요?',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":16,"concept":"K3-2-u2-C16","difficulty":2,"kind":"mc","stem":"「연필을 깎을 줄 안다」를 바르게 띄어 쓴 것은 무엇인가요?","options":[{"t":"연필을 깎을 줄 안다.","correct":true},{"t":"연필을 깎을줄 안다.","mis":"K3-2-u2-X27"},{"t":"연필을 깎을 줄안다.","mis":"K3-2-u2-X27"},{"t":"연필을깎을줄안다.","mis":"K3-2-u2-X27"}],"explanation":["‘줄’ 앞뒤를 봐요.","앞말과 띄어 써요.","뒷말과도 띄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#17','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C2',3,'mc','auto','「깎고 나온 찌꺼기는 아래 통에 모입니다.」를 친구 가는 「깎고 나온 찌꺼기는∨아래 통에 모입니다.」로, 친구 나는 「깎고∨나온 찌꺼기는 아래∨통에 모입니다.」로 읽었어요. 알맞게 본 것은 무엇인가요?',ARRAY['K3-2-u2-X04','K3-2-u2-X03','K3-2-u2-X05']::text[],false,'{"seq":17,"concept":"K3-2-u2-C2","difficulty":3,"kind":"mc","stem":"「깎고 나온 찌꺼기는 아래 통에 모입니다.」를 친구 가는 「깎고 나온 찌꺼기는∨아래 통에 모입니다.」로, 친구 나는 「깎고∨나온 찌꺼기는 아래∨통에 모입니다.」로 읽었어요. 알맞게 본 것은 무엇인가요?","options":[{"t":"가는 덩어리 끝에서 쉬어 알맞고, 나는 「아래 통」 같은 덩어리를 깨뜨렸다","correct":true},{"t":"둘 다 알맞다 — 아무 데서나 쉬어도 되니까","mis":"K3-2-u2-X04"},{"t":"둘 다 틀렸다 — 쉬는 곳은 하나뿐이니까","mis":"K3-2-u2-X03"},{"t":"나가 알맞다 — 많이 쉴수록 정확하니까","mis":"K3-2-u2-X05"}],"explanation":["‘무엇이’ 덩어리는 「깎고 나온 찌꺼기는」이에요.","「아래 통」은 한 덩어리예요.","가는 알맞고 나는 덩어리를 깨뜨렸어요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#18','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C6',3,'mc','auto','「은솔이는 비행기를 가슴에 꼭 안았다.」를 한 친구는 「꼭」에 힘을 주어, 다른 친구는 끝을 천천히 늘여 읽었어요. 가장 알맞게 본 것은 무엇인가요?',ARRAY['K3-2-u2-X14','K3-2-u2-X13']::text[],false,'{"seq":18,"concept":"K3-2-u2-C6","difficulty":3,"kind":"mc","stem":"「은솔이는 비행기를 가슴에 꼭 안았다.」를 한 친구는 「꼭」에 힘을 주어, 다른 친구는 끝을 천천히 늘여 읽었어요. 가장 알맞게 본 것은 무엇인가요?","options":[{"t":"둘 다 고맙고 소중한 마음이 전해지면 알맞다","correct":true},{"t":"「꼭」에 힘을 준 쪽만 맞다","mis":"K3-2-u2-X14"},{"t":"천천히 늘인 쪽만 맞다","mis":"K3-2-u2-X14"},{"t":"둘 다 틀렸다 — 가장 크게 읽어야 한다","mis":"K3-2-u2-X13"}],"explanation":["읽은 방법이 달라요.","전해진 마음을 견주어요.","같은 마음이면 둘 다 알맞아요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#19','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C8',3,'mc','auto','「걸린 종이비행기」의 「올려다보았다」 자리에 넣어도 뜻이 가장 잘 통하는 말은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":19,"concept":"K3-2-u2-C8","difficulty":3,"kind":"mc","stem":"「걸린 종이비행기」의 「올려다보았다」 자리에 넣어도 뜻이 가장 잘 통하는 말은 무엇인가요?","options":[{"t":"쳐다보았다","correct":true},{"t":"내려다보았다","mis":"K3-2-u2-X16"},{"t":"달래었다","mis":"K3-2-u2-X16"},{"t":"서둘렀다","mis":"K3-2-u2-X16"}],"explanation":["은솔이는 나무 아래에 있었어요.","가지는 위에 있어요.","위를 보는 말이 통해요."],"asset":{"type":"passage","lines":["점심시간, 은솔이는 새로 접은 종이비행기를 힘껏 날렸다.","비행기는 운동장 위를 빙글 돌며 멀리 날아갔다.","은솔이는 손뼉을 치며 그 뒤를 쫓아 달렸다.","그런데 비행기가 키 큰 나무의 가지 끝에 툭 걸리고 말았다.","은솔이는 나무 아래에 서서 한참 동안 가지만 올려다보았다.","종이 울리자 친구들은 하나둘 교실로 들어갔다."],"title":"이야기 「걸린 종이비행기」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#20','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C12',3,'mc','auto','「연필깎이」를 처음 쓰는 1학년 동생에게 알려 주려고 할 때 넣을 내용으로 가장 알맞게 고른 것은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":20,"concept":"K3-2-u2-C12","difficulty":3,"kind":"mc","stem":"「연필깎이」를 처음 쓰는 1학년 동생에게 알려 주려고 할 때 넣을 내용으로 가장 알맞게 고른 것은 무엇인가요?","options":[{"t":"연필을 끝까지 넣고 손잡이 돌리기 · 뾰족해지면 멈추기","correct":true},{"t":"연필깎이는 무엇으로 만들었을까 · 값은 얼마일까","mis":"K3-2-u2-X21"},{"t":"통이 차면 비우기만","mis":"K3-2-u2-X21"},{"t":"연필이 짧아지는 것이 재미있다는 것","mis":"K3-2-u2-X21"}],"explanation":["동생이 직접 써 봐야 해요.","쓰는 방법이 먼저예요.","넣고 돌리고 멈추기예요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#21','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C14',3,'mc','auto','지안이 자료에 쓴 쪽지로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X25','K3-2-u2-X24']::text[],false,'{"seq":21,"concept":"K3-2-u2-C14","difficulty":3,"kind":"mc","stem":"지안이 자료에 쓴 쪽지로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“차례 글이 크게 쓰여 있어 읽기 편해. 둘째에 책을 내미는 손 그림을 넣으면 더 잘 보이겠어.”","correct":true},{"t":"“그림이 작아서 별로야.”","mis":"K3-2-u2-X25"},{"t":"“다 좋아!”","mis":"K3-2-u2-X25"},{"t":"“서윤이 것처럼 그림을 크게 다시 그려.”","mis":"K3-2-u2-X24"}],"explanation":["잘한 곳을 말해요.","더 잘 보이게 할 방법을 말해요.","남의 것과 똑같게 하라는 건 아니에요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 차례마다 번호를 붙인 그림 셋을 크게 그리고, 그림 아래에 짧게 글을 썼어."},{"who":"지안","text":"나는 차례를 글로 크게 쓰고, 옆에 작은 화살표 그림으로 이어 놓았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#22','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C17',3,'mc','auto','종이를 한 장씩 집어 넘겨 주는 고무 골무에 이름을 지었어요. 특징이 가장 잘 드러난 이름은 무엇인가요?',ARRAY['K3-2-u2-X29']::text[],false,'{"seq":22,"concept":"K3-2-u2-C17","difficulty":3,"kind":"mc","stem":"종이를 한 장씩 집어 넘겨 주는 고무 골무에 이름을 지었어요. 특징이 가장 잘 드러난 이름은 무엇인가요?","options":[{"t":"장넘김이","correct":true},{"t":"말랑이","mis":"K3-2-u2-X29"},{"t":"동그리","mis":"K3-2-u2-X29"},{"t":"손친구","mis":"K3-2-u2-X29"}],"explanation":["하는 일은 종이 장 넘기기예요.","이름에 그 일이 들어 있나요?","장넘김이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#23','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C5',4,'mc','auto','「걸린 종이비행기」가 「은솔이는 비행기를 가슴에 꼭 안았다.」로 끝나는 것은 이야기에서 어떤 구실을 하나요?',ARRAY['K3-2-u2-X15','K3-2-u2-X12']::text[],false,'{"seq":23,"concept":"K3-2-u2-C5","difficulty":4,"kind":"mc","stem":"「걸린 종이비행기」가 「은솔이는 비행기를 가슴에 꼭 안았다.」로 끝나는 것은 이야기에서 어떤 구실을 하나요?","options":[{"t":"쓸쓸하던 은솔이 마음이 따뜻하게 풀렸다는 것을 행동으로 보여 준다","correct":true},{"t":"은솔이가 비행기를 버리려 했다는 것을 알려 준다","mis":"K3-2-u2-X15"},{"t":"이야기와 상관없는 장면을 덧붙인 것이다","mis":"K3-2-u2-X12"},{"t":"은솔이가 태오에게 화가 났다는 것을 보여 준다","mis":"K3-2-u2-X15"}],"explanation":["끝 장면의 행동을 봐요.","꼭 안은 것은 소중하다는 뜻이에요.","마음이 풀린 것을 보여 줘요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#24','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C5',4,'essay','teacher','「걸린 종이비행기」의 앞부분과 뒷부분에서 장면을 하나씩 골라 분위기를 까닭과 함께 쓰고, 두 장면을 각각 어떤 목소리로 읽을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u2-C5","difficulty":4,"kind":"essay","stem":"「걸린 종이비행기」의 앞부분과 뒷부분에서 장면을 하나씩 골라 분위기를 까닭과 함께 쓰고, 두 장면을 각각 어떤 목소리로 읽을지 쓰세요.","answer_guide":{"answer":"예: 앞부분 — 혼자 가지를 올려다본 장면은 가라앉고 쓸쓸하다. 친구들은 모두 들어갔는데 은솔이만 한참 동안 서 있었기 때문이다. 낮고 느린 목소리로 읽겠다. 뒷부분 — 날개 끝 글을 읽고 비행기를 안은 장면은 마음이 놓이고 따뜻하다. 태오가 말없이 비행기를 찾아 주고 함께 날리자고 썼기 때문이다. 부드럽고 따뜻한 목소리로 읽겠다.","scoring_points":["앞부분과 뒷부분에서 장면을 하나씩 골랐는가","장면마다 분위기를 까닭과 함께 썼는가","장면마다 어울리는 목소리를 썼는가"]},"explanation":["두 장면은 분위기가 달라요.","까닭은 은솔이와 태오의 행동에서 찾아요.","분위기에 맞는 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_b#25','kor',3,2,'u2','','g3_2_kor_u2_review_b','unit_review','K3-2-u2-C10',4,'essay','teacher','「연필깎이」를 글과 그림으로 설명하는 자료를 만든다고 생각하고, 글로 쓸 것 하나와 그림으로 보일 것 하나를 정해 각각 그렇게 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u2-C10","difficulty":4,"kind":"essay","stem":"「연필깎이」를 글과 그림으로 설명하는 자료를 만든다고 생각하고, 글로 쓸 것 하나와 그림으로 보일 것 하나를 정해 각각 그렇게 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 글로 쓸 것 — 너무 오래 돌리면 연필이 금방 짧아진다는 것. 까닭을 자세히 알려 주려면 글이 필요하다. 그림으로 보일 것 — 연필을 구멍에 끝까지 넣고 손잡이를 돌리는 모습. 어디에 넣고 어느 쪽으로 돌리는지는 그림으로 보여 주면 한눈에 알 수 있다.","scoring_points":["글로 쓸 것을 정하고 까닭을 썼는가","그림으로 보일 것을 정하고 까닭을 썼는가","글과 그림이 하는 일을 갈랐는가"]},"explanation":["글은 자세히 알려 줘요.","그림은 한눈에 보여 줘요.","할 일을 나누어 써요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#1','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C1',1,'mc','auto','「연필깎이」를 동생에게 읽어 줄 때 가장 먼저 생각할 것은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X02','K3-2-u2-X09']::text[],false,'{"seq":1,"concept":"K3-2-u2-C1","difficulty":1,"kind":"mc","stem":"「연필깎이」를 동생에게 읽어 줄 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"동생이 듣고 연필깎이 쓰는 법을 알 수 있는지","correct":true},{"t":"얼마나 빨리 끝낼지","mis":"K3-2-u2-X01"},{"t":"얼마나 크게 읽을지","mis":"K3-2-u2-X02"},{"t":"몇 글자인지","mis":"K3-2-u2-X09"}],"explanation":["읽어 주는 까닭이 있어요.","동생이 알아들어야 해요.","뜻이 전해지는지 생각해요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#2','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C2',1,'sa','auto','조금 쉬어 읽으라는 표시는 ∨ 와 ≡ 가운데 무엇인가요? 표시를 그대로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u2-C2","difficulty":1,"kind":"sa","stem":"조금 쉬어 읽으라는 표시는 ∨ 와 ≡ 가운데 무엇인가요? 표시를 그대로 쓰세요.","answer":["∨"],"explanation":["짧게 쉬는 표시예요.","문장 안에서 써요.","∨ 예요."],"mis":"K3-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#3','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C4',1,'mc','auto','「연필깎이」에서 알 수 없는 것은 무엇인가요?',ARRAY['K3-2-u2-X08']::text[],false,'{"seq":3,"concept":"K3-2-u2-C4","difficulty":1,"kind":"mc","stem":"「연필깎이」에서 알 수 없는 것은 무엇인가요?","options":[{"t":"연필깎이를 처음 만든 사람","correct":true},{"t":"너무 오래 돌리면 연필이 짧아진다","mis":"K3-2-u2-X08"},{"t":"통이 차면 비운다","mis":"K3-2-u2-X08"},{"t":"연필심이 뾰족해지면 멈춘다","mis":"K3-2-u2-X08"}],"explanation":["글에 쓰여 있는 것을 찾아요.","만든 사람은 글에 없어요.","그것이 알 수 없는 것이에요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#4','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C5',1,'ox','auto','「걸린 종이비행기」에서 날개 끝에 적힌 말은 “다음엔 같이 날리자.”예요.',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":4,"concept":"K3-2-u2-C5","difficulty":1,"kind":"ox","stem":"「걸린 종이비행기」에서 날개 끝에 적힌 말은 “다음엔 같이 날리자.”예요.","answer":"O","reason_options":[{"t":"②의 다섯 번째 줄에 그렇게 적혀 있기 때문에","correct":true},{"t":"태오가 큰 소리로 그렇게 외쳤기 때문에","mis":"K3-2-u2-X15"}],"mis":"K3-2-u2-X15","explanation":["다섯 번째 줄을 읽어요.","연필로 작게 적혀 있었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#5','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C8',1,'mc','auto','「서두르다」와 뜻이 비슷한 말은 무엇인가요?',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":5,"concept":"K3-2-u2-C8","difficulty":1,"kind":"mc","stem":"「서두르다」와 뜻이 비슷한 말은 무엇인가요?","options":[{"t":"급히 하다","correct":true},{"t":"천천히 하다","mis":"K3-2-u2-X16"},{"t":"둘러보다","mis":"K3-2-u2-X16"},{"t":"다독이다","mis":"K3-2-u2-X16"}],"explanation":["서두르지 않아도 돼라고 했어요.","급하게 하는 거예요.","급히 하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#6','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C10',1,'ox','auto','설명하는 글에 넣는 그림은 보기 좋게 꾸미려고 넣어요.',ARRAY['K3-2-u2-X18']::text[],false,'{"seq":6,"concept":"K3-2-u2-C10","difficulty":1,"kind":"ox","stem":"설명하는 글에 넣는 그림은 보기 좋게 꾸미려고 넣어요.","answer":"X","reason_options":[{"t":"그림은 글로 알기 어려운 것을 한눈에 보여 주려고 넣기 때문에","correct":true},{"t":"그림이 예쁘면 글을 안 읽어도 되기 때문에","mis":"K3-2-u2-X18"}],"mis":"K3-2-u2-X18","explanation":["그림은 장식이 아니에요.","한눈에 보여 주는 일을 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#7','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C13',1,'ox','auto','얼개에서 그림을 풀어 주는 짧은 설명은 그림 바로 아래에 놓아요.',ARRAY['K3-2-u2-X22']::text[],false,'{"seq":7,"concept":"K3-2-u2-C13","difficulty":1,"kind":"ox","stem":"얼개에서 그림을 풀어 주는 짧은 설명은 그림 바로 아래에 놓아요.","answer":"O","reason_options":[{"t":"그림을 보고 바로 아래 설명을 이어 읽을 수 있기 때문에","correct":true},{"t":"설명은 맨 위에 가장 크게 놓아야 하기 때문에","mis":"K3-2-u2-X22"}],"mis":"K3-2-u2-X22","explanation":["그림과 설명은 붙어 있어야 해요.","그림 바로 아래예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#8','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C16',1,'ox','auto','「자전거를 탈 줄 안다.」의 「줄」은 앞말과 띄어 써요.',ARRAY['K3-2-u2-X27']::text[],false,'{"seq":8,"concept":"K3-2-u2-C16","difficulty":1,"kind":"ox","stem":"「자전거를 탈 줄 안다.」의 「줄」은 앞말과 띄어 써요.","answer":"O","reason_options":[{"t":"‘줄’이 혼자 쓰이지 못하고 앞말에 기대어 쓰이기 때문에","correct":true},{"t":"‘줄’은 줄넘기의 줄과 같은 말이기 때문에","mis":"K3-2-u2-X27"}],"mis":"K3-2-u2-X27","explanation":["「탈」 다음의 ‘줄’이에요.","다른 말에 기대어 쓰여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#9','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C2',2,'error','auto','「통이 가득 차면 열어서 쓰레기통에 비워야 합니다.」를 띄어 읽었어요. 뜻 덩어리를 깨뜨린 것은 무엇인가요?',ARRAY['K3-2-u2-X05','K3-2-u2-X03']::text[],false,'{"seq":9,"concept":"K3-2-u2-C2","difficulty":2,"kind":"error","stem":"「통이 가득 차면 열어서 쓰레기통에 비워야 합니다.」를 띄어 읽었어요. 뜻 덩어리를 깨뜨린 것은 무엇인가요?","options":[{"t":"통이∨가득∨차면∨열어서∨쓰레기통에∨비워야∨합니다.≡","correct":true,"mis_target":"K3-2-u2-X05"},{"t":"통이 가득 차면∨열어서 쓰레기통에 비워야 합니다.≡","mis":"K3-2-u2-X03"},{"t":"통이 가득 차면∨열어서∨쓰레기통에 비워야 합니다.≡","mis":"K3-2-u2-X03"}],"explanation":["낱말마다 다 쉬면 뜻이 흩어져요.","나머지 둘은 쉬는 곳이 조금 달라도 뜻이 같아요.","첫 번째가 덩어리를 깨뜨렸어요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#10','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C4',2,'mc','auto','「연필깎이」를 녹음해 다시 들을 때 살펴볼 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X02','K3-2-u2-X09']::text[],false,'{"seq":10,"concept":"K3-2-u2-C4","difficulty":2,"kind":"mc","stem":"「연필깎이」를 녹음해 다시 들을 때 살펴볼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"「너무 오래 돌리면」에서 쉬어 뜻이 또렷이 들렸는지","correct":true},{"t":"몇 초 걸렸는지","mis":"K3-2-u2-X01"},{"t":"옆 친구보다 큰 소리였는지","mis":"K3-2-u2-X02"},{"t":"틀린 글자를 몇 개 세었는지","mis":"K3-2-u2-X09"}],"explanation":["녹음을 처음 듣는 사람을 떠올려요.","뜻이 전해졌는지 봐요.","덩어리마다 또렷했는지예요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#11','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C5',2,'match','auto','「걸린 종이비행기」의 장면과 분위기를 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K3-2-u2-C5","difficulty":2,"kind":"match","stem":"「걸린 종이비행기」의 장면과 분위기를 알맞게 이으세요.","pairs":[{"l":"비행기를 날리며 쫓아 달린 장면","r":"들뜨고 신난다"},{"l":"혼자 가지를 올려다본 장면","r":"가라앉고 쓸쓸하다"},{"l":"날개 끝 글을 읽고 비행기를 안은 장면","r":"마음이 놓이고 따뜻하다"}],"mis":"K3-2-u2-X12","explanation":["장면마다 은솔이가 무엇을 했는지 봐요.","달림 · 올려다봄 · 안음이에요.","셋 다 까닭이 글 안에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#12','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C6',2,'ox','auto','같은 장면을 두 친구가 다르게 읽었어도 장면에 어울린다면 둘 다 알맞게 읽은 거예요.',ARRAY['K3-2-u2-X14']::text[],false,'{"seq":12,"concept":"K3-2-u2-C6","difficulty":2,"kind":"ox","stem":"같은 장면을 두 친구가 다르게 읽었어도 장면에 어울린다면 둘 다 알맞게 읽은 거예요.","answer":"O","reason_options":[{"t":"분위기를 살려 읽는 방법은 하나가 아니기 때문에","correct":true},{"t":"똑같이 읽어야만 맞기 때문에","mis":"K3-2-u2-X14"}],"mis":"K3-2-u2-X14","explanation":["나겸이와 한울이를 떠올려요.","방법은 달랐지만 같은 마음이 전해졌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#13','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C9',2,'ox','auto','태오처럼 우리 반 친구에게서도 배울 점을 찾을 수 있어요.',ARRAY['K3-2-u2-X17']::text[],false,'{"seq":13,"concept":"K3-2-u2-C9","difficulty":2,"kind":"ox","stem":"태오처럼 우리 반 친구에게서도 배울 점을 찾을 수 있어요.","answer":"O","reason_options":[{"t":"배울 점은 유명한 사람만이 아니라 둘레의 사람에게도 있기 때문에","correct":true},{"t":"친구는 나와 나이가 같아 배울 것이 없기 때문에","mis":"K3-2-u2-X17"}],"mis":"K3-2-u2-X17","explanation":["노란 조끼도 둘레의 사람이었어요.","태오도 우리 반 같은 친구예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#14','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C12',2,'ox','auto','발표 주제를 정할 때는 누구에게, 왜 알려 줄지부터 정해요.',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":14,"concept":"K3-2-u2-C12","difficulty":2,"kind":"ox","stem":"발표 주제를 정할 때는 누구에게, 왜 알려 줄지부터 정해요.","answer":"O","reason_options":[{"t":"목적이 정해져야 넣을 내용도 정해지기 때문에","correct":true},{"t":"주제는 가장 재미있는 것으로만 정하기 때문에","mis":"K3-2-u2-X21"}],"mis":"K3-2-u2-X21","explanation":["태경 · 나겸 · 우담을 떠올려요.","목적이 달라서 넣은 것도 달랐어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#15','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C14',2,'ox','auto','서윤이의 자료 옆에 「번호 그림이 크게 보여서 좋아. 돌려줄 날은 빨간색으로 칠하면 더 잘 보이겠어.」라고 쓴 쪽지는 알맞은 의견이에요.',ARRAY['K3-2-u2-X25']::text[],false,'{"seq":15,"concept":"K3-2-u2-C14","difficulty":2,"kind":"ox","stem":"서윤이의 자료 옆에 「번호 그림이 크게 보여서 좋아. 돌려줄 날은 빨간색으로 칠하면 더 잘 보이겠어.」라고 쓴 쪽지는 알맞은 의견이에요.","answer":"O","reason_options":[{"t":"잘한 곳과 더 잘 보이게 할 방법을 함께 말했기 때문에","correct":true},{"t":"쪽지에는 칭찬만 써야 하기 때문에","mis":"K3-2-u2-X25"}],"mis":"K3-2-u2-X25","explanation":["잘한 곳이 있어요.","방법도 있어요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 차례마다 번호를 붙인 그림 셋을 크게 그리고, 그림 아래에 짧게 글을 썼어."},{"who":"지안","text":"나는 차례를 글로 크게 쓰고, 옆에 작은 화살표 그림으로 이어 놓았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#16','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C17',2,'mc','auto','연필깎이의 하는 일이 드러나게 새로 지은 이름으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X29']::text[],false,'{"seq":16,"concept":"K3-2-u2-C17","difficulty":2,"kind":"mc","stem":"연필깎이의 하는 일이 드러나게 새로 지은 이름으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"돌려깎개","correct":true},{"t":"둥글이","mis":"K3-2-u2-X29"},{"t":"반짝통","mis":"K3-2-u2-X29"},{"t":"색칠이","mis":"K3-2-u2-X29"}],"explanation":["손잡이를 돌려 연필을 깎아요.","이름에 돌리기와 깎기가 들어 있나요?","돌려깎개예요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#17','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C2',3,'ox','auto','「연필심이 뾰족해지면∨돌리기를 멈춥니다.≡」에서 ≡ 대신 ∨ 를 붙이면 다음 문장과의 사이를 짧게 쉬게 돼요.',ARRAY['K3-2-u2-X06']::text[],false,'{"seq":17,"concept":"K3-2-u2-C2","difficulty":3,"kind":"ox","stem":"「연필심이 뾰족해지면∨돌리기를 멈춥니다.≡」에서 ≡ 대신 ∨ 를 붙이면 다음 문장과의 사이를 짧게 쉬게 돼요.","answer":"O","reason_options":[{"t":"∨ 는 조금 쉬는 표시라 문장 사이를 더 길게 쉬라는 ≡ 보다 짧기 때문에","correct":true},{"t":"∨ 와 ≡ 는 같은 표시이기 때문에","mis":"K3-2-u2-X06"}],"mis":"K3-2-u2-X06","explanation":["∨ 는 조금 쉬어요.","≡ 는 더 길게 쉬어요.","그래서 O예요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#18','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C5',3,'mc','auto','「태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.」에서 짐작할 수 있는 태오의 마음으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X15','K3-2-u2-X11']::text[],false,'{"seq":18,"concept":"K3-2-u2-C5","difficulty":3,"kind":"mc","stem":"「태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.」에서 짐작할 수 있는 태오의 마음으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"생색내지 않고 은솔이를 조용히 챙겨 주고 싶은 마음","correct":true},{"t":"은솔이에게 화가 난 마음","mis":"K3-2-u2-X15"},{"t":"비행기를 갖고 싶은 마음","mis":"K3-2-u2-X15"},{"t":"청소가 하기 싫은 마음","mis":"K3-2-u2-X11"}],"explanation":["말없이 올려 두는 행동을 봐요.","날개 끝에 함께 날리자고 썼어요.","조용히 챙겨 주는 마음이에요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#19','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C7',3,'mc','auto','「노란 조끼」의 「그래도 노란 조끼는 늘 같은 곳에 서 있었다.」 장면을 정리한 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X15']::text[],false,'{"seq":19,"concept":"K3-2-u2-C7","difficulty":3,"kind":"mc","stem":"「노란 조끼」의 「그래도 노란 조끼는 늘 같은 곳에 서 있었다.」 장면을 정리한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"상황 — 꽃가루 날리고 손이 어는 날들 / 마음 — 힘들어도 그 자리를 지키려는 마음","correct":true},{"t":"상황 — 더운 여름 바닷가 / 마음 — 놀고 싶다","mis":"K3-2-u2-X15"},{"t":"상황 — 새 조끼를 받은 날 / 마음 — 자랑하고 싶다","mis":"K3-2-u2-X15"},{"t":"상황 — 아이들이 없는 날 / 마음 — 쉬고 싶다","mis":"K3-2-u2-X15"}],"explanation":["바로 앞 줄을 봐요.","봄 꽃가루, 겨울 언 손이에요.","그래도 지키는 마음이에요."],"asset":{"type":"passage","lines":["처음에는 이른 아침에 일어나는 일이 가장 힘들었다고 한다.","그래도 하루도 빠지지 않은 까닭을 이렇게 말했다.","“내가 없는 날, 누가 여기를 살피지?”","봄에는 꽃가루가 날리고 겨울에는 손이 얼었다.","그래도 노란 조끼는 늘 같은 곳에 서 있었다.","아이들은 이제 멀리서도 그 조끼를 알아본다."],"title":"글 「노란 조끼」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#20','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C10',3,'mc','auto','「연필깎이」 설명 자료에서 「통이 가득 차면 열어서 비워야 합니다」 옆에 넣을 그림으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X18','K3-2-u2-X23']::text[],false,'{"seq":20,"concept":"K3-2-u2-C10","difficulty":3,"kind":"mc","stem":"「연필깎이」 설명 자료에서 「통이 가득 차면 열어서 비워야 합니다」 옆에 넣을 그림으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"찌꺼기가 가득 찬 통을 열어 쓰레기통에 쏟는 그림","correct":true},{"t":"새 연필이 가득 꽂힌 필통 그림","mis":"K3-2-u2-X18"},{"t":"알록달록한 별 무늬 그림","mis":"K3-2-u2-X23"},{"t":"연필깎이를 파는 가게 그림","mis":"K3-2-u2-X18"}],"explanation":["그림은 글이 말하는 것을 보여 줘요.","통을 비우는 모습이에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#21','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C13',3,'mc','auto','「책 빌리는 차례」 자료에서 「언제까지 돌려주어야 하는지」만 빨간색으로 칠했어요. 이렇게 한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X23','K3-2-u2-X19']::text[],false,'{"seq":21,"concept":"K3-2-u2-C13","difficulty":3,"kind":"mc","stem":"「책 빌리는 차례」 자료에서 「언제까지 돌려주어야 하는지」만 빨간색으로 칠했어요. 이렇게 한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"잊기 쉬운 돌려줄 날을 눈에 띄게 하려고","correct":true},{"t":"빨간색이 가장 예뻐서","mis":"K3-2-u2-X23"},{"t":"색을 많이 쓸수록 좋아서","mis":"K3-2-u2-X23"},{"t":"다른 차례는 볼 필요가 없어서","mis":"K3-2-u2-X19"}],"explanation":["색은 전하려는 곳에 써요.","돌려줄 날은 잊기 쉬워요.","그래서 눈에 띄게 했어요."],"asset":{"type":"passage","lines":["도서관에서 책을 빌리는 차례를 알려 드리겠습니다.","첫째, 읽고 싶은 책을 골라 빌리는 곳으로 가져갑니다.","둘째, 내 이름을 말하고 책을 내밉니다.","셋째, 언제까지 돌려주어야 하는지 확인합니다.","빌린 책은 깨끗하게 보고 날짜에 맞추어 돌려줍니다."],"title":"서윤이의 발표 글 「책 빌리는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#22','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C15',3,'mc','auto','「소개하고 싶은 물건 설명하기」를 준비하며 「무엇인가요 · 왜 소개하고 싶은가요 · 어떤 물건인가요」에 답했어요. 가장 알맞게 쓴 것은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":22,"concept":"K3-2-u2-C15","difficulty":3,"kind":"mc","stem":"「소개하고 싶은 물건 설명하기」를 준비하며 「무엇인가요 · 왜 소개하고 싶은가요 · 어떤 물건인가요」에 답했어요. 가장 알맞게 쓴 것은 무엇인가요?","options":[{"t":"연필깎이 · 매일 아침 연필을 깎아 주어서 · 손잡이를 돌려 깎고 찌꺼기는 아래 통에 모인다","correct":true},{"t":"연필깎이 · 값이 비싸서 · 가게에서 샀다","mis":"K3-2-u2-X21"},{"t":"연필깎이 · 그냥 · 모르겠다","mis":"K3-2-u2-X21"},{"t":"지우개 · 연필깎이가 좋아서 · 둥글다","mis":"K3-2-u2-X21"}],"explanation":["세 물음에 맞게 답해요.","무엇 · 왜 · 어떤 물건이에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#23','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C12',4,'mc','auto','「책 빌리는 차례」와 「연필깎이」를 묶어 「1학년 동생을 위한 학교생활 안내」 발표를 한다면, 두 자료에서 함께 남길 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":23,"concept":"K3-2-u2-C12","difficulty":4,"kind":"mc","stem":"「책 빌리는 차례」와 「연필깎이」를 묶어 「1학년 동생을 위한 학교생활 안내」 발표를 한다면, 두 자료에서 함께 남길 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"동생이 혼자 해 볼 수 있는 차례 — 책 빌리는 셋째까지와 연필 넣고 돌리고 멈추기","correct":true},{"t":"두 글의 첫 문장만","mis":"K3-2-u2-X21"},{"t":"연필깎이 통 색과 도서관 책 수","mis":"K3-2-u2-X21"},{"t":"두 글을 모두 그대로 옮겨 쓴 것","mis":"K3-2-u2-X21"}],"explanation":["목적은 동생이 혼자 해 보는 거예요.","그러려면 차례가 필요해요.","두 글의 차례를 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#24','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C12',4,'essay','teacher','「책 빌리는 차례」로 발표할 대상을 한 사람(또는 한 무리) 정하고, 그 목적에 맞게 넣을 내용과 뺄 내용을 하나씩 골라 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u2-C12","difficulty":4,"kind":"essay","stem":"「책 빌리는 차례」로 발표할 대상을 한 사람(또는 한 무리) 정하고, 그 목적에 맞게 넣을 내용과 뺄 내용을 하나씩 골라 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 대상 — 처음 도서관에 가는 1학년 동생들. 넣을 내용 — 둘째, 내 이름을 말하고 책을 내민다. 처음이라 무엇을 말해야 할지 모르기 때문이다. 뺄 내용 — 「차례를 알려 드리겠습니다」라는 첫 문장. 동생들이 해 볼 일은 아니라서 자료에는 없어도 되기 때문이다.","scoring_points":["발표할 대상을 정했는가","넣을 내용과 뺄 내용을 하나씩 골랐는가","목적과 이어 까닭을 썼는가"]},"explanation":["누구에게 알려 줄지부터 정해요.","그 사람에게 필요한 것을 남겨요.","목적으로 까닭을 써요."],"asset":{"type":"passage","lines":["도서관에서 책을 빌리는 차례를 알려 드리겠습니다.","첫째, 읽고 싶은 책을 골라 빌리는 곳으로 가져갑니다.","둘째, 내 이름을 말하고 책을 내밉니다.","셋째, 언제까지 돌려주어야 하는지 확인합니다.","빌린 책은 깨끗하게 보고 날짜에 맞추어 돌려줍니다."],"title":"서윤이의 발표 글 「책 빌리는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_c#25','kor',3,2,'u2','','g3_2_kor_u2_review_c','unit_review','K3-2-u2-C14',4,'essay','teacher','서윤이와 지안이 가운데 한 친구의 자료 옆에 붙일 쪽지를 쓰세요. 잘한 곳 한 가지와 더 잘 보이게 할 방법 한 가지를 쓰고, 그렇게 쓴 까닭도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u2-C14","difficulty":4,"kind":"essay","stem":"서윤이와 지안이 가운데 한 친구의 자료 옆에 붙일 쪽지를 쓰세요. 잘한 곳 한 가지와 더 잘 보이게 할 방법 한 가지를 쓰고, 그렇게 쓴 까닭도 쓰세요.","answer_guide":{"answer":"예: 서윤이에게 — 번호를 붙인 그림이 커서 무엇을 먼저 할지 한눈에 보여. 셋째 그림 옆 「돌려줄 날」 글씨만 조금 더 크게 쓰면 더 잘 보이겠어. 까닭 — 잘한 곳을 말해 주면 힘이 나고, 방법을 말해 주면 다음에 더 잘 만들 수 있기 때문이다.","scoring_points":["잘한 곳 한 가지를 썼는가","더 잘 보이게 할 방법 한 가지를 썼는가","그렇게 쓴 까닭을 썼는가"]},"explanation":["잘못한 곳만 쓰지 않아요.","칭찬만 쓰지도 않아요.","잘한 곳과 방법을 함께 써요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 차례마다 번호를 붙인 그림 셋을 크게 그리고, 그림 아래에 짧게 글을 썼어."},{"who":"지안","text":"나는 차례를 글로 크게 쓰고, 옆에 작은 화살표 그림으로 이어 놓았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#1','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C1',1,'mc','auto','친구의 낭독을 듣고 칭찬할 말로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X01','K3-2-u2-X02','K3-2-u2-X05']::text[],false,'{"seq":1,"concept":"K3-2-u2-C1","difficulty":1,"kind":"mc","stem":"친구의 낭독을 듣고 칭찬할 말로 알맞은 것은 무엇인가요?","options":[{"t":"“네가 읽어 준 덕분에 무슨 내용인지 잘 알겠어.”","correct":true},{"t":"“제일 빨리 읽었어!”","mis":"K3-2-u2-X01"},{"t":"“목소리가 제일 컸어!”","mis":"K3-2-u2-X02"},{"t":"“한 번도 안 쉬었어!”","mis":"K3-2-u2-X05"}],"explanation":["유창하게 읽기의 기준을 떠올려요.","듣는 사람에게 뜻이 전해졌는지예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#2','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C2',1,'mc','auto','‘누가/무엇이’에 해당하는 말이 길 때는 어떻게 읽나요?',ARRAY['K3-2-u2-X05','K3-2-u2-X04']::text[],false,'{"seq":2,"concept":"K3-2-u2-C2","difficulty":1,"kind":"mc","stem":"‘누가/무엇이’에 해당하는 말이 길 때는 어떻게 읽나요?","options":[{"t":"한 번 더 띄어 읽는다","correct":true},{"t":"쉬지 않고 한 번에 읽는다","mis":"K3-2-u2-X05"},{"t":"낱말마다 모두 쉰다","mis":"K3-2-u2-X05"},{"t":"아무 데서나 쉰다","mis":"K3-2-u2-X04"}],"explanation":["짧으면 한 번 쉬어요.","길면 한 번 더 쉬어요.","덩어리 안에서 한 번 더예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#3','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C4',1,'sa','auto','「연필깎이」에서 너무 오래 돌리면 연필이 어떻게 된다고 했나요? 「금방 ○○○○」의 ○○○○ 네 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u2-C4","difficulty":1,"kind":"sa","stem":"「연필깎이」에서 너무 오래 돌리면 연필이 어떻게 된다고 했나요? 「금방 ○○○○」의 ○○○○ 네 글자를 쓰세요.","answer":["짧아진다","짧아집니다"],"explanation":["네 번째 줄을 읽어요.","오래 돌리면 연필이 줄어요.","짧아진다예요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"},"mis":"K3-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#4','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C5',1,'mc','auto','비행기가 운동장 위를 빙글 돌며 날아가고 은솔이가 손뼉을 치며 쫓아간 장면의 분위기는 어떤가요?',ARRAY['K3-2-u2-X12']::text[],false,'{"seq":4,"concept":"K3-2-u2-C5","difficulty":1,"kind":"mc","stem":"비행기가 운동장 위를 빙글 돌며 날아가고 은솔이가 손뼉을 치며 쫓아간 장면의 분위기는 어떤가요?","options":[{"t":"들뜨고 신난다","correct":true},{"t":"가라앉고 쓸쓸하다","mis":"K3-2-u2-X12"},{"t":"무섭고 떨린다","mis":"K3-2-u2-X12"},{"t":"화가 난다","mis":"K3-2-u2-X12"}],"explanation":["은솔이가 손뼉을 쳤어요.","비행기가 멀리 날아갔어요.","들뜨고 신나요."],"asset":{"type":"passage","lines":["점심시간, 은솔이는 새로 접은 종이비행기를 힘껏 날렸다.","비행기는 운동장 위를 빙글 돌며 멀리 날아갔다.","은솔이는 손뼉을 치며 그 뒤를 쫓아 달렸다.","그런데 비행기가 키 큰 나무의 가지 끝에 툭 걸리고 말았다.","은솔이는 나무 아래에 서서 한참 동안 가지만 올려다보았다.","종이 울리자 친구들은 하나둘 교실로 들어갔다."],"title":"이야기 「걸린 종이비행기」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#5','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C8',1,'ox','auto','「아이들이 뛰어오면 어깨를 다독여 준다」의 「다독여」를 「둘러봐」로 바꾸어도 뜻이 통해요.',ARRAY['K3-2-u2-X16']::text[],false,'{"seq":5,"concept":"K3-2-u2-C8","difficulty":1,"kind":"ox","stem":"「아이들이 뛰어오면 어깨를 다독여 준다」의 「다독여」를 「둘러봐」로 바꾸어도 뜻이 통해요.","answer":"X","reason_options":[{"t":"다독이다는 달래다와 뜻이 비슷하고 둘러보다는 살피다와 비슷하기 때문에","correct":true},{"t":"비슷한 말은 아무것이나 바꾸어 넣어도 되기 때문에","mis":"K3-2-u2-X16"}],"mis":"K3-2-u2-X16","explanation":["바꾸어 넣어 읽어 봐요.","「어깨를 둘러봐 준다」는 어색해요.","그래서 X예요."],"asset":{"type":"passage","lines":["해가 뜨기 전, 길 건너에 노란 조끼가 서 있다.","우리 학교 건널목을 지키는 분이다.","비가 오는 날에도, 눈이 쌓인 날에도 그 자리를 비운 적이 없다.","아이들이 뛰어오면 손을 들어 차를 세우고 어깨를 다독여 준다.","“천천히 와도 돼. 서두르지 않아도 돼.”"],"title":"글 「노란 조끼」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#6','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C11',1,'mc','auto','어디에 있는지, 어느 쪽인지 알려 줄 때 쓰는 것은 무엇인가요?',ARRAY['K3-2-u2-X20','K3-2-u2-X19']::text[],false,'{"seq":6,"concept":"K3-2-u2-C11","difficulty":1,"kind":"mc","stem":"어디에 있는지, 어느 쪽인지 알려 줄 때 쓰는 것은 무엇인가요?","options":[{"t":"화살표 같은 모양","correct":true},{"t":"여러 가지 색","mis":"K3-2-u2-X20"},{"t":"아주 큰 글씨","mis":"K3-2-u2-X20"},{"t":"긴 설명 글","mis":"K3-2-u2-X19"}],"explanation":["색 · 크기 · 모양 가운데 하나예요.","쪽을 가리키는 것이에요.","화살표 같은 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#7','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C14',1,'ox','auto','친구 자료를 보고 무조건 잘했다고만 말하는 것이 가장 좋은 의견이에요.',ARRAY['K3-2-u2-X25']::text[],false,'{"seq":7,"concept":"K3-2-u2-C14","difficulty":1,"kind":"ox","stem":"친구 자료를 보고 무조건 잘했다고만 말하는 것이 가장 좋은 의견이에요.","answer":"X","reason_options":[{"t":"더 잘 보이게 할 방법도 함께 말해야 친구에게 도움이 되기 때문에","correct":true},{"t":"친구는 칭찬만 들어야 하기 때문에","mis":"K3-2-u2-X25"}],"mis":"K3-2-u2-X25","explanation":["칭찬만 하면 방법이 없어요.","방법도 함께 말해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#8','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C17',1,'mc','auto','특징이 드러나는 이름으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X29']::text[],false,'{"seq":8,"concept":"K3-2-u2-C17","difficulty":1,"kind":"mc","stem":"특징이 드러나는 이름으로 알맞은 것은 무엇인가요?","options":[{"t":"「물먹는솜」 — 물을 빨아들이는 말랑한 것","correct":true},{"t":"「반짝이」 — 물을 빨아들이는 말랑한 것","mis":"K3-2-u2-X29"},{"t":"「동글이」 — 종이를 집는 쇠붙이","mis":"K3-2-u2-X29"},{"t":"「친구」 — 색을 칠하는 막대","mis":"K3-2-u2-X29"}],"explanation":["이름에 하는 일이 들어가야 해요.","물을 먹는다는 말이 들어 있어요.","「물먹는솜」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#9','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C2',2,'ox','auto','「너무 오래 돌리면∨연필이 금방 짧아집니다.」와 「너무 오래∨돌리면 연필이 금방 짧아집니다.」 가운데 앞의 것이 뜻 덩어리를 더 잘 살려요.',ARRAY['K3-2-u2-X04']::text[],false,'{"seq":9,"concept":"K3-2-u2-C2","difficulty":2,"kind":"ox","stem":"「너무 오래 돌리면∨연필이 금방 짧아집니다.」와 「너무 오래∨돌리면 연필이 금방 짧아집니다.」 가운데 앞의 것이 뜻 덩어리를 더 잘 살려요.","answer":"O","reason_options":[{"t":"「너무 오래 돌리면」이 한 덩어리라 그 끝에서 쉬어야 뜻이 또렷하기 때문에","correct":true},{"t":"쉬는 곳은 아무 데나 같기 때문에","mis":"K3-2-u2-X04"}],"mis":"K3-2-u2-X04","explanation":["덩어리를 찾아요.","「너무 오래 돌리면」이 하나예요.","그래서 O예요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#10','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C3',2,'mc','auto','급식실 앞 발자국 표시가 알려 주는 것은 무엇인가요?',ARRAY['K3-2-u2-X07']::text[],false,'{"seq":10,"concept":"K3-2-u2-C3","difficulty":2,"kind":"mc","stem":"급식실 앞 발자국 표시가 알려 주는 것은 무엇인가요?","options":[{"t":"여기에 줄을 서라는 것","correct":true},{"t":"여기서 뛰라는 것","mis":"K3-2-u2-X07"},{"t":"발 크기를 재라는 것","mis":"K3-2-u2-X07"},{"t":"신발을 벗으라는 것","mis":"K3-2-u2-X07"}],"explanation":["발자국은 서는 자리예요.","줄을 서는 곳이에요.","여기에 줄을 서요."],"asset":{"type":"passage","lines":["복도 바닥의 오른쪽 화살표 — 이쪽으로 걸어요.","책꽂이 옆의 책 그림 — 뽑은 책은 제자리에 꽂아요.","급식실 앞의 발자국 표시 — 여기에 줄을 서요."],"title":"학교 안의 그림 기호"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#11','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C5',2,'ox','auto','「걸린 종이비행기」 ②의 분위기를 말할 때는 그렇게 느낀 까닭을 글에서 찾아 함께 말해요.',ARRAY['K3-2-u2-X10']::text[],false,'{"seq":11,"concept":"K3-2-u2-C5","difficulty":2,"kind":"ox","stem":"「걸린 종이비행기」 ②의 분위기를 말할 때는 그렇게 느낀 까닭을 글에서 찾아 함께 말해요.","answer":"O","reason_options":[{"t":"까닭을 함께 말해야 서로 다른 생각도 알아들을 수 있기 때문에","correct":true},{"t":"분위기는 느낌이라 까닭이 없어도 되기 때문에","mis":"K3-2-u2-X10"}],"mis":"K3-2-u2-X10","explanation":["분위기에는 까닭이 따라와요.","태오의 말없는 손길이 까닭이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#12','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C6',2,'mc','auto','“다음엔 같이 날리자.”를 읽는 목소리로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X12','K3-2-u2-X13']::text[],false,'{"seq":12,"concept":"K3-2-u2-C6","difficulty":2,"kind":"mc","stem":"“다음엔 같이 날리자.”를 읽는 목소리로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다정하고 따뜻한 목소리","correct":true},{"t":"화난 목소리","mis":"K3-2-u2-X12"},{"t":"쓸쓸한 목소리","mis":"K3-2-u2-X12"},{"t":"아주 큰 목소리","mis":"K3-2-u2-X13"}],"explanation":["태오가 남긴 말이에요.","은솔이를 챙겨 주는 마음이에요.","다정한 목소리가 어울려요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#13','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C7',2,'mc','auto','「태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.」를 장면이 떠오르게 읽은 것은 무엇인가요?',ARRAY['K3-2-u2-X05','K3-2-u2-X01','K3-2-u2-X04']::text[],false,'{"seq":13,"concept":"K3-2-u2-C7","difficulty":2,"kind":"mc","stem":"「태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.」를 장면이 떠오르게 읽은 것은 무엇인가요?","options":[{"t":"태오가∨긴 빗자루 손잡이로∨가지를 톡톡 치고 있었다.≡","correct":true},{"t":"태오가∨긴∨빗자루∨손잡이로∨가지를∨톡톡∨치고∨있었다.≡","mis":"K3-2-u2-X05"},{"t":"태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","mis":"K3-2-u2-X01"},{"t":"태오가 긴∨빗자루 손잡이로 가지를∨톡톡 치고 있었다.≡","mis":"K3-2-u2-X04"}],"explanation":["누가 · 무엇으로 · 무엇을 했는지 덩어리예요.","낱말마다 끊거나 덩어리를 깨면 흩어져요.","첫 번째가 장면이 떠올라요."],"asset":{"type":"passage","lines":["청소 시간, 창밖을 보던 은솔이는 눈을 동그랗게 떴다.","태오가 긴 빗자루 손잡이로 가지를 톡톡 치고 있었다.","비행기가 팔랑팔랑 내려와 태오 손에 앉았다.","태오는 아무 말 없이 비행기를 은솔이 책상에 올려 두었다.","날개 끝에 연필로 작게 적혀 있었다. “다음엔 같이 날리자.”","은솔이는 비행기를 가슴에 꼭 안았다."],"title":"이야기 「걸린 종이비행기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#14','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C12',2,'mc','auto','「책 빌리는 차례」를 우리 반 「도서관 약속판」에 붙이려고 해요. 가장 알맞게 고른 내용은 무엇인가요?',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":14,"concept":"K3-2-u2-C12","difficulty":2,"kind":"mc","stem":"「책 빌리는 차례」를 우리 반 「도서관 약속판」에 붙이려고 해요. 가장 알맞게 고른 내용은 무엇인가요?","options":[{"t":"빌린 책은 깨끗하게 보고 날짜에 맞추어 돌려준다","correct":true},{"t":"읽고 싶은 책을 고른다","mis":"K3-2-u2-X21"},{"t":"도서관에서 책을 빌리는 차례를 알려 드리겠습니다","mis":"K3-2-u2-X21"},{"t":"이름을 말하고 책을 내민다","mis":"K3-2-u2-X21"}],"explanation":["약속판에는 지킬 것을 붙여요.","빌린 뒤 지킬 일이에요.","깨끗이 보고 날짜에 돌려줘요."],"asset":{"type":"passage","lines":["도서관에서 책을 빌리는 차례를 알려 드리겠습니다.","첫째, 읽고 싶은 책을 골라 빌리는 곳으로 가져갑니다.","둘째, 내 이름을 말하고 책을 내밉니다.","셋째, 언제까지 돌려주어야 하는지 확인합니다.","빌린 책은 깨끗하게 보고 날짜에 맞추어 돌려줍니다."],"title":"서윤이의 발표 글 「책 빌리는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#15','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C11',2,'mc','auto','서윤이가 차례마다 그림에 번호를 붙인 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X23','K3-2-u2-X18','K3-2-u2-X19']::text[],false,'{"seq":15,"concept":"K3-2-u2-C11","difficulty":2,"kind":"mc","stem":"서윤이가 차례마다 그림에 번호를 붙인 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"무엇을 먼저 하고 다음에 할지 차례를 한눈에 보여 주려고","correct":true},{"t":"그림을 많아 보이게 하려고","mis":"K3-2-u2-X23"},{"t":"그림을 꾸미려고","mis":"K3-2-u2-X18"},{"t":"글을 안 쓰려고","mis":"K3-2-u2-X19"}],"explanation":["번호는 차례를 알려 줘요.","그림과 함께 보면 한눈에 보여요.","차례를 보여 주려고예요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 차례마다 번호를 붙인 그림 셋을 크게 그리고, 그림 아래에 짧게 글을 썼어."},{"who":"지안","text":"나는 차례를 글로 크게 쓰고, 옆에 작은 화살표 그림으로 이어 놓았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#16','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C15',2,'ox','auto','친구가 「연필깎이」를 설명할 때 끝까지 듣고 좋았던 곳을 말해 주는 것은 알맞은 듣기예요.',ARRAY['K3-2-u2-X26']::text[],false,'{"seq":16,"concept":"K3-2-u2-C15","difficulty":2,"kind":"ox","stem":"친구가 「연필깎이」를 설명할 때 끝까지 듣고 좋았던 곳을 말해 주는 것은 알맞은 듣기예요.","answer":"O","reason_options":[{"t":"끝까지 듣고 좋았던 곳을 말해 주면 발표한 친구에게 힘이 되기 때문에","correct":true},{"t":"내 차례를 준비하는 것이 더 중요하기 때문에","mis":"K3-2-u2-X26"}],"mis":"K3-2-u2-X26","explanation":["듣는 사람이 할 일이에요.","끝까지 들어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#17','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C1',3,'match','auto','읽는 모습과 듣는 사람에게 생기는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":17,"concept":"K3-2-u2-C1","difficulty":3,"kind":"match","stem":"읽는 모습과 듣는 사람에게 생기는 일을 알맞게 이으세요.","pairs":[{"l":"쉬지 않고 아주 빠르게 읽었다","r":"덩어리가 안 보여 무슨 말인지 놓쳤다"},{"l":"처음부터 끝까지 가장 큰 소리로 읽었다","r":"귀가 아파 내용보다 소리만 남았다"},{"l":"덩어리마다 쉬고 또박또박 읽었다","r":"연필깎이 쓰는 법이 또렷이 남았다"}],"mis":"K3-2-u2-X01","explanation":["듣는 사람 쪽에서 봐요.","빠르기 · 크기 · 덩어리를 견주어요.","뜻이 남은 것은 마지막이에요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#18','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C6',3,'error','auto','「걸린 종이비행기」 ①의 쓸쓸한 장면을 읽는 방법을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u2-X13']::text[],false,'{"seq":18,"concept":"K3-2-u2-C6","difficulty":3,"kind":"error","stem":"「걸린 종이비행기」 ①의 쓸쓸한 장면을 읽는 방법을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「쓸쓸하니까 아무도 못 듣게 아주 작게 읽어야 해.」","correct":true,"mis_target":"K3-2-u2-X13"},{"t":"친구 나 — 「한참 동안 올려다본 모습을 떠올리며 낮게 읽을래.」","mis":"K3-2-u2-X13"},{"t":"친구 다 — 「느리게 읽어도 낱말은 또렷이 들려야 해.」","mis":"K3-2-u2-X13"}],"explanation":["쓸쓸한 장면은 낮고 느리게 읽어요.","그래도 뜻은 들려야 해요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["점심시간, 은솔이는 새로 접은 종이비행기를 힘껏 날렸다.","비행기는 운동장 위를 빙글 돌며 멀리 날아갔다.","은솔이는 손뼉을 치며 그 뒤를 쫓아 달렸다.","그런데 비행기가 키 큰 나무의 가지 끝에 툭 걸리고 말았다.","은솔이는 나무 아래에 서서 한참 동안 가지만 올려다보았다.","종이 울리자 친구들은 하나둘 교실로 들어갔다."],"title":"이야기 「걸린 종이비행기」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#19','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C7',3,'ox','auto','「노란 조끼」를 읽을 때 장면이 떠오르게 읽으려면 「비가 오는 날에도,」에서 쉼표에 맞게 조금 쉬어 읽으면 좋아요.',ARRAY['K3-2-u2-X05']::text[],false,'{"seq":19,"concept":"K3-2-u2-C7","difficulty":3,"kind":"ox","stem":"「노란 조끼」를 읽을 때 장면이 떠오르게 읽으려면 「비가 오는 날에도,」에서 쉼표에 맞게 조금 쉬어 읽으면 좋아요.","answer":"O","reason_options":[{"t":"쉼표가 비 오는 날과 눈 쌓인 날을 나누어 두 장면이 차례로 떠오르게 하기 때문에","correct":true},{"t":"쉼표는 아무 뜻이 없어 그냥 지나치면 되기 때문에","mis":"K3-2-u2-X05"}],"mis":"K3-2-u2-X05","explanation":["문장 부호도 역할에 맞게 읽어요.","쉼표 앞뒤로 두 날이 나와요.","그래서 O예요."],"asset":{"type":"passage","lines":["해가 뜨기 전, 길 건너에 노란 조끼가 서 있다.","우리 학교 건널목을 지키는 분이다.","비가 오는 날에도, 눈이 쌓인 날에도 그 자리를 비운 적이 없다.","아이들이 뛰어오면 손을 들어 차를 세우고 어깨를 다독여 준다.","“천천히 와도 돼. 서두르지 않아도 돼.”"],"title":"글 「노란 조끼」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#20','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C12',3,'ox','auto','「책 빌리는 차례」를 이미 책을 잘 빌리는 6학년에게 알려 준다면, 1학년 동생에게 알려 줄 때와 넣을 내용이 달라질 수 있어요.',ARRAY['K3-2-u2-X21']::text[],false,'{"seq":20,"concept":"K3-2-u2-C12","difficulty":3,"kind":"ox","stem":"「책 빌리는 차례」를 이미 책을 잘 빌리는 6학년에게 알려 준다면, 1학년 동생에게 알려 줄 때와 넣을 내용이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"누구에게, 왜 알려 주는지에 따라 넣을 내용이 달라지기 때문에","correct":true},{"t":"같은 글이면 넣을 내용도 언제나 같기 때문에","mis":"K3-2-u2-X21"}],"mis":"K3-2-u2-X21","explanation":["듣는 사람이 다르면 목적도 달라요.","목적이 달라지면 내용도 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["도서관에서 책을 빌리는 차례를 알려 드리겠습니다.","첫째, 읽고 싶은 책을 골라 빌리는 곳으로 가져갑니다.","둘째, 내 이름을 말하고 책을 내밉니다.","셋째, 언제까지 돌려주어야 하는지 확인합니다.","빌린 책은 깨끗하게 보고 날짜에 맞추어 돌려줍니다."],"title":"서윤이의 발표 글 「책 빌리는 차례」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#21','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C14',3,'ox','auto','서윤이와 지안이 자료 가운데 하나를 우리 반 모범 자료로 정해 모두 똑같이 만들게 하는 것이 좋아요.',ARRAY['K3-2-u2-X24']::text[],false,'{"seq":21,"concept":"K3-2-u2-C14","difficulty":3,"kind":"ox","stem":"서윤이와 지안이 자료 가운데 하나를 우리 반 모범 자료로 정해 모두 똑같이 만들게 하는 것이 좋아요.","answer":"X","reason_options":[{"t":"같은 내용이라도 표현과 배치가 다를 수 있고 전하려는 것이 잘 보이면 모두 알맞기 때문에","correct":true},{"t":"모범 자료는 언제나 하나뿐이기 때문에","mis":"K3-2-u2-X24"}],"mis":"K3-2-u2-X24","explanation":["모범 자료가 하나면 다른 방법이 사라져요.","둘 다 차례가 잘 보였어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 차례마다 번호를 붙인 그림 셋을 크게 그리고, 그림 아래에 짧게 글을 썼어."},{"who":"지안","text":"나는 차례를 글로 크게 쓰고, 옆에 작은 화살표 그림으로 이어 놓았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#22','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C16',3,'match','auto','문장과 띄어쓰기 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":22,"concept":"K3-2-u2-C16","difficulty":3,"kind":"match","stem":"문장과 띄어쓰기 까닭을 알맞게 이으세요.","pairs":[{"l":"통을 비울 줄 안다.","r":"‘줄’이 앞말에 기대어 띄어 쓴다"},{"l":"줄넘기를 했다.","r":"‘줄’이 한 낱말 속에 있어 붙여 쓴다"},{"l":"찌꺼기를 버릴 것.","r":"‘것’이 앞말에 기대어 띄어 쓴다"}],"mis":"K3-2-u2-X28","explanation":["‘것·수·줄’이 혼자 떨어져 있나 봐요.","줄넘기는 한 낱말이에요.","까닭과 짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#23','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C14',4,'mc','auto','서윤이는 「그림이 커야 동생들이 좋아해」, 지안이는 「글이 커야 차례를 정확히 알아」라고 다투었어요. 두 친구에게 할 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u2-X24','K3-2-u2-X25']::text[],false,'{"seq":23,"concept":"K3-2-u2-C14","difficulty":4,"kind":"mc","stem":"서윤이는 「그림이 커야 동생들이 좋아해」, 지안이는 「글이 커야 차례를 정확히 알아」라고 다투었어요. 두 친구에게 할 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“둘 다 차례가 잘 보이니 알맞아. 서로 잘한 곳을 말하고 더 잘 보이게 할 방법을 나눠 보자.”","correct":true},{"t":"“그림이 큰 쪽이 언제나 이겨.”","mis":"K3-2-u2-X24"},{"t":"“글이 많은 쪽이 언제나 이겨.”","mis":"K3-2-u2-X24"},{"t":"“둘 다 틀렸으니 선생님이 하나로 정해 주실 거야.”","mis":"K3-2-u2-X25"}],"explanation":["나타내는 방법은 여러 가지예요.","어느 쪽이 이기는 일이 아니에요.","잘한 곳과 방법을 나눠요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"나는 차례마다 번호를 붙인 그림 셋을 크게 그리고, 그림 아래에 짧게 글을 썼어."},{"who":"지안","text":"나는 차례를 글로 크게 쓰고, 옆에 작은 화살표 그림으로 이어 놓았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#24','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C16',4,'essay','teacher','「연필깎이」 내용을 써서 ‘것’, ‘수’, ‘줄’이 들어간 문장을 하나씩 만들고, 「수요일」이나 「줄넘기」처럼 붙여 쓰는 낱말도 하나 넣은 문장을 만든 뒤, 띄어 쓰고 붙여 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u2-C16","difficulty":4,"kind":"essay","stem":"「연필깎이」 내용을 써서 ‘것’, ‘수’, ‘줄’이 들어간 문장을 하나씩 만들고, 「수요일」이나 「줄넘기」처럼 붙여 쓰는 낱말도 하나 넣은 문장을 만든 뒤, 띄어 쓰고 붙여 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 통이 차면 비울 것. 연필을 끝까지 넣어야 잘 깎을 수 있다. 나는 연필깎이를 쓸 줄 안다. 수요일마다 통을 비운다. ‘것·수·줄’은 혼자 쓰이지 못하고 앞말에 기대어 쓰이므로 띄어 썼다. 「수요일」의 ‘수’는 한 낱말 속에 있어 붙여 썼다.","scoring_points":["‘것·수·줄’ 문장을 하나씩 바르게 띄어 썼는가","붙여 쓰는 낱말이 든 문장을 썼는가","띄어 쓰고 붙여 쓴 까닭을 썼는가"]},"explanation":["‘것·수·줄’마다 문장을 만들어요.","앞말과 띄어 써요.","한 낱말 속은 붙여 써요."],"asset":{"type":"passage","lines":["연필깎이는 연필을 뾰족하게 깎아 주는 물건입니다.","연필을 구멍에 끝까지 넣고 손잡이를 돌립니다.","연필심이 뾰족해지면 돌리기를 멈춥니다.","너무 오래 돌리면 연필이 금방 짧아집니다.","깎고 나온 찌꺼기는 아래 통에 모입니다.","그래서 통이 가득 차면 열어서 쓰레기통에 비워야 합니다."],"title":"설명하는 글 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u2_review_d#25','kor',3,2,'u2','','g3_2_kor_u2_review_d','unit_review','K3-2-u2-C6',4,'essay','teacher','「말린 실내화」나 「걸린 종이비행기」 가운데 하나를 골라 친구에게 읽어 준다고 생각하고, 장면 하나를 정해 분위기를 살려 읽을 방법을 상황·표정과 몸짓·목소리로 나누어 쓰세요. 친구가 다르게 읽는다면 어떻게 볼지도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u2-C6","difficulty":4,"kind":"essay","stem":"「말린 실내화」나 「걸린 종이비행기」 가운데 하나를 골라 친구에게 읽어 준다고 생각하고, 장면 하나를 정해 분위기를 살려 읽을 방법을 상황·표정과 몸짓·목소리로 나누어 쓰세요. 친구가 다르게 읽는다면 어떻게 볼지도 쓰세요.","answer_guide":{"answer":"예: 「걸린 종이비행기」에서 혼자 가지를 올려다본 장면. 상황 — 친구들이 다 들어간 텅 빈 운동장을 떠올리며 읽는다. 표정과 몸짓 — 고개를 들어 위를 올려다보는 몸짓을 한다. 목소리 — 낮고 느리게, 그래도 낱말은 또렷이 읽는다. 친구가 쉬는 곳을 더 두고 읽어도 쓸쓸한 마음이 전해지면 그것도 알맞다고 보겠다.","scoring_points":["장면을 하나 정했는가","상황·표정과 몸짓·목소리로 나누어 읽을 방법을 썼는가","다르게 읽어도 알맞을 수 있다고 썼는가"]},"explanation":["장면부터 정해요.","읽는 방법 셋으로 나누어요.","방법은 하나가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
